BEGIN;
DO $$DECLARE role_name text;encoded text;password_value text;BEGIN
 FOR role_name,encoded IN SELECT*FROM(VALUES('salesflow_owner','__MIGRATION_PASSWORD_B64__'),('salesflow_runtime','__WORKFLOW_DB_PASSWORD_B64__'),('n8n_internal','__N8N_DB_PASSWORD_B64__'))x(role_name,encoded)LOOP
  BEGIN password_value:=convert_from(decode(encoded,'base64'),'UTF8');EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION'invalid encoded password for role %',role_name;END;
  IF COALESCE(password_value,'')=''THEN RAISE EXCEPTION'empty password for role %',role_name;END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=role_name)THEN EXECUTE format('CREATE ROLE %I NOLOGIN NOINHERIT',role_name);END IF;
  EXECUTE format('ALTER ROLE %I LOGIN PASSWORD %L NOINHERIT',role_name,password_value);
 END LOOP;
END$$;
DO $$BEGIN EXECUTE format('GRANT CONNECT ON DATABASE %I TO salesflow_owner,salesflow_runtime,n8n_internal',current_database());EXECUTE format('GRANT CREATE ON DATABASE %I TO n8n_internal',current_database());END$$;
GRANT USAGE,CREATE ON SCHEMA public TO n8n_internal;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS salesflow AUTHORIZATION salesflow_owner;
ALTER SCHEMA salesflow OWNER TO salesflow_owner;
SET ROLE salesflow_owner;
SET search_path=salesflow,public;

CREATE TABLE IF NOT EXISTS accounts(id text PRIMARY KEY,enabled bool NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS config_docs(account_ref text NOT NULL REFERENCES accounts(id),kind text NOT NULL,version text NOT NULL,body jsonb NOT NULL,active bool NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(account_ref,kind,version));
CREATE UNIQUE INDEX IF NOT EXISTS config_one_active ON config_docs(account_ref,kind)WHERE active;
CREATE TABLE IF NOT EXISTS controls(account_ref text NOT NULL REFERENCES accounts(id),key text NOT NULL,value jsonb NOT NULL,PRIMARY KEY(account_ref,key));
CREATE TABLE IF NOT EXISTS auth_tokens(hash text PRIMARY KEY,role text NOT NULL CHECK(role IN('owner','runtime','operator','scheduler')),account_ref text REFERENCES accounts(id),actor text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval'24 hours',revoked_at timestamptz);
ALTER TABLE auth_tokens ADD COLUMN IF NOT EXISTS expires_at timestamptz NOT NULL DEFAULT now()+interval'24 hours';
ALTER TABLE auth_tokens ADD COLUMN IF NOT EXISTS revoked_at timestamptz;
CREATE TABLE IF NOT EXISTS contacts(account_ref text NOT NULL REFERENCES accounts(id),id uuid NOT NULL DEFAULT gen_random_uuid(),locale text NOT NULL DEFAULT'en',PRIMARY KEY(account_ref,id));
CREATE TABLE IF NOT EXISTS contact_identifiers(account_ref text NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),contact_id uuid NOT NULL,channel text NOT NULL,provider text NOT NULL,external_ref text NOT NULL,external_ref_hash text NOT NULL,active bool NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),retired_at timestamptz,PRIMARY KEY(account_ref,id),UNIQUE(account_ref,channel,provider,external_ref_hash),FOREIGN KEY(account_ref,contact_id)REFERENCES contacts(account_ref,id),CHECK(COALESCE(btrim(channel),'')<>''AND COALESCE(btrim(provider),'')<>''AND COALESCE(btrim(external_ref),'')<>''AND external_ref_hash~'^[0-9a-f]{64}$'),CHECK((active AND retired_at IS NULL)OR(NOT active AND retired_at IS NOT NULL)));
ALTER TABLE contact_identifiers ADD COLUMN IF NOT EXISTS external_ref_hash text;
UPDATE contact_identifiers SET external_ref_hash=encode(digest(external_ref,'sha256'),'hex')WHERE external_ref_hash IS NULL;
ALTER TABLE contact_identifiers ALTER COLUMN external_ref_hash SET NOT NULL;
DO $$DECLARE n name;BEGIN SELECT conname INTO n FROM pg_constraint WHERE conrelid='contact_identifiers'::regclass AND contype='u'AND pg_get_constraintdef(oid)='UNIQUE (account_ref, channel, provider, external_ref)';IF n IS NOT NULL THEN EXECUTE format('ALTER TABLE contact_identifiers DROP CONSTRAINT %I',n);END IF;END$$;
DROP INDEX IF EXISTS contact_identifiers_history_unique;
DO $$BEGIN IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='salesflow'AND table_name='contacts'AND column_name='external_ref')THEN EXECUTE'INSERT INTO contact_identifiers(account_ref,contact_id,channel,provider,external_ref,external_ref_hash)SELECT account_ref,id,''whatsapp'',''meta'',external_ref,encode(digest(external_ref,''sha256''),''hex'')FROM contacts WHERE external_ref IS DISTINCT FROM ''deleted-''||id::text ON CONFLICT(account_ref,channel,provider,external_ref_hash)DO NOTHING';END IF;END$$;
ALTER TABLE contacts DROP COLUMN IF EXISTS external_ref;
CREATE TABLE IF NOT EXISTS consent_events(account_ref text NOT NULL,contact_id uuid NOT NULL,status text NOT NULL CHECK(status IN('granted','revoked')),evidence text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(account_ref,contact_id,occurred_at),FOREIGN KEY(account_ref,contact_id)REFERENCES contacts(account_ref,id));
CREATE TABLE IF NOT EXISTS conversations(account_ref text NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(),contact_id uuid NOT NULL,lifecycle text NOT NULL DEFAULT'active',owner text NOT NULL DEFAULT'ai',version bigint NOT NULL DEFAULT 0,last_seq bigint NOT NULL DEFAULT 0,campaign bool NOT NULL DEFAULT true,PRIMARY KEY(account_ref,id),UNIQUE(account_ref,contact_id),FOREIGN KEY(account_ref,contact_id)REFERENCES contacts(account_ref,id));
CREATE OR REPLACE FUNCTION normalize_inbound_body(raw text)RETURNS text LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$SELECT regexp_replace(replace(replace(normalize(raw,NFC),E'\r\n',E'\n'),E'\r',E'\n'),'^[[:space:]]+|[[:space:]]+$','','g')$$;
CREATE TABLE IF NOT EXISTS inbound_messages(account_ref text NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL,provider_id text NOT NULL,contact_ref text NOT NULL,body text NOT NULL,processing_body text NOT NULL,body_hash text NOT NULL,received_at timestamptz NOT NULL,seq bigint NOT NULL,PRIMARY KEY(account_ref,id),UNIQUE(account_ref,provider_id),UNIQUE(account_ref,conversation_id,seq),FOREIGN KEY(account_ref,conversation_id)REFERENCES conversations(account_ref,id));
ALTER TABLE inbound_messages ADD COLUMN IF NOT EXISTS processing_body text;
UPDATE inbound_messages SET processing_body=normalize_inbound_body(body)WHERE processing_body IS NULL;
ALTER TABLE inbound_messages ALTER COLUMN processing_body SET NOT NULL;
CREATE TABLE IF NOT EXISTS turns(account_ref text NOT NULL,inbound_id uuid NOT NULL,conversation_id uuid NOT NULL,state text NOT NULL DEFAULT'pending',claim uuid,claim_until timestamptz,attempts int NOT NULL DEFAULT 0,result jsonb,PRIMARY KEY(account_ref,inbound_id),FOREIGN KEY(account_ref,inbound_id)REFERENCES inbound_messages(account_ref,id));
CREATE TABLE IF NOT EXISTS intents(account_ref text NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),contact_id uuid NOT NULL,conversation_id uuid NOT NULL,source_id uuid NOT NULL,kind text NOT NULL,expected_version bigint NOT NULL,policy_version text NOT NULL,knowledge_version text NOT NULL,body text NOT NULL,template_key text,provenance jsonb NOT NULL,state text NOT NULL DEFAULT'pending',reason text,lease uuid,lease_until timestamptz,attempts int NOT NULL DEFAULT 0,next_attempt timestamptz,provider_id text,provider_status text,provider_time timestamptz,PRIMARY KEY(account_ref,id),UNIQUE(account_ref,conversation_id,source_id,kind),UNIQUE(account_ref,provider_id),FOREIGN KEY(account_ref,contact_id)REFERENCES contacts(account_ref,id),FOREIGN KEY(account_ref,conversation_id)REFERENCES conversations(account_ref,id));
CREATE TABLE IF NOT EXISTS intent_transitions(id bigserial PRIMARY KEY,account_ref text NOT NULL,intent_id uuid NOT NULL,from_state text,to_state text NOT NULL,reason text NOT NULL,at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(account_ref,intent_id)REFERENCES intents(account_ref,id));
CREATE TABLE IF NOT EXISTS provider_calls(account_ref text NOT NULL,intent_id uuid NOT NULL,attempt_no int NOT NULL,lease uuid NOT NULL,provider_id text NOT NULL,correlation_id uuid NOT NULL DEFAULT gen_random_uuid(),release_set_version text NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(account_ref,intent_id),UNIQUE(account_ref,provider_id),FOREIGN KEY(account_ref,intent_id)REFERENCES intents(account_ref,id),CHECK(attempt_no>0));
CREATE TABLE IF NOT EXISTS provider_call_events(id bigserial PRIMARY KEY,account_ref text NOT NULL,intent_id uuid NOT NULL,event_key text NOT NULL,event_type text NOT NULL CHECK(event_type IN('started','accepted','failed','ambiguous','reconciliation_required','reconciled')),reason text NOT NULL,details jsonb NOT NULL DEFAULT'{}',at timestamptz NOT NULL DEFAULT now(),UNIQUE(account_ref,intent_id,event_key),FOREIGN KEY(account_ref,intent_id)REFERENCES provider_calls(account_ref,intent_id));
CREATE TABLE IF NOT EXISTS provider_events(account_ref text NOT NULL,event_id text NOT NULL,intent_id uuid NOT NULL,provider_id text NOT NULL,status text NOT NULL CHECK(status IN('accepted','sent','delivered','read','failed')),provider_time timestamptz NOT NULL,payload_hash text NOT NULL,PRIMARY KEY(account_ref,event_id),FOREIGN KEY(account_ref,intent_id)REFERENCES intents(account_ref,id));
WITH moved AS(UPDATE intents SET state='pending',reason='migration_pre_call_requeued',lease=NULL,lease_until=NULL WHERE state='leased'AND NOT EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(intents.account_ref,intents.id))RETURNING account_ref,id)INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)SELECT account_ref,id,'leased','pending','migration_pre_call_requeued'FROM moved;
UPDATE intents SET provider_id='synthetic-'||id WHERE state IN('sent','failed')AND provider_id IS NULL AND COALESCE(reason,'')NOT IN('migration_unknown_without_call_record','retry_exhausted');
INSERT INTO provider_calls(account_ref,intent_id,attempt_no,lease,provider_id,release_set_version,started_at)SELECT i.account_ref,i.id,GREATEST(i.attempts,1),COALESCE(i.lease,gen_random_uuid()),i.provider_id,COALESCE(i.provenance#>>'{context,releaseSetVersion}','legacy'),COALESCE(i.provider_time,now())FROM intents i WHERE i.state IN('sent','failed')AND i.provider_id IS NOT NULL AND COALESCE(i.reason,'')<>'retry_exhausted'ON CONFLICT(account_ref,intent_id)DO NOTHING;
INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason,at)SELECT pc.account_ref,pc.intent_id,'started','started','migration_backfill',pc.started_at FROM provider_calls pc ON CONFLICT DO NOTHING;
INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason,at)SELECT pc.account_ref,pc.intent_id,'migration-current-state',CASE i.state WHEN'sent'THEN'accepted'WHEN'failed'THEN'failed'ELSE'reconciliation_required'END,COALESCE(i.reason,'migration_backfill'),COALESCE(i.provider_time,now())FROM provider_calls pc JOIN intents i ON(i.account_ref,i.id)=(pc.account_ref,pc.intent_id)WHERE i.state IN('sent','failed','reconciliation_required')ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS followups(account_ref text NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),contact_id uuid NOT NULL,conversation_id uuid NOT NULL,due_at timestamptz NOT NULL,expected_version bigint NOT NULL,template_key text NOT NULL DEFAULT'followup-en',state text NOT NULL DEFAULT'due',claim uuid,claim_until timestamptz,attempts int NOT NULL DEFAULT 0,next_attempt timestamptz,intent_id uuid,reason text,PRIMARY KEY(account_ref,id),FOREIGN KEY(account_ref,contact_id)REFERENCES contacts(account_ref,id),FOREIGN KEY(account_ref,conversation_id)REFERENCES conversations(account_ref,id));
CREATE TABLE IF NOT EXISTS handoffs(account_ref text NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),contact_id uuid NOT NULL,conversation_id uuid NOT NULL,source_id uuid NOT NULL,reason text NOT NULL,queue text NOT NULL,deadline timestamptz NOT NULL,evidence jsonb NOT NULL,state text NOT NULL DEFAULT'pending',claim uuid,claim_until timestamptz,attempts int NOT NULL DEFAULT 0,next_attempt timestamptz,PRIMARY KEY(account_ref,id),UNIQUE(account_ref,source_id),FOREIGN KEY(account_ref,contact_id)REFERENCES contacts(account_ref,id),FOREIGN KEY(account_ref,conversation_id)REFERENCES conversations(account_ref,id),FOREIGN KEY(account_ref,source_id)REFERENCES inbound_messages(account_ref,id));
CREATE TABLE IF NOT EXISTS handoff_summaries(account_ref text NOT NULL,handoff_id uuid NOT NULL,conversation_id uuid NOT NULL,source_id uuid NOT NULL,reason text NOT NULL,urgency text NOT NULL,deadline timestamptz NOT NULL,known_lead_details jsonb NOT NULL,remaining_unknowns jsonb NOT NULL,relevant_offer text NOT NULL,sales_policy_version text NOT NULL,conversation_url text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(account_ref,handoff_id),UNIQUE(account_ref,source_id),FOREIGN KEY(account_ref,handoff_id)REFERENCES handoffs(account_ref,id),FOREIGN KEY(account_ref,conversation_id)REFERENCES conversations(account_ref,id),FOREIGN KEY(account_ref,source_id)REFERENCES inbound_messages(account_ref,id),CHECK(reason IN('human_requested','qualification_threshold','grounding_invalid','unknown')),CHECK(urgency='respond_by_deadline'),CHECK(jsonb_typeof(known_lead_details)='array'),CHECK(jsonb_typeof(remaining_unknowns)='array'),CHECK(COALESCE(btrim(relevant_offer),'')<>''),CHECK(COALESCE(btrim(sales_policy_version),'')<>''),CHECK(conversation_url!~*'(token|secret|authorization)='));
CREATE TABLE IF NOT EXISTS handoff_notification_events(account_ref text NOT NULL,handoff_id uuid NOT NULL,attempt_no int NOT NULL,outcome text,result text NOT NULL,next_attempt timestamptz,at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(account_ref,handoff_id,attempt_no),FOREIGN KEY(account_ref,handoff_id)REFERENCES handoffs(account_ref,id),CHECK(attempt_no>0),CHECK(outcome IS NULL OR outcome IN('success','retryable','failed')),CHECK(result IN('delivered','retry_scheduled','final_failure','retry_exhausted','authority_changed')));
CREATE TABLE IF NOT EXISTS handoff_notification_attempts(account_ref text NOT NULL,handoff_id uuid NOT NULL,attempt_no int NOT NULL,claim uuid NOT NULL,started_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(account_ref,handoff_id,attempt_no),UNIQUE(account_ref,handoff_id,claim),FOREIGN KEY(account_ref,handoff_id)REFERENCES handoffs(account_ref,id),CHECK(attempt_no>0));
CREATE TABLE IF NOT EXISTS deletion_requests(account_ref text NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),contact_id uuid NOT NULL,state text NOT NULL DEFAULT'pending',created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,PRIMARY KEY(account_ref,id),FOREIGN KEY(account_ref,contact_id)REFERENCES contacts(account_ref,id));
CREATE TABLE IF NOT EXISTS deletion_targets(account_ref text NOT NULL,request_id uuid NOT NULL,target_type text NOT NULL,target_id text NOT NULL,state text NOT NULL,PRIMARY KEY(account_ref,request_id,target_type,target_id),FOREIGN KEY(account_ref,request_id)REFERENCES deletion_requests(account_ref,id));
CREATE TABLE IF NOT EXISTS releases(account_ref text NOT NULL,id text NOT NULL,manifest_hash text NOT NULL,manifest jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(account_ref,id));
ALTER TABLE releases DROP COLUMN IF EXISTS active;
DROP INDEX IF EXISTS release_one_active;
CREATE TABLE IF NOT EXISTS release_pointers(account_ref text PRIMARY KEY REFERENCES accounts(id),release_id text NOT NULL,manifest_hash text NOT NULL,FOREIGN KEY(account_ref,release_id)REFERENCES releases(account_ref,id));
CREATE TABLE IF NOT EXISTS audit_events(id bigserial PRIMARY KEY,account_ref text REFERENCES accounts(id),event text NOT NULL,reason text NOT NULL,actor text NOT NULL,details jsonb NOT NULL DEFAULT'{}',at timestamptz NOT NULL DEFAULT now());

DO $$BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='conversations_lifecycle_check'AND conrelid='conversations'::regclass)THEN ALTER TABLE conversations ADD CONSTRAINT conversations_lifecycle_check CHECK(lifecycle IN('active','opted_out','deleted'));END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='conversations_owner_check'AND conrelid='conversations'::regclass)THEN ALTER TABLE conversations ADD CONSTRAINT conversations_owner_check CHECK(owner IN('ai','human'));END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='inbound_messages_seq_positive'AND conrelid='inbound_messages'::regclass)THEN ALTER TABLE inbound_messages ADD CONSTRAINT inbound_messages_seq_positive CHECK(seq>0);END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='inbound_messages_processing_body_matches'AND conrelid='inbound_messages'::regclass)THEN ALTER TABLE inbound_messages ADD CONSTRAINT inbound_messages_processing_body_matches CHECK(processing_body=normalize_inbound_body(body));END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='turns_state_check'AND conrelid='turns'::regclass)THEN ALTER TABLE turns ADD CONSTRAINT turns_state_check CHECK(state IN('pending','claimed','completed','suppressed'));END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='intents_kind_check'AND conrelid='intents'::regclass)THEN ALTER TABLE intents ADD CONSTRAINT intents_kind_check CHECK(kind IN('reply','followup','handoff_ack'));END IF;
 IF EXISTS(SELECT 1 FROM pg_constraint WHERE conname='intents_state_check'AND conrelid='intents'::regclass)THEN ALTER TABLE intents DROP CONSTRAINT intents_state_check;END IF;ALTER TABLE intents ADD CONSTRAINT intents_state_check CHECK(state IN('pending','leased','provider_call_started','sent','failed','retry','suppressed','reconciliation_required'));
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='intents_provider_status_check'AND conrelid='intents'::regclass)THEN ALTER TABLE intents ADD CONSTRAINT intents_provider_status_check CHECK(provider_status IS NULL OR provider_status IN('accepted','sent','delivered','read','failed'));END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='followups_state_check'AND conrelid='followups'::regclass)THEN ALTER TABLE followups ADD CONSTRAINT followups_state_check CHECK(state IN('due','claimed','retry','intent_created','call_started','reconciliation_required','sent','delivered','failed','cancelled','superseded','denied','exhausted','suppressed','legacy_unverifiable'));END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='handoffs_state_check'AND conrelid='handoffs'::regclass)THEN ALTER TABLE handoffs ADD CONSTRAINT handoffs_state_check CHECK(state IN('pending','claimed','acknowledged','suppressed'));END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='deletion_requests_state_check'AND conrelid='deletion_requests'::regclass)THEN ALTER TABLE deletion_requests ADD CONSTRAINT deletion_requests_state_check CHECK(state IN('pending','completed'));END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='deletion_targets_state_check'AND conrelid='deletion_targets'::regclass)THEN ALTER TABLE deletion_targets ADD CONSTRAINT deletion_targets_state_check CHECK(state IN('pending','completed'));END IF;
END$$;
ALTER TABLE handoff_notification_events ALTER COLUMN outcome DROP NOT NULL;
ALTER TABLE handoff_notification_events DROP CONSTRAINT IF EXISTS handoff_notification_events_outcome_check;
ALTER TABLE handoff_notification_events ADD CONSTRAINT handoff_notification_events_outcome_check CHECK(outcome IS NULL OR outcome IN('success','retryable','failed'));
ALTER TABLE handoff_notification_events DROP CONSTRAINT IF EXISTS handoff_notification_events_result_check;
ALTER TABLE handoff_notification_events ADD CONSTRAINT handoff_notification_events_result_check CHECK(result IN('delivered','retry_scheduled','final_failure','retry_exhausted','authority_changed'));

CREATE OR REPLACE FUNCTION immutable()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION'append-only';END$$;
CREATE OR REPLACE FUNCTION handoff_summary_immutable_guard()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF TG_OP='UPDATE'AND(current_setting('salesflow.deletion_mode',true)='on'OR current_setting('salesflow.retention_mode',true)='on')AND current_setting('salesflow.minimization_account',true)=OLD.account_ref AND(NEW.account_ref,NEW.handoff_id,NEW.conversation_id,NEW.source_id,NEW.reason,NEW.urgency,NEW.deadline,NEW.remaining_unknowns,NEW.relevant_offer,NEW.sales_policy_version,NEW.conversation_url,NEW.created_at)IS NOT DISTINCT FROM(OLD.account_ref,OLD.handoff_id,OLD.conversation_id,OLD.source_id,OLD.reason,OLD.urgency,OLD.deadline,OLD.remaining_unknowns,OLD.relevant_offer,OLD.sales_policy_version,OLD.conversation_url,OLD.created_at)AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.known_lead_details)x WHERE x->>'excerpt'IS DISTINCT FROM'[deleted]')THEN RETURN NEW;ELSIF TG_OP='UPDATE'AND current_setting('salesflow.summary_migration',true)='on'AND(NEW.account_ref,NEW.handoff_id,NEW.conversation_id,NEW.source_id,NEW.reason,NEW.urgency,NEW.deadline,NEW.known_lead_details,NEW.remaining_unknowns,NEW.relevant_offer,NEW.sales_policy_version,NEW.created_at)IS NOT DISTINCT FROM(OLD.account_ref,OLD.handoff_id,OLD.conversation_id,OLD.source_id,OLD.reason,OLD.urgency,OLD.deadline,OLD.known_lead_details,OLD.remaining_unknowns,OLD.relevant_offer,OLD.sales_policy_version,OLD.created_at)AND NEW.conversation_url='/webhook/salesflow/handoff?view=conversation&conversation_id='||OLD.conversation_id THEN RETURN NEW;END IF;RAISE EXCEPTION'handoff summary immutable';END$$;
DROP TRIGGER IF EXISTS handoff_summary_immutable ON handoff_summaries;CREATE TRIGGER handoff_summary_immutable BEFORE UPDATE OR DELETE ON handoff_summaries FOR EACH ROW EXECUTE FUNCTION handoff_summary_immutable_guard();
DROP TRIGGER IF EXISTS handoff_notification_event_immutable ON handoff_notification_events;CREATE TRIGGER handoff_notification_event_immutable BEFORE UPDATE OR DELETE ON handoff_notification_events FOR EACH ROW EXECUTE FUNCTION immutable();
DROP TRIGGER IF EXISTS handoff_notification_attempt_immutable ON handoff_notification_attempts;CREATE TRIGGER handoff_notification_attempt_immutable BEFORE UPDATE OR DELETE ON handoff_notification_attempts FOR EACH ROW EXECUTE FUNCTION immutable();
ALTER TABLE handoff_notification_attempts ALTER COLUMN started_at DROP NOT NULL;
INSERT INTO handoff_notification_attempts(account_ref,handoff_id,attempt_no,claim,started_at)SELECT account_ref,id,attempts,claim,NULL FROM handoffs WHERE state='claimed'AND claim IS NOT NULL AND attempts>0 ON CONFLICT DO NOTHING;
SELECT set_config('salesflow.summary_migration','on',true);UPDATE handoff_summaries SET conversation_url='/webhook/salesflow/handoff?view=conversation&conversation_id='||conversation_id WHERE conversation_url IS DISTINCT FROM'/webhook/salesflow/handoff?view=conversation&conversation_id='||conversation_id;SELECT set_config('salesflow.summary_migration','off',true);
INSERT INTO handoff_summaries(account_ref,handoff_id,conversation_id,source_id,reason,urgency,deadline,known_lead_details,remaining_unknowns,relevant_offer,sales_policy_version,conversation_url,created_at)
SELECT h.account_ref,h.id,h.conversation_id,h.source_id,CASE WHEN h.reason IN('human_requested','qualification_threshold','grounding_invalid')THEN h.reason ELSE'unknown'END,'respond_by_deadline',h.deadline,'[]','["unknown"]','none','unknown','/webhook/salesflow/handoff?view=conversation&conversation_id='||h.conversation_id,h.deadline-make_interval(secs=>300)
FROM handoffs h LEFT JOIN handoff_summaries s ON(s.account_ref,s.handoff_id)=(h.account_ref,h.id)WHERE s.handoff_id IS NULL ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION config_immutable_guard()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF TG_OP='UPDATE'AND current_setting('salesflow.config_activation',true)='on'AND NEW.account_ref IS NOT DISTINCT FROM OLD.account_ref AND NEW.kind IS NOT DISTINCT FROM OLD.kind AND NEW.version IS NOT DISTINCT FROM OLD.version AND NEW.body IS NOT DISTINCT FROM OLD.body AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at THEN RETURN NEW;END IF;RAISE EXCEPTION'config version immutable';END$$;
CREATE OR REPLACE FUNCTION provider_immutable_guard()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF TG_OP='UPDATE'AND current_setting('salesflow.deletion_mode',true)='on'AND NEW.account_ref=OLD.account_ref AND NEW.event_id=OLD.event_id AND NEW.intent_id=OLD.intent_id AND NEW.status=OLD.status AND NEW.provider_time=OLD.provider_time AND NEW.provider_id LIKE'deleted-%'THEN RETURN NEW;END IF;RAISE EXCEPTION'append-only';END$$;
CREATE OR REPLACE FUNCTION provider_call_immutable_guard()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF TG_OP='UPDATE'AND current_setting('salesflow.deletion_mode',true)='on'AND(NEW.account_ref,NEW.intent_id,NEW.attempt_no,NEW.lease,NEW.correlation_id,NEW.release_set_version,NEW.started_at)IS NOT DISTINCT FROM(OLD.account_ref,OLD.intent_id,OLD.attempt_no,OLD.lease,OLD.correlation_id,OLD.release_set_version,OLD.started_at)AND NEW.provider_id='deleted-'||OLD.intent_id::text THEN RETURN NEW;END IF;RAISE EXCEPTION'append-only';END$$;
CREATE OR REPLACE FUNCTION contact_identifier_immutable_guard()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF TG_OP='UPDATE'AND(NEW.account_ref,NEW.id,NEW.contact_id,NEW.channel,NEW.provider,NEW.external_ref_hash,NEW.created_at)IS NOT DISTINCT FROM(OLD.account_ref,OLD.id,OLD.contact_id,OLD.channel,OLD.provider,OLD.external_ref_hash,OLD.created_at)AND((NEW.external_ref IS NOT DISTINCT FROM OLD.external_ref AND((NEW.active,NEW.retired_at)IS NOT DISTINCT FROM(OLD.active,OLD.retired_at)OR(OLD.active AND NOT NEW.active AND OLD.retired_at IS NULL AND NEW.retired_at IS NOT NULL)))OR(current_setting('salesflow.deletion_mode',true)='on'AND NEW.external_ref='deleted-'||OLD.id::text AND NOT NEW.active AND NEW.retired_at IS NOT NULL))THEN RETURN NEW;END IF;RAISE EXCEPTION'contact identifier immutable';END$$;
CREATE OR REPLACE FUNCTION assign_inbound_message_sequence()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN PERFORM followup_lock_conversation(NEW.account_ref,NEW.conversation_id);UPDATE conversations SET last_seq=last_seq+1,version=version+1 WHERE(account_ref,id)=(NEW.account_ref,NEW.conversation_id)RETURNING last_seq INTO NEW.seq;IF NOT FOUND THEN RAISE EXCEPTION'conversation not found' USING ERRCODE='23503';END IF;RETURN NEW;END$$;
CREATE OR REPLACE FUNCTION inbound_message_order_guard()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF TG_OP='DELETE'THEN RAISE EXCEPTION'inbound message immutable';END IF;IF NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW;END IF;IF(current_setting('salesflow.deletion_mode',true)='on'OR current_setting('salesflow.retention_mode',true)='on')AND current_setting('salesflow.minimization_account',true)=OLD.account_ref AND(NEW.account_ref,NEW.id,NEW.conversation_id,NEW.provider_id,NEW.received_at,NEW.seq)IS NOT DISTINCT FROM(OLD.account_ref,OLD.id,OLD.conversation_id,OLD.provider_id,OLD.received_at,OLD.seq)AND NEW.contact_ref='[deleted]'AND NEW.body='[deleted]'AND NEW.processing_body='[deleted]'AND NEW.body_hash=encode(digest('[deleted]','sha256'),'hex')THEN RETURN NEW;END IF;RAISE EXCEPTION'inbound message immutable';END$$;
CREATE OR REPLACE FUNCTION audit_immutable_guard()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF TG_OP='DELETE'AND current_setting('salesflow.retention_mode',true)='on'AND current_setting('salesflow.minimization_account',true)=OLD.account_ref THEN RETURN OLD;END IF;RAISE EXCEPTION'append-only';END$$;
CREATE OR REPLACE FUNCTION intent_evidence_guard()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF TG_OP='DELETE'THEN RAISE EXCEPTION'intent evidence immutable';END IF;IF(NEW.account_ref,NEW.id,NEW.contact_id,NEW.conversation_id,NEW.source_id,NEW.kind,NEW.expected_version,NEW.policy_version,NEW.knowledge_version)IS NOT DISTINCT FROM(OLD.account_ref,OLD.id,OLD.contact_id,OLD.conversation_id,OLD.source_id,OLD.kind,OLD.expected_version,OLD.policy_version,OLD.knowledge_version)AND((NEW.body,NEW.provenance)IS NOT DISTINCT FROM(OLD.body,OLD.provenance)OR(current_setting('salesflow.deletion_mode',true)='on'AND NEW.body='[deleted]'AND NEW.provenance='{}'))THEN RETURN NEW;END IF;RAISE EXCEPTION'intent evidence immutable';END$$;
UPDATE conversations c SET last_seq=GREATEST(c.last_seq,x.last_seq)FROM(SELECT account_ref,conversation_id,max(seq)last_seq FROM inbound_messages GROUP BY account_ref,conversation_id)x WHERE(c.account_ref,c.id)=(x.account_ref,x.conversation_id)AND c.last_seq<x.last_seq;
DROP TRIGGER IF EXISTS audit_immutable ON audit_events;CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION audit_immutable_guard();
DROP TRIGGER IF EXISTS transitions_immutable ON intent_transitions;CREATE TRIGGER transitions_immutable BEFORE UPDATE OR DELETE ON intent_transitions FOR EACH ROW EXECUTE FUNCTION immutable();
DROP TRIGGER IF EXISTS provider_calls_immutable ON provider_calls;CREATE TRIGGER provider_calls_immutable BEFORE UPDATE OR DELETE ON provider_calls FOR EACH ROW EXECUTE FUNCTION provider_call_immutable_guard();
DROP TRIGGER IF EXISTS provider_call_events_immutable ON provider_call_events;CREATE TRIGGER provider_call_events_immutable BEFORE UPDATE OR DELETE ON provider_call_events FOR EACH ROW EXECUTE FUNCTION immutable();
DROP TRIGGER IF EXISTS provider_immutable ON provider_events;CREATE TRIGGER provider_immutable BEFORE UPDATE OR DELETE ON provider_events FOR EACH ROW EXECUTE FUNCTION provider_immutable_guard();
DROP TRIGGER IF EXISTS contact_identifier_immutable ON contact_identifiers;CREATE TRIGGER contact_identifier_immutable BEFORE UPDATE OR DELETE ON contact_identifiers FOR EACH ROW EXECUTE FUNCTION contact_identifier_immutable_guard();
DROP TRIGGER IF EXISTS releases_immutable ON releases;CREATE TRIGGER releases_immutable BEFORE UPDATE OR DELETE ON releases FOR EACH ROW EXECUTE FUNCTION immutable();
DROP TRIGGER IF EXISTS config_immutable ON config_docs;CREATE TRIGGER config_immutable BEFORE UPDATE OR DELETE ON config_docs FOR EACH ROW EXECUTE FUNCTION config_immutable_guard();
DROP TRIGGER IF EXISTS inbound_message_sequence ON inbound_messages;CREATE TRIGGER inbound_message_sequence BEFORE INSERT ON inbound_messages FOR EACH ROW EXECUTE FUNCTION assign_inbound_message_sequence();
DROP TRIGGER IF EXISTS inbound_message_order_immutable ON inbound_messages;CREATE TRIGGER inbound_message_order_immutable BEFORE UPDATE OR DELETE ON inbound_messages FOR EACH ROW EXECUTE FUNCTION inbound_message_order_guard();
DROP TRIGGER IF EXISTS intent_evidence_immutable ON intents;CREATE TRIGGER intent_evidence_immutable BEFORE UPDATE OR DELETE ON intents FOR EACH ROW EXECUTE FUNCTION intent_evidence_guard();

CREATE OR REPLACE FUNCTION actor_for(t text,want text DEFAULT NULL)RETURNS TABLE(role text,account_ref text,actor text)LANGUAGE sql STABLE SECURITY DEFINER SET search_path=salesflow,public AS $$SELECT x.role,x.account_ref,x.actor FROM auth_tokens x LEFT JOIN accounts a ON a.id=x.account_ref WHERE x.hash=encode(digest(t,'sha256'),'hex')AND x.revoked_at IS NULL AND x.expires_at>now()AND(want IS NULL OR x.role=want)AND(x.account_ref IS NULL OR a.enabled)$$;
CREATE OR REPLACE FUNCTION actor_for_account_management(t text,acct text)RETURNS TABLE(role text,account_ref text,actor text)LANGUAGE sql STABLE SECURITY DEFINER SET search_path=salesflow,public AS $$SELECT x.role,x.account_ref,x.actor FROM auth_tokens x WHERE x.hash=encode(digest(t,'sha256'),'hex')AND x.revoked_at IS NULL AND x.expires_at>now()AND x.role='operator'AND x.account_ref IS NOT NULL AND(acct IS NULL OR x.account_ref=acct)$$;
CREATE OR REPLACE FUNCTION bootstrap(t text,r text,a text,acct text DEFAULT NULL)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$BEGIN IF session_user<>'salesflow_owner'AND session_user<>'postgres'THEN RAISE EXCEPTION'owner only';END IF;INSERT INTO auth_tokens(hash,role,account_ref,actor)VALUES(encode(digest(t,'sha256'),'hex'),r,acct,a)ON CONFLICT(hash)DO UPDATE SET expires_at=EXCLUDED.expires_at WHERE auth_tokens.revoked_at IS NULL AND(auth_tokens.role,auth_tokens.account_ref,auth_tokens.actor)IS NOT DISTINCT FROM(EXCLUDED.role,EXCLUDED.account_ref,EXCLUDED.actor);END$$;
CREATE OR REPLACE FUNCTION exact_integer(v jsonb)RETURNS bool LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$SELECT jsonb_typeof(v)='number'AND v::text~'^-?(0|[1-9][0-9]*)$'$$;
CREATE OR REPLACE FUNCTION validate_config(k text,b jsonb)RETURNS bool LANGUAGE plpgsql IMMUTABLE AS $$BEGIN
 IF octet_length(b::text)>262144 OR octet_length(COALESCE(b->>'accountRef',''))>256 OR octet_length(COALESCE(b->>'kind',''))>256 OR octet_length(COALESCE(b->>'version',''))>256 OR EXISTS(SELECT 1 FROM jsonb_path_query(b,'strict $.** ? (@.type() == "string")')x WHERE octet_length(x#>>'{}')>1024)OR EXISTS(SELECT 1 FROM jsonb_path_query(b,'strict $.** ? (@.type() == "array")')x WHERE jsonb_array_length(x)>100)THEN RETURN false;END IF;
 IF jsonb_typeof(b)IS DISTINCT FROM'object'OR jsonb_typeof(b->'accountRef')IS DISTINCT FROM'string'OR COALESCE(btrim(b->>'accountRef'),'')=''OR jsonb_typeof(b->'kind')IS DISTINCT FROM'string'OR COALESCE(btrim(b->>'kind'),'')=''OR b->>'kind'IS DISTINCT FROM k OR jsonb_typeof(b->'version')IS DISTINCT FROM'string'OR COALESCE(btrim(b->>'version'),'')=''THEN RETURN false;END IF;
 IF k='product_knowledge'AND b-ARRAY['accountRef','kind','version','sources']<>'{}'OR k='sales_policy'AND b-ARRAY['accountRef','kind','version','campaignEnabled','allowedOffers','allowedClaims','minimumConfidence','frequencyCap24h','quietHoursUtc']<>'{}'OR k='qualification'AND b-ARRAY['accountRef','kind','version','minimumScore','handoffScore']<>'{}'OR k='consent_templates'AND b-ARRAY['accountRef','kind','version','serviceWindowHours','optOutSignals','humanSignals','templates']<>'{}'OR k='handoff'AND b-ARRAY['accountRef','kind','version','queue','deadlineSeconds','maxAttempts','backoffSeconds','claimSeconds']<>'{}'OR k='retry'AND b-ARRAY['accountRef','kind','version','maxAttempts','backoffSeconds','leaseSeconds','turnClaimSeconds','followupClaimSeconds']<>'{}'OR k='model'AND b-ARRAY['accountRef','kind','version','selection','productionEnabled','allowedClaims']<>'{}'OR k='retention'AND b-ARRAY['accountRef','kind','version','auditDays','messageDays']<>'{}'OR k='release_set'AND b-ARRAY['accountRef','kind','version','reviewedManifestHash','policyVersion','knowledgeVersion','manifestVersion']<>'{}'THEN RETURN false;END IF;
 IF k='retry'AND NOT(b?&ARRAY['maxAttempts','backoffSeconds','leaseSeconds','turnClaimSeconds','followupClaimSeconds'])OR k='sales_policy'AND NOT(b?&ARRAY['allowedOffers','allowedClaims','minimumConfidence','frequencyCap24h','campaignEnabled','quietHoursUtc'])OR k='consent_templates'AND NOT(b?&ARRAY['optOutSignals','humanSignals','templates','serviceWindowHours'])OR k='handoff'AND NOT(b?&ARRAY['queue','deadlineSeconds','maxAttempts','backoffSeconds','claimSeconds'])OR k='model'AND NOT(b?&ARRAY['selection','productionEnabled','allowedClaims'])OR k='product_knowledge'AND NOT(b?'sources')OR k='qualification'AND NOT(b?&ARRAY['minimumScore','handoffScore'])OR k='retention'AND NOT(b?&ARRAY['auditDays','messageDays'])OR k='release_set'AND NOT(b?&ARRAY['reviewedManifestHash','policyVersion','knowledgeVersion','manifestVersion'])THEN RETURN false;END IF;
 IF k='retry'THEN RETURN exact_integer(b->'maxAttempts')AND(b->>'maxAttempts')::int BETWEEN 1 AND 10 AND exact_integer(b->'backoffSeconds')AND(b->>'backoffSeconds')::int BETWEEN 1 AND 3600 AND exact_integer(b->'leaseSeconds')AND(b->>'leaseSeconds')::int BETWEEN 1 AND 300 AND exact_integer(b->'turnClaimSeconds')AND(b->>'turnClaimSeconds')::int BETWEEN 1 AND 300 AND exact_integer(b->'followupClaimSeconds')AND(b->>'followupClaimSeconds')::int BETWEEN 1 AND 300;
 ELSIF k='sales_policy'THEN RETURN jsonb_typeof(b->'allowedOffers')='array'AND jsonb_array_length(b->'allowedOffers')>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'allowedOffers')x WHERE jsonb_typeof(x)<>'string'OR btrim(x#>>'{}')='')AND(SELECT count(*)=count(DISTINCT lower(btrim(value)))FROM jsonb_array_elements_text(b->'allowedOffers'))AND jsonb_typeof(b->'allowedClaims')='array'AND jsonb_array_length(b->'allowedClaims')>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'allowedClaims')x WHERE jsonb_typeof(x)<>'string'OR btrim(x#>>'{}')='')AND(SELECT count(*)=count(DISTINCT lower(btrim(value)))FROM jsonb_array_elements_text(b->'allowedClaims'))AND jsonb_typeof(b->'minimumConfidence')='number'AND(b->>'minimumConfidence')::numeric BETWEEN 0 AND 1 AND exact_integer(b->'frequencyCap24h')AND(b->>'frequencyCap24h')::int BETWEEN 1 AND 100 AND jsonb_typeof(b->'campaignEnabled')='boolean'AND jsonb_typeof(b->'quietHoursUtc')='object'AND(b->'quietHoursUtc')?&ARRAY['start','end']AND(b->'quietHoursUtc')-ARRAY['start','end']='{}'AND exact_integer(b#>'{quietHoursUtc,start}')AND(b#>>'{quietHoursUtc,start}')::int BETWEEN 0 AND 23 AND exact_integer(b#>'{quietHoursUtc,end}')AND(b#>>'{quietHoursUtc,end}')::int BETWEEN 0 AND 23;
 ELSIF k='consent_templates'THEN RETURN exact_integer(b->'serviceWindowHours')AND(b->>'serviceWindowHours')::int BETWEEN 1 AND 168 AND jsonb_typeof(b->'optOutSignals')='array'AND jsonb_array_length(b->'optOutSignals')>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'optOutSignals')x WHERE jsonb_typeof(x)<>'string'OR btrim(x#>>'{}')=''OR x#>>'{}' IS DISTINCT FROM lower(btrim(regexp_replace(normalize_inbound_body(x#>>'{}'),'[[:space:]]+',' ','g'))))AND(SELECT count(*)=count(DISTINCT lower(btrim(value)))FROM jsonb_array_elements_text(b->'optOutSignals'))AND jsonb_typeof(b->'humanSignals')='array'AND jsonb_array_length(b->'humanSignals')>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'humanSignals')x WHERE jsonb_typeof(x)<>'string'OR btrim(x#>>'{}')=''OR x#>>'{}' IS DISTINCT FROM lower(btrim(regexp_replace(normalize_inbound_body(x#>>'{}'),'[[:space:]]+',' ','g'))))AND(SELECT count(*)=count(DISTINCT lower(btrim(value)))FROM jsonb_array_elements_text(b->'humanSignals'))AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(b->'optOutSignals')x JOIN jsonb_array_elements_text(b->'humanSignals')y ON lower(btrim(x))=lower(btrim(y)))AND jsonb_typeof(b->'templates')='array'AND(SELECT count(*)=count(DISTINCT lower(btrim(x->>'key')))FROM jsonb_array_elements(b->'templates')x)AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'templates')x WHERE jsonb_typeof(x)<>'object'OR NOT(x?&ARRAY['key','approved','windowHours','providerTemplateId','category','language'])OR x-ARRAY['key','approved','windowHours','providerTemplateId','category','language']<>'{}'OR jsonb_typeof(x->'key')<>'string'OR COALESCE(btrim(x->>'key'),'')=''OR jsonb_typeof(x->'approved')<>'boolean'OR NOT exact_integer(x->'windowHours')OR(x->>'windowHours')::int NOT BETWEEN 1 AND 168 OR jsonb_typeof(x->'providerTemplateId')<>'string'OR COALESCE(btrim(x->>'providerTemplateId'),'')=''OR jsonb_typeof(x->'category')<>'string'OR x->>'category'NOT IN('marketing','utility','authentication')OR jsonb_typeof(x->'language')<>'string'OR COALESCE(btrim(x->>'language'),'')='');
 ELSIF k='handoff'THEN RETURN jsonb_typeof(b->'queue')='string'AND COALESCE(btrim(b->>'queue'),'')<>''AND exact_integer(b->'deadlineSeconds')AND(b->>'deadlineSeconds')::int BETWEEN 1 AND 86400 AND exact_integer(b->'maxAttempts')AND(b->>'maxAttempts')::int BETWEEN 1 AND 10 AND exact_integer(b->'backoffSeconds')AND(b->>'backoffSeconds')::int BETWEEN 1 AND 3600 AND exact_integer(b->'claimSeconds')AND(b->>'claimSeconds')::int BETWEEN 1 AND 300;
 ELSIF k='model'THEN RETURN b->>'selection'='synthetic-local'AND NOT(b->>'productionEnabled')::bool AND jsonb_typeof(b->'allowedClaims')='array'AND jsonb_array_length(b->'allowedClaims')>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'allowedClaims')x WHERE jsonb_typeof(x)<>'string'OR btrim(x#>>'{}')='')AND(SELECT count(*)=count(DISTINCT lower(btrim(value)))FROM jsonb_array_elements_text(b->'allowedClaims'));
 ELSIF k='product_knowledge'THEN RETURN jsonb_typeof(b->'sources')='array'AND jsonb_array_length(b->'sources')>0 AND(SELECT count(*)=count(DISTINCT lower(btrim(x->>'id')))FROM jsonb_array_elements(b->'sources')x)AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'sources')x WHERE jsonb_typeof(x)<>'object'OR NOT(x?&ARRAY['id','claims'])OR x-ARRAY['id','claims']<>'{}'OR jsonb_typeof(x->'id')<>'string'OR COALESCE(btrim(x->>'id'),'')=''OR jsonb_typeof(x->'claims')<>'array'OR jsonb_array_length(x->'claims')=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(x->'claims')c WHERE jsonb_typeof(c)<>'string'OR btrim(c#>>'{}')='')OR(SELECT count(*)<>count(DISTINCT lower(btrim(value)))FROM jsonb_array_elements_text(x->'claims')));
 ELSIF k='qualification'THEN RETURN exact_integer(b->'minimumScore')AND(b->>'minimumScore')::int BETWEEN 0 AND 100 AND exact_integer(b->'handoffScore')AND(b->>'handoffScore')::int BETWEEN 0 AND 100 AND(b->>'minimumScore')::int<=(b->>'handoffScore')::int;
 ELSIF k='retention'THEN RETURN exact_integer(b->'auditDays')AND(b->>'auditDays')::int BETWEEN 1 AND 3650 AND exact_integer(b->'messageDays')AND(b->>'messageDays')::int BETWEEN 1 AND 3650 AND(b->>'messageDays')::int<=(b->>'auditDays')::int;
 ELSIF k='release_set'THEN RETURN COALESCE(b->>'reviewedManifestHash','')~'^[0-9a-f]{64}$'AND COALESCE(btrim(b->>'policyVersion'),'')<>''AND COALESCE(btrim(b->>'knowledgeVersion'),'')<>''AND COALESCE(btrim(b->>'manifestVersion'),'')<>'';
 END IF;RETURN false;EXCEPTION WHEN OTHERS THEN RETURN false;END$$;
DROP FUNCTION IF EXISTS publish_config(text,jsonb);
CREATE OR REPLACE FUNCTION save_config(t text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$
DECLARE a record;acct text:=b->>'accountRef';k text:=b->>'kind';v text:=b->>'version';prior jsonb;
BEGIN
 SELECT*INTO a FROM actor_for(t,'operator');IF NOT FOUND OR a.account_ref IS DISTINCT FROM acct THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;
 IF validate_config(k,b)IS DISTINCT FROM true THEN RETURN'{"ok":false,"reason":"invalid_config"}';END IF;
 PERFORM set_config('lock_timeout','1s',true);BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(acct||':'||k,0));EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"reason":"busy"}';END;
 SELECT body INTO prior FROM config_docs WHERE(account_ref,kind,version)=(acct,k,v)FOR UPDATE;
 IF FOUND THEN IF prior IS DISTINCT FROM b THEN RETURN'{"ok":false,"reason":"version_immutable"}';END IF;RETURN'{"ok":true,"created":false}';END IF;
 INSERT INTO config_docs(account_ref,kind,version,body)VALUES(acct,k,v,b);
 INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'config_saved',k,a.actor,jsonb_build_object('kind',k,'version',v));
 RETURN'{"ok":true,"created":true}';
END$$;
CREATE OR REPLACE FUNCTION activate_config(t text,acct text,k text,v text,expected text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$
DECLARE a record;current_version text;target jsonb;
BEGIN
 SELECT*INTO a FROM actor_for(t,'operator');IF NOT FOUND OR a.account_ref IS DISTINCT FROM acct THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;
 IF COALESCE(btrim(k),'')=''OR COALESCE(btrim(v),'')=''THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;
 PERFORM set_config('lock_timeout','1s',true);BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(acct||':'||k,0));EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"reason":"busy"}';END;
 SELECT body INTO target FROM config_docs WHERE(account_ref,kind,version)=(acct,k,v);IF NOT FOUND THEN RETURN'{"ok":false,"reason":"not_found"}';END IF;
 IF validate_config(k,target)IS DISTINCT FROM true THEN RETURN'{"ok":false,"reason":"incompatible_config"}';END IF;
 IF EXISTS(SELECT 1 FROM config_docs WHERE(account_ref,kind,version,active)=(acct,k,v,true))THEN RETURN jsonb_build_object('ok',true,'activated',false,'version',v);END IF;
 SELECT version INTO current_version FROM config_docs WHERE account_ref=acct AND kind=k AND active;IF current_version IS DISTINCT FROM expected THEN RETURN jsonb_build_object('ok',false,'reason','stale_active_version','activeVersion',current_version);END IF;
 PERFORM set_config('salesflow.config_activation','on',true);UPDATE config_docs SET active=false WHERE account_ref=acct AND kind=k AND active;UPDATE config_docs SET active=true WHERE(account_ref,kind,version)=(acct,k,v);PERFORM set_config('salesflow.config_activation','off',true);
 INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'config_activated',k,a.actor,jsonb_build_object('kind',k,'targetVersion',v,'previousVersion',current_version));
 RETURN jsonb_build_object('ok',true,'activated',true,'version',v,'previousVersion',current_version);
END$$;
CREATE OR REPLACE FUNCTION set_control(t text,acct text,k text,v jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;BEGIN SELECT*INTO a FROM actor_for(t,'operator');IF NOT FOUND OR a.account_ref<>acct OR k NOT IN('stop')THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;IF jsonb_typeof(v->'enabled')<>'boolean'THEN RETURN'{"ok":false,"reason":"invalid_control"}';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(acct||':control:'||k,0));INSERT INTO controls VALUES(acct,k,v)ON CONFLICT(account_ref,key)DO UPDATE SET value=EXCLUDED.value;INSERT INTO audit_events(account_ref,event,reason,actor)VALUES(acct,'control_changed',k,a.actor);RETURN'{"ok":true}';END$$;
CREATE OR REPLACE FUNCTION set_consent(t text,acct text,c uuid,s text,e text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;prior timestamptz;at_time timestamptz:=clock_timestamp();BEGIN SELECT*INTO a FROM actor_for(t,'runtime');IF NOT FOUND OR a.account_ref<>acct THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;IF s NOT IN('granted','revoked')OR COALESCE(trim(e),'')=''OR NOT EXISTS(SELECT 1 FROM contacts WHERE(account_ref,id)=(acct,c))THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;PERFORM set_config('lock_timeout','5s',true);BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(acct||':consent:'||c::text,0));EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"reason":"busy"}';END;SELECT max(occurred_at)INTO prior FROM consent_events WHERE(account_ref,contact_id)=(acct,c);at_time:=GREATEST(at_time,COALESCE(prior+interval'1 microsecond',at_time));INSERT INTO consent_events VALUES(acct,c,s,e,at_time);RETURN jsonb_build_object('ok',true,'occurred_at',at_time);END$$;

CREATE OR REPLACE FUNCTION replace_contact_identifier(t text,acct text,c uuid,ch text,pr text,old_ref text,new_ref text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;old_id uuid;new_id uuid;old_hash text;new_hash text;old_lock bigint;new_lock bigint;conv uuid;lock_deadline timestamptz;BEGIN SELECT*INTO a FROM actor_for(t,'operator');IF NOT FOUND OR a.account_ref IS DISTINCT FROM acct THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;IF c IS NULL OR COALESCE(btrim(ch),'')=''OR COALESCE(btrim(pr),'')=''OR COALESCE(btrim(old_ref),'')=''OR COALESCE(btrim(new_ref),'')=''OR old_ref=new_ref THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;old_hash:=encode(digest(old_ref,'sha256'),'hex');new_hash:=encode(digest(new_ref,'sha256'),'hex');old_lock:=hashtextextended(acct||':'||ch||':'||pr||':'||old_hash,0);new_lock:=hashtextextended(acct||':'||ch||':'||pr||':'||new_hash,0);PERFORM set_config('lock_timeout','1s',true);lock_deadline:=clock_timestamp()+interval'1s';BEGIN FOR conv IN SELECT id FROM conversations WHERE(account_ref,contact_id)=(acct,c)ORDER BY id LOOP PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(acct,conv);END LOOP;PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(acct,c);PERFORM followup_set_lock_deadline(lock_deadline);PERFORM pg_advisory_xact_lock(LEAST(old_lock,new_lock));IF old_lock<>new_lock THEN PERFORM followup_set_lock_deadline(lock_deadline);PERFORM pg_advisory_xact_lock(GREATEST(old_lock,new_lock));END IF;PERFORM 1 FROM contacts WHERE(account_ref,id)=(acct,c)FOR UPDATE;IF NOT FOUND THEN RETURN'{"ok":false,"reason":"not_found"}';END IF;SELECT id INTO old_id FROM contact_identifiers WHERE account_ref=acct AND contact_id=c AND channel=ch AND provider=pr AND external_ref_hash=old_hash AND active FOR UPDATE;EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"reason":"busy"}';END;IF old_id IS NULL THEN IF EXISTS(SELECT 1 FROM contact_identifiers o JOIN contact_identifiers n ON n.account_ref=o.account_ref AND n.contact_id=o.contact_id AND n.channel=o.channel AND n.provider=o.provider WHERE o.account_ref=acct AND o.contact_id=c AND o.channel=ch AND o.provider=pr AND o.external_ref_hash=old_hash AND NOT o.active AND n.external_ref_hash=new_hash AND n.active)THEN RETURN jsonb_build_object('ok',true,'created',false,'contact_id',c);END IF;RETURN'{"ok":false,"reason":"not_found"}';END IF;IF EXISTS(SELECT 1 FROM contact_identifiers WHERE account_ref=acct AND channel=ch AND provider=pr AND external_ref_hash=new_hash)THEN RETURN'{"ok":false,"reason":"identifier_conflict"}';END IF;UPDATE contact_identifiers SET active=false,retired_at=clock_timestamp()WHERE(account_ref,id)=(acct,old_id);INSERT INTO contact_identifiers(account_ref,contact_id,channel,provider,external_ref,external_ref_hash)VALUES(acct,c,ch,pr,new_ref,new_hash)RETURNING id INTO new_id;INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'contact_identifier_replaced',ch,a.actor,jsonb_build_object('contact_id',c,'retired_identifier_id',old_id,'active_identifier_id',new_id,'provider',pr));RETURN jsonb_build_object('ok',true,'created',true,'contact_id',c,'retired_identifier_id',old_id,'active_identifier_id',new_id);EXCEPTION WHEN unique_violation THEN RETURN'{"ok":false,"reason":"identifier_conflict"}';END$$;

CREATE OR REPLACE FUNCTION audit_inbound_rejection(acct text,who text,why text,inbound uuid DEFAULT NULL)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$BEGIN INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,CASE WHEN why='idempotency_conflict'THEN'ingress_conflict'ELSE'ingress_rejected'END,why,who,CASE WHEN inbound IS NULL THEN'{}'::jsonb ELSE jsonb_build_object('inbound_id',inbound)END);END$$;

CREATE OR REPLACE FUNCTION save_handoff_summary(acct text,work uuid,policy_version text,offer text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$BEGIN
 INSERT INTO handoff_summaries(account_ref,handoff_id,conversation_id,source_id,reason,urgency,deadline,known_lead_details,remaining_unknowns,relevant_offer,sales_policy_version,conversation_url)
 SELECT h.account_ref,h.id,h.conversation_id,h.source_id,h.reason,'respond_by_deadline',h.deadline,jsonb_build_array(jsonb_build_object('messageId',m.id,'sequence',m.seq,'excerpt',left(m.body,128))),'["structured_lead_profile"]',COALESCE(NULLIF(offer,''),'none'),COALESCE(NULLIF(policy_version,''),'unknown'),'/webhook/salesflow/handoff?view=conversation&conversation_id='||h.conversation_id
 FROM handoffs h JOIN inbound_messages m ON(m.account_ref,m.id)=(h.account_ref,h.source_id)WHERE(h.account_ref,h.id)=(acct,work)ON CONFLICT(account_ref,handoff_id)DO NOTHING;
END$$;

CREATE OR REPLACE FUNCTION handoff_summary_json(acct text,work uuid)RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=salesflow,public AS $$
SELECT jsonb_build_object('handoffId',s.handoff_id,'conversationId',s.conversation_id,'reason',s.reason,'urgency',s.urgency,'deadline',s.deadline,'knownLeadDetails',s.known_lead_details,'remainingUnknowns',s.remaining_unknowns,'relevantOffer',s.relevant_offer,'salesPolicyVersion',s.sales_policy_version,'conversationUrl',s.conversation_url)FROM handoff_summaries s WHERE(s.account_ref,s.handoff_id)=(acct,work)
$$;

CREATE OR REPLACE FUNCTION read_conversation_history(t text,acct text,conv uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;v conversations;messages jsonb;BEGIN
 SELECT*INTO a FROM actor_for(t,'operator');IF NOT FOUND OR a.account_ref IS DISTINCT FROM acct THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;
 IF COALESCE(btrim(acct),'')=''OR conv IS NULL THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;
 SELECT*INTO v FROM conversations WHERE(account_ref,id)=(acct,conv);IF NOT FOUND OR v.lifecycle='deleted'THEN RETURN'{"ok":false,"reason":"not_found"}';END IF;
 SELECT COALESCE(jsonb_agg(x.message ORDER BY x.source_seq NULLS LAST,x.direction_order,x.at NULLS LAST,x.message_id),'[]')INTO messages FROM(
 SELECT m.seq source_seq,0 direction_order,m.received_at at,m.id message_id,jsonb_build_object('messageId',m.id,'sequence',m.seq,'direction','inbound','receivedAt',m.received_at,'body',m.body)message FROM inbound_messages m WHERE(m.account_ref,m.conversation_id)=(acct,conv)
 UNION ALL
 SELECT m.seq,1,COALESCE(i.provider_time,it.at),i.id,jsonb_build_object('messageId',i.id,'sequence',COALESCE(to_jsonb(m.seq),'"unknown"'::jsonb),'direction','outbound','receivedAt',COALESCE(to_jsonb(COALESCE(i.provider_time,it.at)),'"unknown"'::jsonb),'body',i.body)
 FROM intents i
 LEFT JOIN followups f ON i.kind='followup'AND(f.account_ref,f.id,f.conversation_id)=(i.account_ref,i.source_id,i.conversation_id)
 LEFT JOIN intents parent ON(parent.account_ref,parent.id,parent.conversation_id)=(f.account_ref,f.source_intent_id,f.conversation_id)AND parent.kind='reply'
 LEFT JOIN inbound_messages m ON(m.account_ref,m.id,m.conversation_id)=(i.account_ref,CASE WHEN i.kind='reply'THEN i.source_id WHEN i.kind='followup'THEN parent.source_id END,i.conversation_id)
 LEFT JOIN LATERAL(SELECT min(ti.at)at FROM intent_transitions ti WHERE(ti.account_ref,ti.intent_id,ti.to_state)=(i.account_ref,i.id,'sent'))it ON true
 WHERE(i.account_ref,i.conversation_id,i.state)=(acct,conv,'sent'))x;
 RETURN jsonb_build_object('ok',true,'account_ref',acct,'conversation_id',conv,'messages',messages);
END$$;

DROP FUNCTION IF EXISTS read_conversation_history_request(text,text,text);
CREATE OR REPLACE FUNCTION read_conversation_history_request(t text,conv_text text)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;BEGIN
 IF conv_text IS NULL OR conv_text!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;
 SELECT*INTO a FROM actor_for(t,'operator');IF NOT FOUND THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;RETURN read_conversation_history(t,a.account_ref,conv_text::uuid);
EXCEPTION WHEN invalid_text_representation THEN RETURN'{"ok":false,"reason":"invalid_input"}';END$$;

CREATE OR REPLACE FUNCTION ingest_core(t text,p jsonb,staging bool)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;c contacts;ci contact_identifiers;v conversations;m inbound_messages;e inbound_messages;received timestamptz;h text;identity_hash text;conversation_hint uuid;contact_hint uuid;cfg jsonb;norm text;raw text;clean text;handoff_id uuid;policy_version text;BEGIN
 SELECT*INTO a FROM actor_for(t,'runtime');IF NOT FOUND THEN RETURN'{"ok":false,"accepted":false,"reason":"unauthorized"}';END IF;
 IF jsonb_typeof(p)IS DISTINCT FROM'object'OR jsonb_typeof(p->'account_ref')IS DISTINCT FROM'string'OR jsonb_typeof(p->'provider_id')IS DISTINCT FROM'string'OR jsonb_typeof(p->'contact_ref')IS DISTINCT FROM'string'OR jsonb_typeof(p->'body')IS DISTINCT FROM'string'OR(p?'received_at'AND jsonb_typeof(p->'received_at')IS DISTINCT FROM'string')THEN PERFORM audit_inbound_rejection(a.account_ref,a.actor,'invalid');RETURN'{"ok":false,"accepted":false,"reason":"invalid"}';END IF;
 IF p->>'account_ref'IS DISTINCT FROM a.account_ref THEN PERFORM audit_inbound_rejection(a.account_ref,a.actor,'wrong_account');RETURN'{"ok":false,"accepted":false,"reason":"wrong_account"}';END IF;
 raw:=p->>'body';IF(p->>'provider_id')~'^[[:space:]]*$'OR(p->>'contact_ref')~'^[[:space:]]*$'OR octet_length(p->>'provider_id')>1024 OR octet_length(raw)>8192 THEN PERFORM audit_inbound_rejection(a.account_ref,a.actor,'invalid');RETURN'{"ok":false,"accepted":false,"reason":"invalid"}';END IF;clean:=normalize_inbound_body(raw);
 BEGIN received:=COALESCE((p->>'received_at')::timestamptz,now());EXCEPTION WHEN OTHERS THEN PERFORM audit_inbound_rejection(a.account_ref,a.actor,'invalid');RETURN'{"ok":false,"accepted":false,"reason":"invalid"}';END;IF clean=''OR received>now()+interval'5 min'THEN PERFORM audit_inbound_rejection(a.account_ref,a.actor,'invalid');RETURN'{"ok":false,"accepted":false,"reason":"invalid"}';END IF;
 h:=encode(digest(raw,'sha256'),'hex');SELECT*INTO e FROM inbound_messages WHERE account_ref=a.account_ref AND provider_id=p->>'provider_id';IF FOUND THEN IF e.body IS DISTINCT FROM raw OR e.contact_ref IS DISTINCT FROM p->>'contact_ref'THEN PERFORM audit_inbound_rejection(a.account_ref,a.actor,'idempotency_conflict',e.id);RETURN'{"ok":false,"accepted":false,"reason":"idempotency_conflict"}';END IF;RETURN jsonb_build_object('ok',true,'accepted',true,'eventId',e.id::text,'created',false,'terminal','duplicate','account_ref',a.account_ref,'conversation_id',e.conversation_id);END IF;
 IF NOT staging THEN norm:=lower(btrim(regexp_replace(clean,'[[:space:]]+',' ','g')));END IF;
 identity_hash:=encode(digest(p->>'contact_ref','sha256'),'hex');SELECT cv.id,cid.contact_id INTO conversation_hint,contact_hint FROM contact_identifiers cid JOIN conversations cv ON(cv.account_ref,cv.contact_id)=(cid.account_ref,cid.contact_id)WHERE cid.account_ref=a.account_ref AND cid.channel='whatsapp'AND cid.provider='meta'AND cid.external_ref_hash=identity_hash AND cid.active;IF conversation_hint IS NOT NULL THEN PERFORM followup_lock_conversation(a.account_ref,conversation_hint);PERFORM followup_lock_authorities(a.account_ref,contact_hint);END IF;PERFORM pg_advisory_xact_lock(hashtextextended(a.account_ref||':whatsapp:meta:'||identity_hash,0));SELECT cid.*INTO ci FROM contact_identifiers cid JOIN contacts ct ON(ct.account_ref,ct.id)=(cid.account_ref,cid.contact_id)WHERE cid.account_ref=a.account_ref AND cid.channel='whatsapp'AND cid.provider='meta'AND cid.external_ref_hash=identity_hash AND cid.active FOR SHARE OF cid,ct;IF FOUND THEN IF conversation_hint IS NULL THEN PERFORM audit_inbound_rejection(a.account_ref,a.actor,'busy');RETURN'{"ok":false,"accepted":false,"reason":"busy"}';END IF;SELECT*INTO c FROM contacts WHERE(account_ref,id)=(a.account_ref,ci.contact_id);ELSIF EXISTS(SELECT 1 FROM contact_identifiers WHERE account_ref=a.account_ref AND channel='whatsapp'AND provider='meta'AND external_ref_hash=identity_hash)THEN PERFORM audit_inbound_rejection(a.account_ref,a.actor,'identifier_retired');RETURN'{"ok":false,"accepted":false,"reason":"identifier_retired"}';ELSE INSERT INTO contacts(account_ref)VALUES(a.account_ref)RETURNING*INTO c;INSERT INTO contact_identifiers(account_ref,contact_id,channel,provider,external_ref,external_ref_hash)VALUES(a.account_ref,c.id,'whatsapp','meta',p->>'contact_ref',identity_hash)RETURNING*INTO ci;END IF;
 INSERT INTO conversations(account_ref,contact_id)VALUES(a.account_ref,c.id)ON CONFLICT(account_ref,contact_id)DO UPDATE SET version=conversations.version RETURNING*INTO v;IF v.lifecycle='deleted'THEN PERFORM audit_inbound_rejection(a.account_ref,a.actor,'identifier_retired');RETURN'{"ok":false,"accepted":false,"reason":"identifier_retired"}';END IF;IF NOT staging THEN PERFORM followup_lock_conversation(a.account_ref,v.id);PERFORM followup_lock_authorities(a.account_ref,c.id);SELECT body INTO cfg FROM config_docs WHERE account_ref=a.account_ref AND kind='consent_templates'AND active;IF cfg IS NULL THEN PERFORM audit_inbound_rejection(a.account_ref,a.actor,'missing_config');RETURN'{"ok":false,"accepted":false,"reason":"missing_config"}';END IF;IF NOT(cfg->'optOutSignals'?norm)AND cfg->'humanSignals'?norm AND NOT EXISTS(SELECT 1 FROM config_docs WHERE account_ref=a.account_ref AND kind='handoff'AND active)THEN PERFORM audit_inbound_rejection(a.account_ref,a.actor,'missing_handoff_config');RETURN'{"ok":false,"accepted":false,"reason":"missing_handoff_config"}';END IF;END IF;
 IF staging THEN PERFORM set_config('salesflow.staging_ingest','on',true);END IF; INSERT INTO inbound_messages(account_ref,conversation_id,provider_id,contact_ref,body,processing_body,body_hash,received_at,seq)VALUES(a.account_ref,v.id,p->>'provider_id',p->>'contact_ref',raw,clean,h,received,0)RETURNING*INTO m;INSERT INTO turns(account_ref,inbound_id,conversation_id,state)VALUES(a.account_ref,m.id,v.id,CASE WHEN staging THEN'completed'ELSE'pending'END);IF staging THEN PERFORM set_config('salesflow.staging_ingest','off',true);END IF;
 IF NOT staging THEN IF cfg->'optOutSignals'?norm THEN UPDATE conversations SET lifecycle='opted_out'WHERE(account_ref,id)=(a.account_ref,v.id);UPDATE intents SET state='suppressed',reason='opted_out',lease=NULL,lease_until=NULL WHERE account_ref=a.account_ref AND conversation_id=v.id AND state IN('pending','leased');UPDATE followups SET state='suppressed',reason='opted_out',claim=NULL,claim_until=NULL WHERE account_ref=a.account_ref AND conversation_id=v.id AND state IN('due','claimed','retry');UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL,next_attempt=NULL WHERE account_ref=a.account_ref AND conversation_id=v.id AND state IN('pending','claimed');ELSIF cfg->'humanSignals'?norm AND v.lifecycle='active'AND v.owner='ai'THEN UPDATE conversations SET owner='human'WHERE(account_ref,id)=(a.account_ref,v.id);PERFORM suppress_automation_for_human(a.account_ref,v.id);SELECT body INTO cfg FROM config_docs WHERE account_ref=a.account_ref AND kind='handoff'AND active;SELECT version INTO policy_version FROM config_docs WHERE account_ref=a.account_ref AND kind='sales_policy'AND active;INSERT INTO handoffs(account_ref,contact_id,conversation_id,source_id,reason,queue,deadline,evidence)VALUES(a.account_ref,c.id,v.id,m.id,'human_requested',cfg->>'queue',now()+make_interval(secs=>(cfg->>'deadlineSeconds')::int),jsonb_build_object('inbound_id',m.id))RETURNING id INTO handoff_id;PERFORM save_handoff_summary(a.account_ref,handoff_id,policy_version,'none');END IF;END IF;
 INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(a.account_ref,'ingress','accepted',a.actor,jsonb_build_object('inbound_id',m.id));RETURN jsonb_build_object('ok',true,'accepted',true,'eventId',m.id::text,'created',true,'account_ref',a.account_ref,'conversation_id',v.id,'contact_id',c.id,'inbound_id',m.id);
 EXCEPTION WHEN unique_violation THEN SELECT*INTO e FROM inbound_messages WHERE account_ref=a.account_ref AND provider_id=p->>'provider_id';IF FOUND AND e.body IS NOT DISTINCT FROM raw AND e.contact_ref IS NOT DISTINCT FROM p->>'contact_ref'THEN RETURN jsonb_build_object('ok',true,'accepted',true,'eventId',e.id::text,'created',false,'terminal','concurrent_replay','account_ref',a.account_ref,'conversation_id',e.conversation_id);END IF;PERFORM audit_inbound_rejection(a.account_ref,a.actor,'idempotency_conflict',e.id);RETURN'{"ok":false,"accepted":false,"reason":"idempotency_conflict"}';END$$;

CREATE OR REPLACE FUNCTION ingest(t text,p jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$BEGIN PERFORM set_config('lock_timeout','5s',true);PERFORM set_config('salesflow.staging_ingest','off',true);BEGIN RETURN ingest_core(t,p,false);EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"accepted":false,"reason":"busy"}'::jsonb;END;END$$;

CREATE OR REPLACE FUNCTION record_ingress_rejection(t text,r text,correlation text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;BEGIN SELECT*INTO a FROM actor_for(t,'runtime');IF NOT FOUND THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;IF COALESCE(r,'')NOT IN('invalid_signature','wrong_identity','malformed_payload','oversized_payload','unsupported_event','idempotency_conflict','identifier_retired')OR COALESCE(correlation,'')!~'^[0-9a-f]{64}$'THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(a.account_ref||':meta-rejection:'||r||':'||correlation,0));IF NOT EXISTS(SELECT 1 FROM audit_events WHERE account_ref=a.account_ref AND event='ingress_rejected'AND reason=r AND details=jsonb_build_object('correlation',correlation))THEN INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(a.account_ref,'ingress_rejected',r,a.actor,jsonb_build_object('correlation',correlation));RETURN jsonb_build_object('ok',true,'created',true,'reason',r);END IF;RETURN jsonb_build_object('ok',true,'created',false,'reason',r);END$$;

-- ponytail: one staging-envelope lock per account; split by Conversation only after measured pilot contention.
CREATE OR REPLACE FUNCTION ingest_meta(t text,p jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;x jsonb;r jsonb;created int:=0;reason text;correlation text;fallback text:=encode(digest('salesflow:meta-rejection:v1:malformed_payload:invalid','sha256'),'hex');BEGIN SELECT*INTO a FROM actor_for(t,'runtime');IF NOT FOUND THEN RETURN'{"ok":false,"accepted":false,"reason":"unauthorized"}';END IF;IF jsonb_typeof(p)IS DISTINCT FROM'object'THEN PERFORM record_ingress_rejection(t,'malformed_payload',fallback);RETURN'{"ok":false,"accepted":false,"reason":"invalid_input"}';END IF;correlation:=p->>'correlation';IF p->>'account_ref'IS DISTINCT FROM a.account_ref THEN PERFORM record_ingress_rejection(t,'wrong_identity',CASE WHEN COALESCE(correlation,'')~'^[0-9a-f]{64}$'THEN correlation ELSE fallback END);RETURN'{"ok":false,"accepted":false,"reason":"invalid_input"}';END IF;IF jsonb_typeof(p->'messages')IS DISTINCT FROM'array'OR COALESCE(correlation,'')!~'^[0-9a-f]{64}$'THEN PERFORM record_ingress_rejection(t,'malformed_payload',fallback);RETURN'{"ok":false,"accepted":false,"reason":"invalid_input"}';END IF;IF jsonb_array_length(p->'messages')=0 THEN PERFORM record_ingress_rejection(t,'malformed_payload',correlation);RETURN'{"ok":false,"accepted":false,"reason":"invalid_input"}';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'messages')m WHERE jsonb_typeof(m)IS DISTINCT FROM'object'OR m->>'account_ref'IS DISTINCT FROM a.account_ref OR COALESCE(m->>'provider_id','')=''OR COALESCE(m->>'contact_ref','')=''OR COALESCE(m->>'body','')=''OR octet_length(m->>'body')>8192 OR COALESCE(m->>'received_at','')='')THEN PERFORM record_ingress_rejection(t,'malformed_payload',correlation);RETURN'{"ok":false,"accepted":false,"reason":"invalid_input"}';END IF;PERFORM set_config('lock_timeout','5s',true);BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(a.account_ref||':meta-envelope',0));FOR x IN SELECT value FROM jsonb_array_elements(p->'messages')LOOP r:=ingest_core(t,x,true);IF NOT COALESCE((r->>'accepted')::bool,false)THEN reason:=COALESCE(r->>'reason','invalid_input');RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE=reason;END IF;IF COALESCE((r->>'created')::bool,false)THEN created:=created+1;END IF;END LOOP;EXCEPTION WHEN SQLSTATE'P0001'THEN reason:=SQLERRM;WHEN lock_not_available THEN reason:='busy';END;IF reason='busy'THEN RETURN'{"ok":false,"accepted":false,"reason":"busy"}';ELSIF reason IS NOT NULL THEN PERFORM record_ingress_rejection(t,CASE WHEN reason IN('idempotency_conflict','identifier_retired')THEN reason ELSE'malformed_payload'END,correlation);RETURN jsonb_build_object('ok',false,'accepted',false,'reason',reason);END IF;RETURN jsonb_build_object('ok',true,'accepted',true,'created',created,'messages',jsonb_array_length(p->'messages'));END$$;


CREATE OR REPLACE FUNCTION authorization_reason(acct text,i intents,n timestamptz DEFAULT now())RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE v conversations;cons text;pol jsonb;retry jsonb;ct jsonb;stop bool;stop_control jsonb;hr int;freq int;last_inbound timestamptz;template_hours int;BEGIN IF NOT EXISTS(SELECT 1 FROM accounts WHERE id=acct AND enabled)THEN RETURN'account_disabled';END IF;SELECT value INTO stop_control FROM controls WHERE account_ref=acct AND key='stop';IF NOT FOUND THEN RETURN'missing_control';ELSIF jsonb_typeof(stop_control->'enabled')IS DISTINCT FROM'boolean'THEN RETURN'invalid_control';END IF;stop:=(stop_control->>'enabled')::bool;SELECT body INTO retry FROM config_docs WHERE account_ref=acct AND kind='retry'AND active;IF retry IS NULL THEN RETURN'missing_retry';END IF;SELECT*INTO v FROM conversations WHERE(account_ref,id)=(acct,i.conversation_id);SELECT status INTO cons FROM consent_events WHERE(account_ref,contact_id)=(acct,i.contact_id)ORDER BY occurred_at DESC LIMIT 1;IF stop THEN RETURN'global_stop';ELSIF v.lifecycle<>'active'THEN RETURN v.lifecycle;ELSIF cons IS DISTINCT FROM'granted'THEN RETURN'consent_missing';ELSIF v.owner<>'ai'THEN RETURN'human_owned';ELSIF v.version<>i.expected_version THEN RETURN'stale_version';END IF;SELECT body INTO pol FROM config_docs WHERE account_ref=acct AND kind='sales_policy'AND active AND version=i.policy_version;IF pol IS NULL THEN RETURN'policy_invalid';END IF;IF NOT EXISTS(SELECT 1 FROM config_docs WHERE account_ref=acct AND kind='product_knowledge'AND active AND version=i.knowledge_version)THEN RETURN'knowledge_invalid';END IF;IF NOT(pol->'allowedOffers'?COALESCE(i.provenance->>'offerId',''))THEN RETURN'offer_invalid';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(i.provenance->'claims')c WHERE NOT(pol->'allowedClaims'?c))THEN RETURN'claim_invalid';END IF;IF COALESCE((i.provenance->>'confidence')::numeric,0)<(pol->>'minimumConfidence')::numeric THEN RETURN'confidence_low';END IF;SELECT body INTO ct FROM config_docs WHERE account_ref=acct AND kind='consent_templates'AND active;IF ct IS NULL THEN RETURN'missing_consent_config';END IF;IF i.template_key IS NOT NULL THEN SELECT(x->>'windowHours')::int INTO template_hours FROM jsonb_array_elements(ct->'templates')x WHERE x->>'key'=i.template_key AND COALESCE((x->>'approved')::bool,false);IF template_hours IS NULL THEN RETURN'template_invalid';END IF;END IF;SELECT max(received_at)INTO last_inbound FROM inbound_messages WHERE account_ref=acct AND conversation_id=i.conversation_id;IF i.template_key IS NULL AND(last_inbound IS NULL OR last_inbound<n-make_interval(hours=>(ct->>'serviceWindowHours')::int))THEN RETURN'service_window_closed';ELSIF i.template_key IS NOT NULL AND(last_inbound IS NULL OR last_inbound<n-make_interval(hours=>template_hours))THEN RETURN'template_window_closed';END IF;hr:=extract(hour from n AT TIME ZONE'UTC');IF(pol#>>'{quietHoursUtc,start}')::int<>(pol#>>'{quietHoursUtc,end}')::int AND(((pol#>>'{quietHoursUtc,start}')::int<(pol#>>'{quietHoursUtc,end}')::int AND hr>=(pol#>>'{quietHoursUtc,start}')::int AND hr<(pol#>>'{quietHoursUtc,end}')::int)OR((pol#>>'{quietHoursUtc,start}')::int>(pol#>>'{quietHoursUtc,end}')::int AND(hr>=(pol#>>'{quietHoursUtc,start}')::int OR hr<(pol#>>'{quietHoursUtc,end}')::int)))THEN RETURN'quiet_hours';END IF;SELECT count(*)INTO freq FROM provider_calls pc JOIN intents sent_i ON(sent_i.account_ref,sent_i.id)=(pc.account_ref,pc.intent_id)WHERE pc.account_ref=acct AND sent_i.contact_id=i.contact_id AND pc.started_at>n-interval'24h';IF freq>=(pol->>'frequencyCap24h')::int THEN RETURN'frequency_cap';END IF;IF NOT v.campaign OR NOT(pol->>'campaignEnabled')::bool THEN RETURN'campaign_disabled';END IF;RETURN'authorized';END$$;

CREATE OR REPLACE FUNCTION claim_dispatch(t text,acct text,work uuid,n timestamptz DEFAULT now())RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;i intents;r text;cfg jsonb;old text;BEGIN SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR a.role NOT IN('runtime','scheduler')OR(a.role='runtime'AND acct IS NOT NULL AND a.account_ref<>acct)THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;IF acct IS NULL THEN acct:=a.account_ref;END IF;IF acct IS NULL THEN RETURN'{"ok":false,"terminal":"denied","reason":"missing_account"}';END IF;SELECT*INTO i FROM intents WHERE(account_ref,id)=(acct,work)FOR UPDATE;IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;IF i.state='sent'THEN RETURN jsonb_build_object('ok',false,'terminal','sent','reason','already_sent','account_ref',acct,'work_id',i.id,'provider_id',i.provider_id);ELSIF i.state='failed'THEN RETURN jsonb_build_object('ok',false,'terminal','failed','reason','failed','account_ref',acct,'work_id',i.id,'provider_id',i.provider_id);ELSIF i.state='reconciliation_required'THEN RETURN jsonb_build_object('ok',false,'terminal','reconciliation_required','reason','reconciliation_required','account_ref',acct,'work_id',i.id,'provider_id',i.provider_id);ELSIF i.state='provider_call_started'AND i.lease_until>n THEN RETURN jsonb_build_object('ok',false,'terminal','already_started','reason','call_in_flight','account_ref',acct,'work_id',i.id,'provider_id',i.provider_id);ELSIF(i.state='provider_call_started'AND i.lease_until<=n)OR(i.state='leased'AND i.lease_until<=n AND EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(acct,i.id)))THEN old:=i.state;UPDATE intents SET state='reconciliation_required',reason='provider_call_outcome_unknown',lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,i.id);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,i.id,old,'reconciliation_required','provider_call_outcome_unknown');INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason)VALUES(acct,i.id,'reconciliation-required','reconciliation_required','provider_call_outcome_unknown')ON CONFLICT DO NOTHING;RETURN jsonb_build_object('ok',false,'terminal','reconciliation_required','reason','reconciliation_required','account_ref',acct,'work_id',i.id,'provider_id',i.provider_id);ELSIF i.state='leased'AND i.lease_until>n THEN RETURN'{"ok":false,"terminal":"denied","reason":"already_leased"}';ELSIF i.state NOT IN('pending','leased')THEN RETURN jsonb_build_object('ok',false,'terminal','denied','reason','not_pending','state',i.state);END IF;SELECT body INTO cfg FROM config_docs WHERE account_ref=acct AND kind='retry'AND active;IF cfg IS NULL THEN r:='missing_retry';ELSIF i.attempts>=(cfg->>'maxAttempts')::int THEN old:=i.state;UPDATE intents SET state='reconciliation_required',reason='retry_exhausted',lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,i.id);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,i.id,old,'reconciliation_required','retry_exhausted');RETURN'{"ok":false,"terminal":"reconciliation_required","reason":"retry_exhausted"}'::jsonb;ELSIF i.next_attempt>n THEN RETURN'{"ok":false,"terminal":"denied","reason":"backoff"}';ELSE r:=authorization_reason(acct,i,n);END IF;IF r<>'authorized'THEN old:=i.state;UPDATE intents SET state='suppressed',reason=r,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,i.id);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,i.id,old,'suppressed',r);INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'authorization_denied',r,a.actor,jsonb_build_object('intent_id',i.id));RETURN jsonb_build_object('ok',false,'terminal','denied','reason',r);END IF;old:=i.state;UPDATE intents SET state='leased',reason=NULL,lease=gen_random_uuid(),lease_until=n+make_interval(secs=>(cfg->>'leaseSeconds')::int),attempts=attempts+1,next_attempt=NULL WHERE(account_ref,id)=(acct,i.id)RETURNING*INTO i;INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,i.id,old,'leased','authorized');RETURN jsonb_build_object('ok',true,'terminal','claimed','account_ref',acct,'work_id',i.id,'lease',i.lease);END$$;
CREATE OR REPLACE FUNCTION recheck_dispatch(t text,acct text,work uuid,l uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;i intents;r text;BEGIN SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR(a.role='runtime'AND a.account_ref<>acct)OR a.role NOT IN('runtime','scheduler')THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;SELECT*INTO i FROM intents WHERE(account_ref,id)=(acct,work)FOR UPDATE;IF NOT FOUND OR i.state<>'leased'OR i.lease IS DISTINCT FROM l OR l IS NULL OR i.lease_until<=now()THEN RETURN'{"ok":false,"terminal":"denied","reason":"lease_mismatch"}';END IF;r:=authorization_reason(acct,i);IF r<>'authorized'THEN UPDATE intents SET state='suppressed',reason=r,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,work,'leased','suppressed',r);INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'authorization_denied',r,a.actor,jsonb_build_object('intent_id',work,'phase','recheck'));RETURN jsonb_build_object('ok',false,'terminal','denied','reason',r);END IF;RETURN'{"ok":true,"terminal":"authorized"}';END$$;
CREATE OR REPLACE FUNCTION begin_provider_call(t text,acct text,work uuid,l uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;i intents;pc provider_calls;r text;pid text;release_id text;authority_lock bigint;BEGIN SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR(a.role='runtime'AND a.account_ref<>acct)OR a.role NOT IN('runtime','scheduler')THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;SELECT*INTO i FROM intents WHERE(account_ref,id)=(acct,work);IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;PERFORM 1 FROM contacts WHERE(account_ref,id)=(acct,i.contact_id)FOR SHARE;PERFORM 1 FROM conversations WHERE(account_ref,id)=(acct,i.conversation_id)FOR SHARE;PERFORM 1 FROM accounts WHERE id=acct FOR SHARE;PERFORM pg_advisory_xact_lock(hashtextextended(acct||':consent:'||i.contact_id::text,0));FOR authority_lock IN SELECT DISTINCT x.lock_id FROM unnest(ARRAY[hashtextextended(acct||':consent_templates',0),hashtextextended(acct||':product_knowledge',0),hashtextextended(acct||':retry',0),hashtextextended(acct||':sales_policy',0)])AS x(lock_id)ORDER BY x.lock_id LOOP PERFORM pg_advisory_xact_lock(authority_lock);END LOOP;PERFORM pg_advisory_xact_lock(hashtextextended(acct||':control:stop',0));SELECT*INTO i FROM intents WHERE(account_ref,id)=(acct,work)FOR UPDATE;SELECT*INTO pc FROM provider_calls WHERE(account_ref,intent_id)=(acct,work);IF FOUND THEN RETURN jsonb_build_object('ok',true,'terminal','already_started','provider_id',pc.provider_id,'correlation_id',pc.correlation_id);END IF;IF i.state<>'leased'OR i.lease<>l OR i.lease_until<=now()THEN RETURN'{"ok":false,"terminal":"denied","reason":"lease_mismatch"}';END IF;r:=authorization_reason(acct,i);IF r<>'authorized'THEN UPDATE intents SET state='suppressed',reason=r,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,work,'leased','suppressed',r);INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'authorization_denied',r,a.actor,jsonb_build_object('intent_id',work,'phase','provider_call_start'));RETURN jsonb_build_object('ok',false,'terminal','denied','reason',r);END IF;pid:='synthetic-'||work::text;release_id:=COALESCE(i.provenance#>>'{context,releaseSetVersion}','unbound');INSERT INTO provider_calls(account_ref,intent_id,attempt_no,lease,provider_id,release_set_version)VALUES(acct,work,i.attempts,l,pid,release_id)RETURNING*INTO pc;UPDATE intents SET state='provider_call_started',provider_id=pid,reason=NULL WHERE(account_ref,id)=(acct,work);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,work,'leased','provider_call_started','provider_call_started');INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason,details)VALUES(acct,work,'started','started','authorized',jsonb_build_object('attempt',i.attempts,'correlation_id',pc.correlation_id,'release_set_version',release_id));RETURN jsonb_build_object('ok',true,'terminal','started','account_ref',acct,'work_id',work,'lease',l,'provider_id',pid,'correlation_id',pc.correlation_id);END$$;
CREATE OR REPLACE FUNCTION finish_dispatch(t text,acct text,work uuid,l uuid,outcome text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;i intents;pc provider_calls;cfg jsonb;old text;event_id text;event_status text;event_time timestamptz:=now();BEGIN SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR(a.role='runtime'AND a.account_ref<>acct)OR a.role NOT IN('runtime','scheduler')THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;IF outcome NOT IN('success','retryable','ambiguous','failed')THEN RETURN'{"ok":false,"terminal":"denied","reason":"invalid_outcome"}';END IF;SELECT*INTO i FROM intents WHERE(account_ref,id)=(acct,work)FOR UPDATE;IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;SELECT*INTO pc FROM provider_calls WHERE(account_ref,intent_id)=(acct,work);IF outcome='retryable'THEN IF FOUND OR i.state<>'leased'OR i.lease<>l OR i.lease_until<=now()THEN RETURN'{"ok":false,"terminal":"denied","reason":"call_already_started"}';END IF;SELECT body INTO cfg FROM config_docs WHERE account_ref=acct AND kind='retry'AND active;old:=i.state;IF cfg IS NOT NULL AND i.attempts<(cfg->>'maxAttempts')::int THEN UPDATE intents SET state='pending',reason='pre_call_retryable',next_attempt=now()+make_interval(secs=>(cfg->>'backoffSeconds')::int),lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work)RETURNING*INTO i;INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,work,old,'pending','pre_call_retryable');RETURN jsonb_build_object('ok',true,'terminal','pending','next_attempt',i.next_attempt);END IF;UPDATE intents SET state='reconciliation_required',reason='retry_exhausted',lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,work,old,'reconciliation_required','retry_exhausted');RETURN'{"ok":true,"terminal":"reconciliation_required","reason":"retry_exhausted"}'::jsonb;END IF;IF NOT FOUND OR pc.lease<>l THEN RETURN'{"ok":false,"terminal":"denied","reason":"call_mismatch"}';END IF;IF i.state='sent'THEN RETURN jsonb_build_object('ok',true,'terminal','sent','provider_id',pc.provider_id);ELSIF i.state='failed'THEN RETURN jsonb_build_object('ok',true,'terminal','failed','provider_id',pc.provider_id);ELSIF i.state NOT IN('provider_call_started','reconciliation_required')THEN RETURN jsonb_build_object('ok',false,'terminal','denied','reason','invalid_state','state',i.state);END IF;old:=i.state;IF outcome='success'THEN UPDATE intents SET state='sent',reason=NULL,provider_id=pc.provider_id,provider_status='accepted',provider_time=event_time,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work)RETURNING*INTO i;event_id:='dispatch-accepted-'||work::text;event_status:='accepted';INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason)VALUES(acct,work,'outcome-success','accepted','provider_accepted')ON CONFLICT DO NOTHING;ELSIF outcome='failed'THEN UPDATE intents SET state='failed',reason='provider_call_failed',provider_id=pc.provider_id,provider_status='failed',provider_time=event_time,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work)RETURNING*INTO i;event_id:='dispatch-failed-'||work::text;event_status:='failed';INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason)VALUES(acct,work,'outcome-failed','failed','provider_call_failed')ON CONFLICT DO NOTHING;ELSE UPDATE intents SET state='reconciliation_required',reason='ambiguous',provider_id=pc.provider_id,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work)RETURNING*INTO i;INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason)VALUES(acct,work,'outcome-ambiguous','ambiguous','ambiguous')ON CONFLICT DO NOTHING;END IF;INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,work,old,i.state,CASE outcome WHEN'success'THEN'provider_accepted'WHEN'failed'THEN'provider_call_failed'ELSE'ambiguous'END);IF event_id IS NOT NULL THEN INSERT INTO provider_events(account_ref,event_id,intent_id,provider_id,status,provider_time,payload_hash)VALUES(acct,event_id,work,pc.provider_id,event_status,event_time,encode(digest(jsonb_build_object('event_id',event_id,'provider_id',pc.provider_id,'status',event_status,'provider_time',event_time)::text,'sha256'),'hex'))ON CONFLICT ON CONSTRAINT provider_events_pkey DO NOTHING;END IF;RETURN jsonb_build_object('ok',true,'terminal',i.state,'provider_id',pc.provider_id);END$$;





-- Loop-5 worker/recheck commands keep discovery and final authorization in PostgreSQL.
CREATE OR REPLACE FUNCTION complete_turn(t text,acct text,conv uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$
DECLARE a record;v conversations;m inbound_messages;cons consent_events;business record;hm record;pol jsonb;know jsonb;model jsonb;qual jsonb;handoff jsonb;i intents;retry jsonb;h uuid;contact uuid;qscore int;grounded bool;history_ids uuid[]:='{}';history_seqs bigint[]:='{}';history_payload jsonb:='[]';history_count int:=0;history_bytes int:=0;history_message_limit constant int:=10;history_byte_limit constant int:=32768;policy_lock bigint;knowledge_lock bigint;release_set_lock bigint;context_lock bigint;lock_deadline timestamptz;
BEGIN
 SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR a.role NOT IN('runtime','scheduler')OR(a.role='runtime'AND a.account_ref IS DISTINCT FROM acct)OR(a.role='scheduler'AND a.account_ref IS NOT NULL AND a.account_ref IS DISTINCT FROM acct)OR NOT EXISTS(SELECT 1 FROM accounts WHERE id=acct AND enabled)THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;
 PERFORM set_config('lock_timeout','5s',true);lock_deadline:=clock_timestamp()+interval'5s';BEGIN PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(acct,conv);SELECT contact_id INTO contact FROM conversations WHERE(account_ref,id)=(acct,conv);IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(acct,contact);PERFORM followup_set_lock_deadline(lock_deadline);SELECT*INTO v FROM conversations WHERE(account_ref,id)=(acct,conv)FOR UPDATE;IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"terminal":"denied","reason":"busy"}';END;
 SELECT im.*INTO m FROM inbound_messages im JOIN turns tr ON(tr.account_ref,tr.inbound_id)=(im.account_ref,im.id)WHERE im.account_ref=acct AND im.conversation_id=conv AND(tr.state='pending'OR(tr.state='claimed'AND tr.claim_until<=now()))ORDER BY im.seq LIMIT 1 FOR UPDATE OF tr SKIP LOCKED;IF NOT FOUND THEN RETURN'{"ok":true,"terminal":"nothing"}';END IF;
 SELECT body INTO retry FROM config_docs WHERE account_ref=acct AND kind='retry'AND active;IF retry IS NULL THEN RETURN'{"ok":false,"terminal":"denied","reason":"missing_retry"}';END IF;
 IF(SELECT attempts FROM turns WHERE(account_ref,inbound_id)=(acct,m.id))>=(retry->>'maxAttempts')::int THEN UPDATE turns SET state='suppressed',claim=NULL,claim_until=NULL,result='{"reason":"retry_exhausted"}'WHERE(account_ref,inbound_id)=(acct,m.id);RETURN'{"ok":false,"terminal":"suppressed","reason":"retry_exhausted"}';END IF;
 UPDATE turns SET state='claimed',claim=gen_random_uuid(),claim_until=now()+make_interval(secs=>(retry->>'turnClaimSeconds')::int),attempts=attempts+1 WHERE(account_ref,inbound_id)=(acct,m.id);
 IF v.lifecycle='active'AND v.owner='human'THEN SELECT id INTO h FROM handoffs WHERE(account_ref,source_id)=(acct,m.id)AND state='pending';IF h IS NOT NULL THEN UPDATE turns SET state='completed',claim=NULL,claim_until=NULL,result=jsonb_build_object('handoff_id',h)WHERE(account_ref,inbound_id)=(acct,m.id);RETURN jsonb_build_object('ok',true,'terminal','handoff','reason','human_requested','work_id',h,'work_type','handoff');END IF;END IF;
 IF v.lifecycle<>'active'OR v.owner<>'ai'THEN UPDATE turns SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,inbound_id)=(acct,m.id);RETURN jsonb_build_object('ok',true,'terminal','suppressed','reason',CASE WHEN v.lifecycle<>'active'THEN v.lifecycle ELSE'human_owned'END);END IF;
 PERFORM set_config('lock_timeout','5s',true);BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(acct||':consent:'||v.contact_id::text,0));EXCEPTION WHEN lock_not_available THEN UPDATE turns SET state='pending',claim=NULL,claim_until=NULL,attempts=GREATEST(attempts-1,0),result=jsonb_build_object('reason','busy')WHERE(account_ref,inbound_id)=(acct,m.id);RETURN'{"ok":false,"terminal":"denied","reason":"busy"}';END;SELECT ce.*INTO cons FROM consent_events ce WHERE(ce.account_ref,ce.contact_id)=(acct,v.contact_id)ORDER BY ce.occurred_at DESC LIMIT 1;IF cons.status IS DISTINCT FROM'granted'THEN UPDATE turns SET state='suppressed',claim=NULL,claim_until=NULL,result=jsonb_build_object('reason',CASE WHEN cons.status='revoked'THEN'consent_revoked'ELSE'consent_missing'END)WHERE(account_ref,inbound_id)=(acct,m.id);RETURN jsonb_build_object('ok',false,'terminal','suppressed','reason',CASE WHEN cons.status='revoked'THEN'consent_revoked'ELSE'consent_missing'END);END IF;
 policy_lock:=hashtextextended(acct||':sales_policy',0);knowledge_lock:=hashtextextended(acct||':product_knowledge',0);release_set_lock:=hashtextextended(acct||':release_set',0);BEGIN FOR context_lock IN SELECT DISTINCT x.lock_id FROM unnest(ARRAY[policy_lock,knowledge_lock,release_set_lock])AS x(lock_id)ORDER BY x.lock_id LOOP PERFORM pg_advisory_xact_lock(context_lock);END LOOP;EXCEPTION WHEN lock_not_available THEN UPDATE turns SET state='pending',claim=NULL,claim_until=NULL,attempts=GREATEST(attempts-1,0),result=jsonb_build_object('reason','busy')WHERE(account_ref,inbound_id)=(acct,m.id);RETURN'{"ok":false,"terminal":"denied","reason":"busy"}';END;
 SELECT rs.body release_set_body,p.body policy_body,p.version policy_version,k.body knowledge_body,k.version knowledge_version INTO business FROM config_docs rs CROSS JOIN config_docs p CROSS JOIN config_docs k WHERE rs.account_ref=acct AND rs.kind='release_set'AND rs.active AND p.account_ref=acct AND p.kind='sales_policy'AND p.active AND k.account_ref=acct AND k.kind='product_knowledge'AND k.active FOR SHARE OF rs,p,k;IF NOT FOUND THEN UPDATE turns SET state='suppressed',claim=NULL,claim_until=NULL,result='{"reason":"missing_business_context"}'WHERE(account_ref,inbound_id)=(acct,m.id);RETURN'{"ok":false,"terminal":"suppressed","reason":"missing_business_context"}';ELSIF business.release_set_body->>'policyVersion'IS DISTINCT FROM business.policy_version OR business.release_set_body->>'knowledgeVersion'IS DISTINCT FROM business.knowledge_version THEN UPDATE turns SET state='suppressed',claim=NULL,claim_until=NULL,result='{"reason":"inconsistent_business_context"}'WHERE(account_ref,inbound_id)=(acct,m.id);RETURN'{"ok":false,"terminal":"suppressed","reason":"inconsistent_business_context"}';END IF;pol:=business.policy_body;know:=business.knowledge_body;
 FOR hm IN SELECT im.id,im.seq,im.processing_body,octet_length(im.processing_body)bytes FROM inbound_messages im WHERE im.account_ref=acct AND im.conversation_id=conv AND im.seq<=m.seq ORDER BY im.seq DESC LOOP IF hm.seq=m.seq AND hm.bytes>history_byte_limit THEN UPDATE turns SET state='suppressed',claim=NULL,claim_until=NULL,result='{"reason":"context_too_large"}'WHERE(account_ref,inbound_id)=(acct,m.id);RETURN'{"ok":false,"terminal":"suppressed","reason":"context_too_large"}';ELSIF history_count>=history_message_limit THEN EXIT;ELSIF history_bytes+hm.bytes<=history_byte_limit THEN history_ids:=array_prepend(hm.id,history_ids);history_seqs:=array_prepend(hm.seq,history_seqs);history_payload:=jsonb_build_array(jsonb_build_object('inboundId',hm.id,'seq',hm.seq,'processingBody',hm.processing_body))||history_payload;history_count:=history_count+1;history_bytes:=history_bytes+hm.bytes;END IF;END LOOP;
 SELECT body INTO model FROM config_docs WHERE account_ref=acct AND kind='model'AND active;SELECT body INTO qual FROM config_docs WHERE account_ref=acct AND kind='qualification'AND active;
 -- ponytail: exact synthetic signal only; replace with an approved classifier when the production model is selected.
 qscore:=CASE WHEN lower((history_payload->-1)->>'processingBody')='qualified'THEN COALESCE((qual->>'handoffScore')::int,101)ELSE COALESCE((qual->>'minimumScore')::int,101)END;
 grounded:=pol IS NOT NULL AND know IS NOT NULL AND model IS NOT NULL AND qual IS NOT NULL AND model->>'selection'='synthetic-local'AND model->'allowedClaims'?'service-count'AND pol->'allowedClaims'?'service-count'AND qscore>=(qual->>'minimumScore')::int AND EXISTS(SELECT 1 FROM jsonb_array_elements(know->'sources')s WHERE s->>'id'='source-1'AND s->'claims'?'service-count');
 IF NOT grounded OR qscore>=(qual->>'handoffScore')::int THEN
  SELECT body INTO handoff FROM config_docs WHERE account_ref=acct AND kind='handoff'AND active;IF handoff IS NULL THEN UPDATE turns SET state='pending',claim=NULL,claim_until=NULL WHERE(account_ref,inbound_id)=(acct,m.id);RETURN'{"ok":false,"terminal":"denied","reason":"missing_handoff_config"}';END IF;
  UPDATE conversations SET owner='human'WHERE(account_ref,id)=(acct,conv);PERFORM suppress_automation_for_human(acct,conv);INSERT INTO handoffs(account_ref,contact_id,conversation_id,source_id,reason,queue,deadline,evidence)VALUES(acct,v.contact_id,v.id,m.id,CASE WHEN grounded THEN'qualification_threshold'ELSE'grounding_invalid'END,handoff->>'queue',now()+make_interval(secs=>(handoff->>'deadlineSeconds')::int),jsonb_build_object('inbound_id',m.id,'qualificationVersion',qual->>'version','qualificationScore',qscore,'handoffScore',qual->>'handoffScore'))ON CONFLICT(account_ref,source_id)DO UPDATE SET reason=handoffs.reason RETURNING id INTO h;PERFORM save_handoff_summary(acct,h,business.policy_version,'none');UPDATE turns SET state='completed',claim=NULL,claim_until=NULL,result=jsonb_build_object('handoff_id',h)WHERE(account_ref,inbound_id)=(acct,m.id);RETURN jsonb_build_object('ok',true,'terminal','handoff','reason',CASE WHEN grounded THEN'qualification_threshold'ELSE'grounding_invalid'END,'work_id',h,'work_type','handoff');
 END IF;
 INSERT INTO intents(account_ref,contact_id,conversation_id,source_id,kind,expected_version,policy_version,knowledge_version,body,provenance)VALUES(acct,v.contact_id,v.id,m.id,'reply',v.version,business.policy_version,business.knowledge_version,'Synthetic Plan includes one service.',jsonb_build_object('sourceIds',jsonb_build_array('source-1'),'offerId','offer-1','claims',jsonb_build_array('service-count'),'confidence',1.0,'qualificationVersion',qual->>'version','qualificationScore',qscore,'handoffScore',qual->>'handoffScore','context',jsonb_build_object('consentStatus',cons.status,'consentOccurredAt',cons.occurred_at,'consentEvidenceHash',encode(digest(cons.evidence,'sha256'),'hex'),'releaseSetVersion',business.release_set_body->>'version','policyVersion',business.policy_version,'knowledgeVersion',business.knowledge_version,'inboundMessageIds',to_jsonb(history_ids),'inboundSequences',to_jsonb(history_seqs),'historyMessageLimit',history_message_limit,'historyByteLimit',history_byte_limit,'historySelectedBytes',history_bytes,'sourceInboundId',m.id,'conversationVersion',v.version)))ON CONFLICT(account_ref,conversation_id,source_id,kind)DO UPDATE SET body=intents.body RETURNING*INTO i;
 UPDATE turns SET state='completed',claim=NULL,claim_until=NULL,result=jsonb_build_object('intent_id',i.id)WHERE(account_ref,inbound_id)=(acct,m.id);RETURN jsonb_build_object('ok',true,'terminal','created','work_id',i.id,'work_type','dispatch');
END$$;

DROP FUNCTION IF EXISTS schedule_followups(text,timestamptz);
CREATE FUNCTION schedule_followups(t text,n timestamptz DEFAULT now())RETURNS TABLE(account_ref text,work_id uuid)LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$#variable_conflict use_column
DECLARE a record;f followups;pol config_docs;know config_docs;retry jsonb;i intents;BEGIN SELECT*INTO a FROM actor_for(t,'scheduler');IF NOT FOUND THEN RETURN;END IF;FOR f IN SELECT x.*FROM followups x JOIN accounts ac ON ac.id=x.account_ref AND ac.enabled WHERE(x.state='due'OR(x.state='claimed'AND x.claim_until<=n)OR(x.state='retry'AND x.next_attempt<=n))AND x.due_at<=n ORDER BY x.due_at FOR UPDATE OF x SKIP LOCKED LOOP SELECT body INTO retry FROM config_docs d WHERE d.account_ref=f.account_ref AND kind='retry'AND active;IF retry IS NULL OR f.attempts>=COALESCE((retry->>'maxAttempts')::int,0)THEN UPDATE followups x SET state='suppressed',reason=CASE WHEN retry IS NULL THEN'missing_retry'ELSE'retry_exhausted'END WHERE(x.account_ref,x.id)=(f.account_ref,f.id);CONTINUE;END IF;UPDATE followups x SET state='claimed',claim=gen_random_uuid(),claim_until=n+make_interval(secs=>(retry->>'followupClaimSeconds')::int),attempts=attempts+1 WHERE(x.account_ref,x.id)=(f.account_ref,f.id);SELECT*INTO pol FROM config_docs d WHERE d.account_ref=f.account_ref AND kind='sales_policy'AND active;SELECT*INTO know FROM config_docs d WHERE d.account_ref=f.account_ref AND kind='product_knowledge'AND active;IF pol.version IS NULL OR know.version IS NULL THEN UPDATE followups x SET state='retry',reason='missing_config',next_attempt=n+make_interval(secs=>(retry->>'backoffSeconds')::int),claim=NULL,claim_until=NULL WHERE(x.account_ref,x.id)=(f.account_ref,f.id);CONTINUE;END IF;INSERT INTO intents(account_ref,contact_id,conversation_id,source_id,kind,expected_version,policy_version,knowledge_version,body,template_key,provenance)VALUES(f.account_ref,f.contact_id,f.conversation_id,f.id,'followup',f.expected_version,pol.version,know.version,'Synthetic follow-up.',f.template_key,'{"sourceIds":["source-1"],"offerId":"offer-1","claims":["service-count"],"confidence":1.0}')ON CONFLICT(account_ref,conversation_id,source_id,kind)DO UPDATE SET body=intents.body RETURNING*INTO i;UPDATE followups x SET state='intent_created',intent_id=i.id,claim=NULL,claim_until=NULL WHERE(x.account_ref,x.id)=(f.account_ref,f.id);account_ref:=f.account_ref;work_id:=i.id;RETURN NEXT;END LOOP;END$$;

CREATE OR REPLACE FUNCTION claim_handoff(t text,acct text,work uuid,n timestamptz DEFAULT now())RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;h handoffs;cfg jsonb;v conversations;BEGIN SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR a.role NOT IN('runtime','scheduler')OR(a.role='runtime'AND acct IS NOT NULL AND a.account_ref<>acct)THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;IF acct IS NULL THEN acct:=a.account_ref;END IF;IF NOT EXISTS(SELECT 1 FROM accounts WHERE id=acct AND enabled)THEN RETURN'{"ok":false,"terminal":"denied","reason":"account_disabled"}';END IF;SELECT*INTO h FROM handoffs WHERE(account_ref,id)=(acct,work)FOR UPDATE;IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;SELECT body INTO cfg FROM config_docs WHERE account_ref=acct AND kind='handoff'AND active;SELECT*INTO v FROM conversations WHERE(account_ref,id)=(acct,h.conversation_id);IF v.lifecycle IN('opted_out','deleted')THEN UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);RETURN jsonb_build_object('ok',false,'terminal','denied','reason',v.lifecycle);ELSIF cfg IS NULL THEN RETURN'{"ok":false,"terminal":"denied","reason":"missing_config"}';ELSIF h.state IN('acknowledged','suppressed')THEN RETURN jsonb_build_object('ok',false,'terminal','denied','reason','terminal_state','state',h.state);ELSIF h.state='claimed'AND h.claim_until>n THEN RETURN'{"ok":false,"terminal":"denied","reason":"already_claimed"}';ELSIF h.state NOT IN('pending','claimed')THEN RETURN'{"ok":false,"terminal":"denied","reason":"invalid_state"}';ELSIF h.attempts>=(cfg->>'maxAttempts')::int THEN UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);RETURN'{"ok":false,"terminal":"denied","reason":"retry_exhausted"}';ELSIF h.next_attempt>n THEN RETURN'{"ok":false,"terminal":"denied","reason":"backoff"}';END IF;UPDATE handoffs SET state='claimed',claim=gen_random_uuid(),claim_until=n+make_interval(secs=>(cfg->>'claimSeconds')::int),attempts=attempts+1 WHERE(account_ref,id)=(acct,work)RETURNING*INTO h;RETURN jsonb_build_object('ok',true,'terminal','claimed','account_ref',acct,'work_id',h.id,'claim',h.claim,'queue',h.queue,'deadline',h.deadline);END$$;

CREATE OR REPLACE FUNCTION recheck_handoff(t text,acct text,work uuid,c uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;h handoffs;life text;BEGIN SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR a.role NOT IN('runtime','scheduler')OR(a.role='runtime'AND a.account_ref<>acct)THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;SELECT*INTO h FROM handoffs WHERE(account_ref,id)=(acct,work)FOR UPDATE;IF NOT FOUND OR h.state<>'claimed'OR h.claim<>c OR h.claim_until<=now()THEN RETURN'{"ok":false,"terminal":"denied","reason":"claim_mismatch"}';END IF;SELECT lifecycle INTO life FROM conversations WHERE(account_ref,id)=(acct,h.conversation_id);IF NOT EXISTS(SELECT 1 FROM accounts WHERE id=acct AND enabled)OR life='opted_out'OR life='deleted'OR NOT EXISTS(SELECT 1 FROM config_docs WHERE account_ref=acct AND kind='handoff'AND active)THEN UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);RETURN jsonb_build_object('ok',false,'terminal','denied','reason',CASE WHEN life IN('opted_out','deleted')THEN life WHEN NOT EXISTS(SELECT 1 FROM accounts WHERE id=acct AND enabled)THEN'account_disabled'ELSE'missing_config'END);END IF;RETURN jsonb_build_object('ok',true,'terminal','authorized','account_ref',acct,'work_id',work,'claim',c);END$$;

CREATE OR REPLACE FUNCTION finish_handoff(t text,acct text,work uuid,c uuid,outcome text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;h handoffs;cfg jsonb;life text;BEGIN SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR a.role NOT IN('runtime','scheduler')OR(a.role='runtime'AND a.account_ref<>acct)THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;SELECT*INTO h FROM handoffs WHERE(account_ref,id)=(acct,work)FOR UPDATE;IF NOT FOUND OR h.state<>'claimed'OR h.claim<>c OR h.claim_until<=now()THEN RETURN'{"ok":false,"terminal":"denied","reason":"claim_mismatch"}';END IF;IF outcome NOT IN('success','retryable','failed')THEN RETURN'{"ok":false,"terminal":"denied","reason":"invalid_outcome"}';END IF;SELECT lifecycle INTO life FROM conversations WHERE(account_ref,id)=(acct,h.conversation_id);IF life IN('opted_out','deleted')OR NOT EXISTS(SELECT 1 FROM accounts WHERE id=acct AND enabled)THEN UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);RETURN jsonb_build_object('ok',false,'terminal','denied','reason',CASE WHEN life IN('opted_out','deleted')THEN life ELSE'account_disabled'END);END IF;SELECT body INTO cfg FROM config_docs WHERE account_ref=acct AND kind='handoff'AND active;IF cfg IS NULL THEN UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);RETURN'{"ok":false,"terminal":"denied","reason":"missing_config"}';ELSIF outcome='success'THEN UPDATE handoffs SET state='acknowledged',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);ELSIF outcome='retryable'AND h.attempts<(cfg->>'maxAttempts')::int THEN UPDATE handoffs SET state='pending',next_attempt=now()+make_interval(secs=>(cfg->>'backoffSeconds')::int),claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);ELSE UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);END IF;RETURN(SELECT jsonb_build_object('ok',true,'terminal',state,'next_attempt',next_attempt)FROM handoffs WHERE(account_ref,id)=(acct,work));END$$;


CREATE OR REPLACE FUNCTION schedule_work(t text,n timestamptz DEFAULT now())RETURNS TABLE(account_ref text,work_id uuid,workflow_id text)LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;x record;BEGIN SELECT*INTO a FROM actor_for(t,'scheduler');IF NOT FOUND THEN RETURN;END IF;PERFORM count(*)FROM schedule_followups(t,n);FOR x IN SELECT i.account_ref,i.id,i.state FROM intents i WHERE(i.state='provider_call_started'OR i.state='leased')AND i.lease_until<=n AND EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(i.account_ref,i.id))FOR UPDATE OF i LOOP UPDATE intents i SET state='reconciliation_required',reason='provider_call_outcome_unknown',lease=NULL,lease_until=NULL WHERE(i.account_ref,i.id)=(x.account_ref,x.id);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(x.account_ref,x.id,x.state,'reconciliation_required','provider_call_outcome_unknown');INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason)VALUES(x.account_ref,x.id,'reconciliation-required','reconciliation_required','provider_call_outcome_unknown')ON CONFLICT DO NOTHING;END LOOP;RETURN QUERY SELECT i.account_ref,i.id,'salesflow-wf-03'FROM intents i JOIN accounts ac ON ac.id=i.account_ref AND ac.enabled WHERE(i.state='pending'OR(i.state='leased'AND i.lease_until<=n AND NOT EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(i.account_ref,i.id))))AND(i.next_attempt IS NULL OR i.next_attempt<=n)UNION ALL SELECT h.account_ref,h.id,'salesflow-wf-06'FROM handoffs h JOIN accounts ac ON ac.id=h.account_ref AND ac.enabled WHERE(h.state='pending'OR(h.state='claimed'AND h.claim_until<=n))AND(h.next_attempt IS NULL OR h.next_attempt<=n)ORDER BY 1,2;END$$;

CREATE OR REPLACE FUNCTION callback(t text,p jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$
DECLARE a record;i intents;e provider_events;pt timestamptz;h text;rank_old int;rank_new int;
BEGIN
 SELECT*INTO a FROM actor_for(t,'runtime');IF NOT FOUND OR p->>'account_ref'IS DISTINCT FROM a.account_ref THEN RETURN'{"ok":false,"reason":"wrong_account"}';END IF;
 IF COALESCE(p->>'event_id','')=''OR COALESCE(p->>'provider_id','')=''OR COALESCE(p->>'provider_time','')=''OR COALESCE(p->>'status','')NOT IN('accepted','sent','delivered','read','failed')THEN RETURN'{"ok":false,"reason":"invalid"}';END IF;
 BEGIN pt:=(p->>'provider_time')::timestamptz;EXCEPTION WHEN OTHERS THEN RETURN'{"ok":false,"reason":"invalid"}';END;
 IF pt IS NULL THEN RETURN'{"ok":false,"reason":"invalid"}';ELSIF pt>now()+interval'5 min'THEN RETURN'{"ok":false,"reason":"future"}';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(a.account_ref||':'||(p->>'event_id'),0));SELECT x.*INTO i FROM intents x JOIN conversations v ON(v.account_ref,v.id)=(x.account_ref,x.conversation_id)WHERE(x.account_ref,x.provider_id)=(a.account_ref,p->>'provider_id')AND v.lifecycle<>'deleted'FOR UPDATE OF x;IF NOT FOUND THEN RETURN'{"ok":false,"reason":"provider_mismatch"}';END IF;
 h:=encode(digest(p::text,'sha256'),'hex');SELECT*INTO e FROM provider_events WHERE(account_ref,event_id)=(a.account_ref,p->>'event_id');IF FOUND THEN RETURN CASE WHEN e.payload_hash=h THEN jsonb_build_object('ok',true,'created',false,'status',i.provider_status)ELSE'{"ok":false,"reason":"idempotency_conflict"}'::jsonb END;END IF;
 INSERT INTO provider_events VALUES(a.account_ref,p->>'event_id',i.id,p->>'provider_id',p->>'status',pt,h);rank_old:=array_position(ARRAY['accepted','sent','delivered','read'],i.provider_status);rank_new:=array_position(ARRAY['accepted','sent','delivered','read'],p->>'status');IF NOT(i.state='failed'AND i.reason='provider_call_failed')AND((p->>'status'='failed'AND COALESCE(rank_old,0)<3 AND(i.provider_time IS NULL OR pt>=i.provider_time))OR(p->>'status'<>'failed'AND(i.provider_time IS NULL OR(pt>=i.provider_time AND rank_new>=COALESCE(rank_old,0)))))THEN IF i.state IN('reconciliation_required','provider_call_started')THEN INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(a.account_ref,i.id,i.state,CASE WHEN p->>'status'='failed'THEN'failed'ELSE'sent'END,'provider_callback_reconciled');INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason,details)VALUES(a.account_ref,i.id,'reconciled-'||(p->>'event_id'),'reconciled','provider_callback_reconciled',jsonb_build_object('event_id',p->>'event_id','status',p->>'status'))ON CONFLICT DO NOTHING;END IF;UPDATE intents SET state=CASE WHEN p->>'status'='failed'THEN'failed'ELSE'sent'END,reason=CASE WHEN p->>'status'='failed'THEN'provider_failed'ELSE NULL END,provider_status=p->>'status',provider_time=pt,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(a.account_ref,i.id)RETURNING*INTO i;END IF;
 RETURN jsonb_build_object('ok',true,'created',true,'status',i.provider_status);
END$$;

CREATE OR REPLACE FUNCTION enforce_retention(t text,acct text,n timestamptz DEFAULT now())RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;ret jsonb;message_count int;audit_count int;BEGIN SELECT*INTO a FROM actor_for(t,'operator');IF NOT FOUND OR a.account_ref<>acct THEN RETURN'{"ok":false,"reason":"wrong_account"}';END IF;SELECT body INTO ret FROM config_docs WHERE account_ref=acct AND kind='retention'AND active;IF ret IS NULL THEN RETURN'{"ok":false,"reason":"missing_retention"}';END IF;PERFORM set_config('salesflow.retention_mode','on',true),set_config('salesflow.minimization_account',acct,true);UPDATE inbound_messages SET body='[deleted]',processing_body='[deleted]',body_hash=encode(digest('[deleted]','sha256'),'hex'),contact_ref='[deleted]'WHERE account_ref=acct AND received_at<n-make_interval(days=>(ret->>'messageDays')::int)AND(body<>'[deleted]'OR processing_body<>'[deleted]'OR contact_ref<>'[deleted]');GET DIAGNOSTICS message_count=ROW_COUNT;DELETE FROM audit_events WHERE account_ref=acct AND at<n-make_interval(days=>(ret->>'auditDays')::int);GET DIAGNOSTICS audit_count=ROW_COUNT;PERFORM set_config('salesflow.retention_mode','off',true),set_config('salesflow.minimization_account','',true);INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'retention_enforced',ret->>'version',a.actor,jsonb_build_object('messagePurged',message_count,'auditPurged',audit_count,'messageDays',(ret->>'messageDays')::int,'auditDays',(ret->>'auditDays')::int));RETURN jsonb_build_object('ok',true,'terminal','retention_enforced','account_ref',acct,'retentionVersion',ret->>'version','messageDays',(ret->>'messageDays')::int,'auditDays',(ret->>'auditDays')::int,'messagePurged',message_count,'auditPurged',audit_count);END$$;

CREATE OR REPLACE FUNCTION operations(t text,acct text,p jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$
DECLARE a record;c uuid;r uuid;n int;mh text;ret jsonb;rs jsonb;previous text;result jsonb;lock_deadline timestamptz;conv uuid;retention_at timestamptz;
BEGIN
 IF jsonb_typeof(p)IS DISTINCT FROM'object'OR COALESCE(p->>'action','')=''THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;IF p->>'action'='account_enabled'THEN IF jsonb_typeof(p->'enabled')IS DISTINCT FROM'boolean'THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;SELECT*INTO a FROM actor_for_account_management(t,acct);IF NOT FOUND THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;EXECUTE'SELECT salesflow.set_account_enabled($1,$2,$3)'INTO result USING t,a.account_ref,(p->>'enabled')::boolean;RETURN result;END IF;SELECT*INTO a FROM actor_for(t,'operator');IF NOT FOUND OR(acct IS NOT NULL AND a.account_ref<>acct)THEN RETURN'{"ok":false,"reason":"wrong_account"}';END IF;IF acct IS NULL THEN acct:=a.account_ref;END IF;
 IF p->>'action'='evidence'THEN SELECT body INTO ret FROM config_docs WHERE account_ref=acct AND kind='retention'AND active;IF ret IS NULL THEN RETURN'{"ok":false,"reason":"missing_retention"}';END IF;RETURN jsonb_build_object('ok',true,'terminal','evidence','account_ref',acct,'events',(SELECT count(*)FROM audit_events WHERE account_ref=acct),'retentionVersion',ret->>'version','auditDays',(ret->>'auditDays')::int,'messageDays',(ret->>'messageDays')::int,'activeRelease',(SELECT release_id FROM release_pointers WHERE account_ref=acct),'followups',followup_metrics(acct),'alert',jsonb_build_object('condition',EXISTS(SELECT 1 FROM intents WHERE account_ref=acct AND state='reconciliation_required'),'evidenceLocation','salesflow.intents state=reconciliation_required','owner','operator investigates provider evidence and reconciles the intent'));

 ELSIF p->>'action'='retention'THEN IF p?'at'AND p->'at'<>'null'::jsonb THEN IF jsonb_typeof(p->'at')IS DISTINCT FROM'string'THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;BEGIN retention_at:=(p->>'at')::timestamptz;EXCEPTION WHEN OTHERS THEN RETURN'{"ok":false,"reason":"invalid_input"}';END;ELSE retention_at:=clock_timestamp();END IF;RETURN enforce_retention(t,acct,retention_at);
 ELSIF p->>'action'='config_save'THEN IF jsonb_typeof(p->'document')IS DISTINCT FROM'object'THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;RETURN save_config(t,p->'document');
 ELSIF p->>'action'IN('config_activate','config_rollback')THEN result:=activate_config(t,acct,p->>'kind',p->>'version',p->>'expected_active_version');RETURN result;
 ELSIF p->>'action'='contact_identifier_replace'THEN BEGIN c:=(p->>'contact_id')::uuid;EXCEPTION WHEN OTHERS THEN RETURN'{"ok":false,"reason":"invalid_input"}';END;RETURN replace_contact_identifier(t,acct,c,p->>'channel',p->>'provider',p->>'old_ref',p->>'new_ref');
 ELSIF p->>'action'='delete'THEN
  BEGIN c:=(p->>'contact_id')::uuid;EXCEPTION WHEN OTHERS THEN RETURN'{"ok":false,"reason":"invalid_input"}';END;PERFORM set_config('lock_timeout','5s',true);lock_deadline:=clock_timestamp()+interval'5s';BEGIN FOR conv IN SELECT id FROM conversations WHERE(account_ref,contact_id)=(acct,c)ORDER BY id LOOP PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(acct,conv);END LOOP;PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(acct,c);PERFORM 1 FROM contacts WHERE(account_ref,id)=(acct,c)FOR UPDATE;EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"reason":"busy"}';END;IF NOT FOUND THEN RETURN'{"ok":false,"reason":"not_found"}';END IF;
  INSERT INTO deletion_requests(account_ref,contact_id)VALUES(acct,c)RETURNING id INTO r;INSERT INTO deletion_targets SELECT acct,r,'inbound_message',id::text,'pending'FROM inbound_messages WHERE account_ref=acct AND conversation_id IN(SELECT id FROM conversations WHERE account_ref=acct AND contact_id=c)UNION ALL SELECT acct,r,'intent',id::text,'pending'FROM intents WHERE account_ref=acct AND contact_id=c UNION ALL SELECT acct,r,'followup',id::text,'pending'FROM followups WHERE account_ref=acct AND contact_id=c UNION ALL SELECT acct,r,'handoff',id::text,'pending'FROM handoffs WHERE account_ref=acct AND contact_id=c UNION ALL SELECT acct,r,'consent',occurred_at::text,'pending'FROM consent_events WHERE(account_ref,contact_id)=(acct,c)UNION ALL SELECT acct,r,'contact_identifier',id::text,'pending'FROM contact_identifiers WHERE(account_ref,contact_id)=(acct,c)UNION ALL SELECT acct,r,'contact',c::text,'pending';
  PERFORM set_config('salesflow.deletion_mode','on',true),set_config('salesflow.minimization_account',acct,true);PERFORM cancel_followups_for_conversation(acct,v.id,'deleted',NULL)FROM conversations v WHERE(v.account_ref,v.contact_id)=(acct,c);UPDATE provider_events e SET provider_id='deleted-'||e.intent_id::text WHERE e.account_ref=acct AND e.intent_id IN(SELECT id FROM intents WHERE account_ref=acct AND contact_id=c);UPDATE provider_calls pc SET provider_id='deleted-'||pc.intent_id::text WHERE pc.account_ref=acct AND pc.intent_id IN(SELECT id FROM intents WHERE account_ref=acct AND contact_id=c);UPDATE conversations SET lifecycle='deleted'WHERE(account_ref,contact_id)=(acct,c);UPDATE intents SET state=CASE WHEN EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(intents.account_ref,intents.id))THEN state ELSE'suppressed'END,reason=CASE WHEN EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(intents.account_ref,intents.id))THEN reason ELSE'deleted'END,body='[deleted]',provenance='{}',provider_id=CASE WHEN provider_id IS NULL THEN NULL ELSE'deleted-'||id::text END,lease=CASE WHEN EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(intents.account_ref,intents.id))THEN lease ELSE NULL END,lease_until=CASE WHEN EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(intents.account_ref,intents.id))THEN lease_until ELSE NULL END WHERE account_ref=acct AND contact_id=c;UPDATE handoffs SET state='suppressed',evidence='{}',claim=NULL,claim_until=NULL,next_attempt=NULL WHERE account_ref=acct AND contact_id=c;UPDATE handoff_summaries s SET known_lead_details=(SELECT COALESCE(jsonb_agg(jsonb_set(x,'{excerpt}','"[deleted]"')),'[]')FROM jsonb_array_elements(s.known_lead_details)x)WHERE s.account_ref=acct AND s.conversation_id IN(SELECT id FROM conversations WHERE account_ref=acct AND contact_id=c);UPDATE inbound_messages SET body='[deleted]',processing_body='[deleted]',body_hash=encode(digest('[deleted]','sha256'),'hex'),contact_ref='[deleted]'WHERE account_ref=acct AND conversation_id IN(SELECT id FROM conversations WHERE account_ref=acct AND contact_id=c);UPDATE consent_events SET evidence='[deleted]'WHERE(account_ref,contact_id)=(acct,c);UPDATE contact_identifiers SET external_ref='deleted-'||id::text,active=false,retired_at=COALESCE(retired_at,now())WHERE(account_ref,contact_id)=(acct,c);UPDATE deletion_targets SET state='completed'WHERE(account_ref,request_id)=(acct,r);UPDATE deletion_requests SET state='completed',completed_at=now()WHERE(account_ref,id)=(acct,r);SELECT count(*)INTO n FROM deletion_targets WHERE(account_ref,request_id)=(acct,r);RETURN jsonb_build_object('ok',true,'terminal','deleted','request_id',r,'targets',n,'completed',true);
 ELSIF p->>'action'='release'THEN
  IF COALESCE(p->>'release_id','')=''OR jsonb_typeof(p->'manifest')<>'object'OR NOT(p->'manifest'?&ARRAY['version','policyVersion','knowledgeVersion','images','configFiles','workflowFiles','workflowHashes','inputHashes'])OR COALESCE(p->>'manifest_hash','')!~'^[0-9a-f]{64}$'THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;
  mh:=encode(digest((p->'manifest')::text,'sha256'),'hex');SELECT body INTO rs FROM config_docs WHERE account_ref=acct AND kind='release_set'AND active;IF mh<>p->>'manifest_hash'OR rs IS NULL OR rs->>'reviewedManifestHash'<>mh OR rs->>'manifestVersion'<>p#>>'{manifest,version}'OR rs->>'policyVersion'<>p#>>'{manifest,policyVersion}'OR rs->>'knowledgeVersion'<>p#>>'{manifest,knowledgeVersion}'THEN RETURN'{"ok":false,"reason":"manifest_mismatch"}';END IF;
  PERFORM set_config('lock_timeout','1s',true);BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('release:'||acct,0));EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"reason":"busy"}';END;IF EXISTS(SELECT 1 FROM releases WHERE(account_ref,id)=(acct,p->>'release_id'))THEN RETURN'{"ok":false,"reason":"release_exists"}';END IF;SELECT release_id INTO previous FROM release_pointers WHERE account_ref=acct FOR UPDATE;INSERT INTO releases(account_ref,id,manifest_hash,manifest)VALUES(acct,p->>'release_id',mh,p->'manifest');INSERT INTO release_pointers VALUES(acct,p->>'release_id',mh)ON CONFLICT(account_ref)DO UPDATE SET release_id=EXCLUDED.release_id,manifest_hash=EXCLUDED.manifest_hash;INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'release_activated',p->>'release_id',a.actor,jsonb_build_object('manifest_hash',mh));RETURN jsonb_build_object('ok',true,'terminal','released','previous_release',previous);
 END IF;RETURN'{"ok":false,"reason":"invalid_action"}';
END$$;

-- SP3-T3 automatic follow-ups. This block is intentionally migration-safe so the
-- same contract is installed for both fresh databases and upgraded local stacks.
ALTER TABLE followups ADD COLUMN IF NOT EXISTS source_intent_id uuid;
ALTER TABLE followups ADD COLUMN IF NOT EXISTS action_key text;
ALTER TABLE followups ADD COLUMN IF NOT EXISTS request_hash text;
ALTER TABLE followups ADD COLUMN IF NOT EXISTS generation int;
ALTER TABLE followups ADD COLUMN IF NOT EXISTS source_conversation_version bigint;
ALTER TABLE followups ADD COLUMN IF NOT EXISTS scheduled_from_sent_at timestamptz;
ALTER TABLE followups ADD COLUMN IF NOT EXISTS release_set_version text;
ALTER TABLE followups ADD COLUMN IF NOT EXISTS policy_version text;
ALTER TABLE followups ADD COLUMN IF NOT EXISTS knowledge_version text;
ALTER TABLE followups ADD COLUMN IF NOT EXISTS consent_occurred_at timestamptz;
ALTER TABLE followups ADD COLUMN IF NOT EXISTS consent_evidence_hash text;
ALTER TABLE followups ADD COLUMN IF NOT EXISTS content_ref text;
ALTER TABLE followups ADD COLUMN IF NOT EXISTS correlation_id uuid;
ALTER TABLE followups ADD COLUMN IF NOT EXISTS campaign_identity text;
ALTER TABLE followups ADD COLUMN IF NOT EXISTS campaign_snapshot jsonb;

DO $$BEGIN
 IF EXISTS(SELECT 1 FROM pg_constraint WHERE conname='followups_state_check'AND conrelid='followups'::regclass)THEN ALTER TABLE followups DROP CONSTRAINT followups_state_check;END IF;
 ALTER TABLE followups ADD CONSTRAINT followups_state_check CHECK(state IN('due','claimed','retry','intent_created','call_started','reconciliation_required','sent','delivered','failed','cancelled','superseded','denied','exhausted','suppressed','legacy_unverifiable'));
END$$;
CREATE TABLE IF NOT EXISTS followup_transitions(id bigserial PRIMARY KEY,account_ref text NOT NULL,followup_id uuid NOT NULL,event_key text NOT NULL,from_state text NOT NULL,to_state text NOT NULL,reason text NOT NULL,details jsonb NOT NULL DEFAULT'{}',at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(account_ref,followup_id,event_key),FOREIGN KEY(account_ref,followup_id)REFERENCES followups(account_ref,id));
CREATE TABLE IF NOT EXISTS followup_busy_events(id bigserial PRIMARY KEY,account_ref text NOT NULL,followup_id uuid NOT NULL,busy_kind text NOT NULL CHECK(busy_kind IN('row_busy','authority_busy')),details jsonb NOT NULL DEFAULT'{}',at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(account_ref,followup_id,busy_kind));
CREATE TABLE IF NOT EXISTS scheduler_cursors(name text PRIMARY KEY,last_account_ref text NOT NULL DEFAULT'',last_work_id uuid NOT NULL DEFAULT'00000000-0000-0000-0000-000000000000',last_workflow_id text NOT NULL DEFAULT'',updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
INSERT INTO scheduler_cursors(name)VALUES('followup-due'),('followup-reconciliation'),('all-account-work')ON CONFLICT(name)DO NOTHING;
ALTER TABLE scheduler_cursors ADD COLUMN IF NOT EXISTS last_sort_at timestamptz NOT NULL DEFAULT'-infinity';
ALTER TABLE scheduler_cursors ADD COLUMN IF NOT EXISTS cycle_start_account_ref text NOT NULL DEFAULT'';
ALTER TABLE scheduler_cursors ADD COLUMN IF NOT EXISTS cycle_start_sort_at timestamptz NOT NULL DEFAULT'-infinity';
ALTER TABLE scheduler_cursors ADD COLUMN IF NOT EXISTS cycle_start_work_id uuid NOT NULL DEFAULT'00000000-0000-0000-0000-000000000000';
ALTER TABLE scheduler_cursors ADD COLUMN IF NOT EXISTS cycle_start_workflow_id text NOT NULL DEFAULT'';
ALTER TABLE scheduler_cursors ADD COLUMN IF NOT EXISTS cycle_high_account_ref text NOT NULL DEFAULT'';
ALTER TABLE scheduler_cursors ADD COLUMN IF NOT EXISTS cycle_high_sort_at timestamptz NOT NULL DEFAULT'-infinity';
ALTER TABLE scheduler_cursors ADD COLUMN IF NOT EXISTS cycle_high_work_id uuid NOT NULL DEFAULT'00000000-0000-0000-0000-000000000000';
ALTER TABLE scheduler_cursors ADD COLUMN IF NOT EXISTS cycle_high_workflow_id text NOT NULL DEFAULT'';
ALTER TABLE scheduler_cursors ADD COLUMN IF NOT EXISTS cycle_phase int NOT NULL DEFAULT 0 CHECK(cycle_phase IN(0,1));
CREATE TABLE IF NOT EXISTS reconciliation_busy_events(id bigserial PRIMARY KEY,account_ref text NOT NULL,intent_id uuid NOT NULL,busy_kind text NOT NULL CHECK(busy_kind IN('row_busy','authority_busy')),details jsonb NOT NULL DEFAULT'{}',at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(account_ref,intent_id,busy_kind));
DO $$DECLARE n name;BEGIN SELECT conname INTO n FROM pg_constraint WHERE conrelid='followup_busy_events'::regclass AND confrelid='followups'::regclass AND contype='f'LIMIT 1;IF n IS NOT NULL THEN EXECUTE format('ALTER TABLE followup_busy_events DROP CONSTRAINT %I',n);END IF;END$$;

DROP TRIGGER IF EXISTS followup_evidence_immutable ON followups;
WITH ranked AS(
 SELECT account_ref,id,state,
  CASE WHEN state IN('due','claimed','retry','intent_created')THEN row_number()OVER(PARTITION BY account_ref,conversation_id,(state IN('due','claimed','retry','intent_created'))ORDER BY due_at DESC,id DESC)ELSE 1 END AS conversation_rank,
  CASE WHEN source_intent_id IS NULL THEN 1 ELSE row_number()OVER(PARTITION BY account_ref,source_intent_id ORDER BY due_at DESC,id DESC)END AS source_rank,
  CASE WHEN action_key IS NULL THEN 1 ELSE row_number()OVER(PARTITION BY account_ref,action_key ORDER BY due_at DESC,id DESC)END AS action_rank,
  contact_id,conversation_id,source_intent_id,action_key,request_hash,claim,claim_until,next_attempt,intent_id
 FROM followups
 ), candidates AS(
  SELECT*FROM ranked WHERE (state IN('due','claimed','retry','intent_created')AND(conversation_rank>1 OR source_intent_id IS NULL OR action_key IS NULL OR request_hash IS NULL OR source_rank>1 OR action_rank>1 OR(state='claimed'AND(claim IS NULL OR claim_until IS NULL))OR(state='retry'AND next_attempt IS NULL)OR(state='intent_created'AND(intent_id IS NULL OR(NOT EXISTS(SELECT 1 FROM intents child WHERE(child.account_ref,child.id)=(ranked.account_ref,ranked.intent_id)AND child.contact_id=ranked.contact_id AND child.conversation_id=ranked.conversation_id AND child.source_id=ranked.id AND child.kind='followup'AND child.state IN('pending','leased','provider_call_started')AND(child.state='pending'OR(child.lease IS NOT NULL AND child.lease_until IS NOT NULL)))AND NOT EXISTS(SELECT 1 FROM intents child JOIN provider_calls pc ON(pc.account_ref,pc.intent_id)=(child.account_ref,child.id)WHERE(child.account_ref,child.id)=(ranked.account_ref,ranked.intent_id)AND child.contact_id=ranked.contact_id AND child.conversation_id=ranked.conversation_id AND child.source_id=ranked.id AND child.kind='followup'))))))OR(state IN('call_started','reconciliation_required')AND intent_id IS NULL)OR(state NOT IN('due','claimed','retry','intent_created','call_started','reconciliation_required')AND(source_rank>1 OR action_rank>1))
), evidence AS(
 INSERT INTO followup_transitions(account_ref,followup_id,event_key,from_state,to_state,reason,details)
  SELECT account_ref,id,'migration-legacy-unverifiable',state,CASE WHEN state IN('due','claimed','retry','intent_created','call_started','reconciliation_required')THEN'legacy_unverifiable'ELSE state END,CASE WHEN state IN('due','claimed','retry','intent_created','call_started','reconciliation_required')THEN'legacy_unverifiable'ELSE'legacy_identity_detached'END,jsonb_build_object('duplicateSourceIntent',source_rank>1,'duplicateActionKey',action_rank>1,'activeConversationRank',conversation_rank,'originalSourceIntentId',source_intent_id,'originalActionKey',action_key,'originalRequestHash',request_hash)
 FROM candidates ON CONFLICT(account_ref,followup_id,event_key)DO NOTHING RETURNING followup_id
)
UPDATE followups f SET state=CASE WHEN c.state IN('due','claimed','retry','intent_created','call_started','reconciliation_required')THEN'legacy_unverifiable'ELSE f.state END,reason=CASE WHEN c.state IN('due','claimed','retry','intent_created','call_started','reconciliation_required')THEN'legacy_unverifiable'ELSE f.reason END,claim=NULL,claim_until=NULL,next_attempt=NULL,source_intent_id=CASE WHEN c.source_rank>1 THEN NULL ELSE f.source_intent_id END,action_key=CASE WHEN c.action_rank>1 THEN NULL ELSE f.action_key END FROM candidates c WHERE(f.account_ref,f.id)=(c.account_ref,c.id);
INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason,at) SELECT child.account_ref,child.id,child.state,CASE WHEN EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(child.account_ref,child.id))THEN'reconciliation_required'ELSE'suppressed'END,'legacy_unverifiable',clock_timestamp() FROM intents child WHERE child.kind='followup'AND child.state IN('leased','provider_call_started')AND(child.lease IS NULL OR child.lease_until IS NULL)AND NOT EXISTS(SELECT 1 FROM intent_transitions prior WHERE(prior.account_ref,prior.intent_id)=(child.account_ref,child.id)AND prior.reason='legacy_unverifiable');
INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason,details) SELECT child.account_ref,child.id,'migration-legacy-unverifiable','reconciliation_required','legacy_unverifiable',jsonb_build_object('previousState',child.state) FROM intents child WHERE child.kind='followup'AND child.state IN('leased','provider_call_started')AND(child.lease IS NULL OR child.lease_until IS NULL)AND EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(child.account_ref,child.id))ON CONFLICT(account_ref,intent_id,event_key)DO NOTHING;
UPDATE intents child SET state=CASE WHEN EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(child.account_ref,child.id))THEN'reconciliation_required'ELSE'suppressed'END,reason='legacy_unverifiable',lease=NULL,lease_until=NULL WHERE child.kind='followup'AND child.state IN('leased','provider_call_started')AND(child.lease IS NULL OR child.lease_until IS NULL);
INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason,at) SELECT child.account_ref,child.id,child.state,CASE WHEN EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(child.account_ref,child.id))THEN'reconciliation_required'ELSE'suppressed'END,'followup_parent_missing',clock_timestamp() FROM intents child WHERE child.kind='followup'AND NOT EXISTS(SELECT 1 FROM followups f WHERE(f.account_ref,f.id)=(child.account_ref,child.source_id))AND child.state IN('pending','leased','provider_call_started','reconciliation_required')AND NOT EXISTS(SELECT 1 FROM intent_transitions prior WHERE(prior.account_ref,prior.intent_id)=(child.account_ref,child.id)AND prior.reason='followup_parent_missing');
INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason,details) SELECT child.account_ref,child.id,'migration-followup-parent-missing','reconciliation_required','followup_parent_missing',jsonb_build_object('previousState',child.state,'sourceId',child.source_id) FROM intents child WHERE child.kind='followup'AND NOT EXISTS(SELECT 1 FROM followups f WHERE(f.account_ref,f.id)=(child.account_ref,child.source_id))AND EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(child.account_ref,child.id))ON CONFLICT(account_ref,intent_id,event_key)DO NOTHING;
UPDATE intents child SET state=CASE WHEN EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(child.account_ref,child.id))THEN'reconciliation_required'ELSE'suppressed'END,reason='followup_parent_missing',lease=NULL,lease_until=NULL WHERE child.kind='followup'AND NOT EXISTS(SELECT 1 FROM followups f WHERE(f.account_ref,f.id)=(child.account_ref,child.source_id))AND child.state IN('pending','leased','provider_call_started','reconciliation_required');
DO $$BEGIN
 IF EXISTS(SELECT 1 FROM pg_constraint WHERE conname='intents_active_lease_shape_check'AND conrelid='intents'::regclass)THEN ALTER TABLE intents DROP CONSTRAINT intents_active_lease_shape_check;END IF;
 ALTER TABLE intents ADD CONSTRAINT intents_active_lease_shape_check CHECK(state NOT IN('leased','provider_call_started')OR(lease IS NOT NULL AND lease_until IS NOT NULL));
END$$;
DO $$BEGIN
 IF EXISTS(SELECT 1 FROM pg_constraint WHERE conname='followups_active_state_shape_check'AND conrelid='followups'::regclass)THEN ALTER TABLE followups DROP CONSTRAINT followups_active_state_shape_check;END IF;
 ALTER TABLE followups ADD CONSTRAINT followups_active_state_shape_check CHECK((state<>'claimed'OR(claim IS NOT NULL AND claim_until IS NOT NULL))AND(state<>'retry'OR next_attempt IS NOT NULL)AND(state NOT IN('intent_created','call_started','reconciliation_required')OR intent_id IS NOT NULL));
END$$;
DROP INDEX IF EXISTS followups_source_intent_unique;
DROP INDEX IF EXISTS followups_action_key_unique;
DROP INDEX IF EXISTS followups_one_active_per_conversation;
DROP INDEX IF EXISTS followups_due_scan;
DROP INDEX IF EXISTS intents_reconciliation_scan;
CREATE UNIQUE INDEX followups_source_intent_unique ON followups(account_ref,source_intent_id)WHERE source_intent_id IS NOT NULL;
CREATE UNIQUE INDEX followups_action_key_unique ON followups(account_ref,action_key)WHERE action_key IS NOT NULL;
CREATE UNIQUE INDEX followups_one_active_per_conversation ON followups(account_ref,conversation_id)WHERE state IN('due','claimed','retry','intent_created');
CREATE INDEX followups_due_scan ON followups(due_at,account_ref,id)WHERE state IN('due','claimed','retry');
CREATE INDEX intents_reconciliation_scan ON intents(lease_until,account_ref,id)WHERE state IN('provider_call_started','leased')AND lease_until IS NOT NULL;

ALTER TABLE provider_calls ADD COLUMN IF NOT EXISTS callback_alias text;
DROP TRIGGER IF EXISTS provider_calls_immutable ON provider_calls;
UPDATE provider_calls SET callback_alias=encode(digest(account_ref||':'||provider_id,'sha256'),'hex')WHERE callback_alias IS NULL AND provider_id NOT LIKE'deleted-%';
INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason,at) SELECT i.account_ref,i.id,i.state,'reconciliation_required','legacy_callback_alias_missing',clock_timestamp() FROM intents i JOIN provider_calls pc ON(pc.account_ref,pc.intent_id)=(i.account_ref,i.id)WHERE pc.callback_alias IS NULL AND pc.provider_id LIKE'deleted-%'AND i.state IN('leased','provider_call_started')AND NOT EXISTS(SELECT 1 FROM intent_transitions prior WHERE(prior.account_ref,prior.intent_id)=(i.account_ref,i.id)AND prior.reason='legacy_callback_alias_missing');
INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason) SELECT i.account_ref,i.id,'legacy-callback-alias-missing','reconciliation_required','legacy_callback_alias_missing'FROM intents i JOIN provider_calls pc ON(pc.account_ref,pc.intent_id)=(i.account_ref,i.id)WHERE pc.callback_alias IS NULL AND pc.provider_id LIKE'deleted-%'AND i.state IN('leased','provider_call_started')ON CONFLICT(account_ref,intent_id,event_key)DO NOTHING;
INSERT INTO followup_transitions(account_ref,followup_id,event_key,from_state,to_state,reason,details) SELECT f.account_ref,f.id,'legacy-callback-alias-missing',f.state,'reconciliation_required','legacy_callback_alias_missing','{}'::jsonb FROM followups f JOIN intents i ON(i.account_ref,i.id)=(f.account_ref,f.intent_id)JOIN provider_calls pc ON(pc.account_ref,pc.intent_id)=(i.account_ref,i.id)WHERE pc.callback_alias IS NULL AND pc.provider_id LIKE'deleted-%'AND i.state IN('leased','provider_call_started')AND f.state IN('due','claimed','retry','intent_created','call_started')ON CONFLICT(account_ref,followup_id,event_key)DO NOTHING;
UPDATE followups f SET state='reconciliation_required',reason='legacy_callback_alias_missing',claim=NULL,claim_until=NULL,next_attempt=NULL FROM intents i JOIN provider_calls pc ON(pc.account_ref,pc.intent_id)=(i.account_ref,i.id)WHERE(f.account_ref,f.intent_id)=(i.account_ref,i.id)AND pc.callback_alias IS NULL AND pc.provider_id LIKE'deleted-%'AND i.state IN('leased','provider_call_started');
UPDATE intents i SET state='reconciliation_required',reason='legacy_callback_alias_missing',lease=NULL,lease_until=NULL FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(i.account_ref,i.id)AND pc.callback_alias IS NULL AND pc.provider_id LIKE'deleted-%'AND i.state IN('leased','provider_call_started');
CREATE UNIQUE INDEX IF NOT EXISTS provider_calls_callback_alias_unique ON provider_calls(account_ref,callback_alias)WHERE callback_alias IS NOT NULL;

CREATE OR REPLACE FUNCTION followup_evidence_immutable_guard()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION'follow-up evidence append-only';END IF;
 IF (NEW.account_ref,NEW.id,NEW.contact_id,NEW.conversation_id,NEW.due_at,NEW.expected_version,NEW.template_key,NEW.source_intent_id,NEW.action_key,NEW.request_hash,NEW.generation,NEW.source_conversation_version,NEW.scheduled_from_sent_at,NEW.release_set_version,NEW.policy_version,NEW.knowledge_version,NEW.consent_occurred_at,NEW.consent_evidence_hash,NEW.content_ref,NEW.correlation_id,NEW.campaign_identity,NEW.campaign_snapshot)IS DISTINCT FROM(OLD.account_ref,OLD.id,OLD.contact_id,OLD.conversation_id,OLD.due_at,OLD.expected_version,OLD.template_key,OLD.source_intent_id,OLD.action_key,OLD.request_hash,OLD.generation,OLD.source_conversation_version,OLD.scheduled_from_sent_at,OLD.release_set_version,OLD.policy_version,OLD.knowledge_version,OLD.consent_occurred_at,OLD.consent_evidence_hash,OLD.content_ref,OLD.correlation_id,OLD.campaign_identity,OLD.campaign_snapshot)THEN RAISE EXCEPTION'follow-up evidence immutable';END IF;
 IF OLD.state IN('cancelled','delivered','failed','superseded','denied','exhausted','suppressed','legacy_unverifiable')AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION'terminal follow-up immutable';END IF;IF OLD.state='sent'AND NEW.state NOT IN('sent','delivered','failed')THEN RAISE EXCEPTION'illegal follow-up status regression';END IF;RETURN NEW;END$$;
DROP TRIGGER IF EXISTS followup_evidence_immutable ON followups;
CREATE TRIGGER followup_evidence_immutable BEFORE UPDATE OR DELETE ON followups FOR EACH ROW EXECUTE FUNCTION followup_evidence_immutable_guard();
DROP TRIGGER IF EXISTS followup_transitions_immutable ON followup_transitions;
CREATE TRIGGER followup_transitions_immutable BEFORE UPDATE OR DELETE ON followup_transitions FOR EACH ROW EXECUTE FUNCTION immutable();
DROP TRIGGER IF EXISTS followup_busy_events_immutable ON followup_busy_events;
CREATE TRIGGER followup_busy_events_immutable BEFORE UPDATE OR DELETE ON followup_busy_events FOR EACH ROW EXECUTE FUNCTION immutable();
DROP TRIGGER IF EXISTS reconciliation_busy_events_immutable ON reconciliation_busy_events;
CREATE TRIGGER reconciliation_busy_events_immutable BEFORE UPDATE OR DELETE ON reconciliation_busy_events FOR EACH ROW EXECUTE FUNCTION immutable();

DROP FUNCTION IF EXISTS provider_call_immutable_guard();
CREATE FUNCTION provider_call_immutable_guard()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF TG_OP='UPDATE'AND current_setting('salesflow.deletion_mode',true)='on'AND(NEW.account_ref,NEW.intent_id,NEW.attempt_no,NEW.lease,NEW.correlation_id,NEW.release_set_version,NEW.started_at,NEW.callback_alias)IS NOT DISTINCT FROM(OLD.account_ref,OLD.intent_id,OLD.attempt_no,OLD.lease,OLD.correlation_id,OLD.release_set_version,OLD.started_at,OLD.callback_alias)AND NEW.provider_id='deleted-'||OLD.intent_id::text THEN RETURN NEW;END IF;RAISE EXCEPTION'append-only';END$$;
CREATE TRIGGER provider_calls_immutable BEFORE UPDATE OR DELETE ON provider_calls FOR EACH ROW EXECUTE FUNCTION provider_call_immutable_guard();

CREATE OR REPLACE FUNCTION followup_conversation_key(acct text,conv uuid)RETURNS bigint LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$SELECT hashtextextended(acct||':followup-conversation:'||conv::text,0)$$;
CREATE OR REPLACE FUNCTION followup_lock_conversation(acct text,conv uuid)RETURNS void LANGUAGE sql AS $$SELECT pg_advisory_xact_lock(followup_conversation_key(acct,conv))$$;
CREATE OR REPLACE FUNCTION followup_authority_keys(acct text,contact uuid)RETURNS bigint[] LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$SELECT array_agg(k ORDER BY k)FROM(SELECT DISTINCT unnest(ARRAY[hashtextextended(acct||':control:stop',0),hashtextextended(acct||':consent:'||contact::text,0),hashtextextended(acct||':consent_templates',0),hashtextextended(acct||':product_knowledge',0),hashtextextended(acct||':release_set',0),hashtextextended(acct||':retry',0),hashtextextended(acct||':sales_policy',0)])k)s$$;
CREATE OR REPLACE FUNCTION followup_set_lock_deadline(deadline timestamptz)RETURNS void LANGUAGE plpgsql AS $$DECLARE remaining_ms int;BEGIN remaining_ms:=floor(extract(epoch FROM deadline-clock_timestamp())*1000);IF remaining_ms<=0 THEN RAISE EXCEPTION USING ERRCODE='55P03',MESSAGE='lock deadline exceeded';END IF;PERFORM set_config('lock_timeout',remaining_ms::text||'ms',true);END$$;
CREATE OR REPLACE FUNCTION followup_lock_authorities(acct text,contact uuid)RETURNS void LANGUAGE plpgsql AS $$DECLARE k bigint;deadline timestamptz:=clock_timestamp()+current_setting('lock_timeout')::interval;BEGIN FOREACH k IN ARRAY followup_authority_keys(acct,contact)LOOP PERFORM followup_set_lock_deadline(deadline);PERFORM pg_advisory_xact_lock(k);END LOOP;END$$;

DROP FUNCTION IF EXISTS followup_request_payload(followups);
DROP FUNCTION IF EXISTS followup_request_payload(text,uuid,timestamptz,bigint,text,text,text,timestamptz,text,text,uuid,int,text,jsonb);
DROP FUNCTION IF EXISTS followup_request_payload(text,uuid,uuid,uuid,timestamptz,bigint,text,text,text,timestamptz,text,text,uuid,int,text,jsonb);
DROP FUNCTION IF EXISTS followup_request_payload(text,uuid,uuid,uuid,timestamptz,bigint,text,text,text,timestamptz,text,text,uuid,int,text,jsonb,text,bigint,text);
CREATE FUNCTION followup_request_payload(acct text,source_intent uuid,contact uuid,conversation uuid,due timestamptz,expected bigint,release_version text,policy_version text,knowledge_version text,consent_at timestamptz,consent_hash text,content text,corr uuid,gen int,campaign_id text,campaign_data jsonb,action text,source_version bigint,template text)RETURNS jsonb LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$SELECT jsonb_build_object('accountRef',acct,'sourceIntentId',source_intent,'contactId',contact,'conversationId',conversation,'dueAt',due,'expectedVersion',expected,'releaseSetVersion',release_version,'policyVersion',policy_version,'knowledgeVersion',knowledge_version,'consentOccurredAt',consent_at,'consentEvidenceHash',consent_hash,'contentRef',content,'correlationId',corr,'generation',gen,'campaignIdentity',campaign_id,'campaignSnapshot',campaign_data,'actionKey',action,'sourceConversationVersion',source_version,'templateKey',template)$$;
CREATE OR REPLACE FUNCTION followup_request_payload(f followups)RETURNS jsonb LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$SELECT followup_request_payload(f.account_ref,f.source_intent_id,f.contact_id,f.conversation_id,f.due_at,f.expected_version,f.release_set_version,f.policy_version,f.knowledge_version,f.consent_occurred_at,f.consent_evidence_hash,f.content_ref,f.correlation_id,f.generation,f.campaign_identity,f.campaign_snapshot,f.action_key,f.source_conversation_version,f.template_key)$$;
CREATE OR REPLACE FUNCTION followup_evidence_valid(f followups)RETURNS boolean LANGUAGE sql STABLE AS $$SELECT COALESCE(f.source_intent_id IS NOT NULL AND f.action_key IS NOT NULL AND f.request_hash~'^[0-9a-f]{64}$'AND f.generation>0 AND f.source_conversation_version IS NOT NULL AND f.scheduled_from_sent_at IS NOT NULL AND f.scheduled_from_sent_at=(SELECT min(it.at)FROM intent_transitions it WHERE(it.account_ref,it.intent_id,it.to_state)=(f.account_ref,f.source_intent_id,'sent'))AND f.release_set_version=(SELECT pc.release_set_version FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(f.account_ref,f.source_intent_id))AND f.due_at=f.scheduled_from_sent_at+interval'12 hours'AND COALESCE(f.release_set_version,'')<>''AND COALESCE(f.policy_version,'')<>''AND COALESCE(f.knowledge_version,'')<>''AND f.consent_occurred_at IS NOT NULL AND f.consent_evidence_hash~'^[0-9a-f]{64}$'AND COALESCE(f.content_ref,'')<>''AND f.content_ref IS NOT DISTINCT FROM f.template_key AND f.correlation_id IS NOT NULL AND COALESCE(f.campaign_identity,'')<>''AND jsonb_typeof(f.campaign_snapshot)='object'AND f.request_hash=encode(digest(followup_request_payload(f)::text,'sha256'),'hex'),false)$$;

CREATE OR REPLACE FUNCTION transition_followup_parent_first(acct text,followup uuid,target text,why text,extra jsonb DEFAULT'{}')RETURNS jsonb LANGUAGE plpgsql AS $$DECLARE f followups;old text;BEGIN SELECT*INTO f FROM followups WHERE(account_ref,id)=(acct,followup)FOR UPDATE;IF NOT FOUND OR f.state IN('cancelled','delivered','failed','superseded','denied','exhausted','suppressed','legacy_unverifiable')OR(f.state='sent'AND target NOT IN('delivered','failed'))THEN RETURN jsonb_build_object('changed',false,'state',f.state);END IF;old:=f.state;UPDATE followups SET state=target,reason=why,claim=NULL,claim_until=NULL,next_attempt=CASE WHEN target='retry'THEN next_attempt ELSE NULL END WHERE(account_ref,id)=(acct,followup);INSERT INTO followup_transitions(account_ref,followup_id,event_key,from_state,to_state,reason,details)VALUES(acct,followup,target||'-'||encode(digest(why||':'||clock_timestamp()::text,'sha256'),'hex'),old,target,why,COALESCE(extra,'{}'));IF target IN('cancelled','superseded','denied','exhausted','suppressed','legacy_unverifiable','failed')AND f.intent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(acct,f.intent_id))THEN UPDATE intents SET state='suppressed',reason=why,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,f.intent_id)AND state IN('pending','leased');END IF;RETURN jsonb_build_object('changed',true,'from',old,'state',target);END$$;
DO $$DECLARE f followups;i intents;has_call bool;intent_found bool;old text;BEGIN FOR f IN SELECT x.*FROM followups x WHERE x.state IN('due','claimed','retry','intent_created','call_started','reconciliation_required')AND NOT followup_evidence_valid(x)ORDER BY x.account_ref,x.conversation_id,x.id LOOP SELECT*INTO i FROM intents WHERE(account_ref,id)=(f.account_ref,f.intent_id);intent_found:=FOUND;SELECT f.intent_id IS NOT NULL AND EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(f.account_ref,f.intent_id))INTO has_call;IF has_call THEN IF intent_found AND i.state IN('sent','failed')THEN PERFORM transition_followup_parent_first(f.account_ref,f.id,i.state,'legacy_terminal_child_preserved',jsonb_build_object('migration',true,'childState',i.state));ELSE IF f.state<>'reconciliation_required'THEN PERFORM transition_followup_parent_first(f.account_ref,f.id,'reconciliation_required','legacy_unverifiable',jsonb_build_object('migration',true));END IF;IF intent_found AND i.state<>'reconciliation_required'THEN old:=i.state;INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason,at)VALUES(i.account_ref,i.id,old,'reconciliation_required','legacy_unverifiable',clock_timestamp());UPDATE intents SET state='reconciliation_required',reason='legacy_unverifiable',lease=NULL,lease_until=NULL WHERE(account_ref,id)=(i.account_ref,i.id);END IF;IF intent_found THEN INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason,details)VALUES(i.account_ref,i.id,'migration-request-hash-upgrade','reconciliation_required','legacy_unverifiable',jsonb_build_object('preservedState',i.state))ON CONFLICT DO NOTHING;END IF;END IF;ELSE PERFORM transition_followup_parent_first(f.account_ref,f.id,'legacy_unverifiable','legacy_unverifiable',jsonb_build_object('migration',true));END IF;END LOOP;END$$;
CREATE OR REPLACE FUNCTION cancel_followups_for_conversation(acct text,conv uuid,why text,source uuid DEFAULT NULL)RETURNS int LANGUAGE plpgsql AS $$DECLARE f record;n int:=0;r jsonb;contact uuid;lock_deadline timestamptz;BEGIN SELECT contact_id INTO contact FROM conversations WHERE(account_ref,id)=(acct,conv);IF NOT FOUND THEN RETURN 0;END IF;PERFORM set_config('lock_timeout','1s',true);lock_deadline:=clock_timestamp()+interval'1s';PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(acct,conv);PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(acct,contact);FOR f IN SELECT id FROM followups WHERE account_ref=acct AND conversation_id=conv AND state IN('due','claimed','retry','intent_created')AND(source IS NULL OR source_intent_id IS DISTINCT FROM source)ORDER BY id FOR UPDATE LOOP r:=transition_followup_parent_first(acct,f.id,'cancelled',why,'{}');IF COALESCE((r->>'changed')::bool,false)THEN n:=n+1;END IF;END LOOP;RETURN n;END$$;

-- Human takeover cancels pre-call work under the same conversation lock as call-start.
-- Preserve started calls and their eventual outcome; handoff dispatcher work is internal.
CREATE OR REPLACE FUNCTION suppress_automation_for_human(acct text,conv uuid,why text DEFAULT 'human_owned')RETURNS void LANGUAGE plpgsql AS $$DECLARE i record;BEGIN
 PERFORM cancel_followups_for_conversation(acct,conv,why,NULL);
 FOR i IN SELECT x.id,x.state FROM intents x WHERE x.account_ref=acct AND x.conversation_id=conv AND x.kind<>'followup'AND x.state IN('pending','leased','retry')AND NOT EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(acct,x.id))ORDER BY x.id FOR UPDATE OF x LOOP
  UPDATE intents SET state='suppressed',reason=why,lease=NULL,lease_until=NULL,next_attempt=NULL WHERE(account_ref,id)=(acct,i.id);
  INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason,at)VALUES(acct,i.id,i.state,'suppressed',why,clock_timestamp());
 END LOOP;
END$$;

-- Close pre-SP3-T4 automation already attached to Human-Owned conversations.
-- Reapplying the migration is safe because only active pre-call rows are selected.
DO $$DECLARE v record;BEGIN
 FOR v IN SELECT account_ref,id,lifecycle FROM conversations WHERE owner='human'ORDER BY account_ref,id LOOP
  PERFORM suppress_automation_for_human(v.account_ref,v.id,CASE WHEN v.lifecycle<>'active'THEN v.lifecycle ELSE'human_owned'END);
 END LOOP;
END$$;

CREATE OR REPLACE FUNCTION followup_schedule_authorization_reason(i intents,at_time timestamptz DEFAULT clock_timestamp())RETURNS text LANGUAGE plpgsql STABLE AS $$DECLARE v conversations;stop bool;stop_control jsonb;ce consent_events;rs config_docs;pol config_docs;know config_docs;ct jsonb;BEGIN
 IF i.kind<>'reply'OR i.state<>'sent'THEN RETURN'not_sent_reply';END IF;
 IF NOT EXISTS(SELECT 1 FROM accounts WHERE id=i.account_ref AND enabled)THEN RETURN'account_disabled';END IF;
 SELECT value INTO stop_control FROM controls WHERE account_ref=i.account_ref AND key='stop';IF NOT FOUND THEN RETURN'missing_control';ELSIF jsonb_typeof(stop_control->'enabled')IS DISTINCT FROM'boolean'THEN RETURN'invalid_control';END IF;stop:=(stop_control->>'enabled')::bool;IF stop THEN RETURN'global_stop';END IF;
 SELECT*INTO v FROM conversations WHERE(account_ref,id)=(i.account_ref,i.conversation_id);IF NOT FOUND THEN RETURN'conversation_missing';ELSIF v.lifecycle<>'active'THEN RETURN v.lifecycle;ELSIF v.owner<>'ai'THEN RETURN'human_owned';ELSIF NOT v.campaign THEN RETURN'campaign_disabled';ELSIF v.version<>i.expected_version THEN RETURN'stale_version';END IF;
 SELECT*INTO ce FROM consent_events WHERE(account_ref,contact_id)=(i.account_ref,i.contact_id)ORDER BY occurred_at DESC LIMIT 1;IF NOT FOUND OR ce.status<>'granted'THEN RETURN'consent_missing';ELSIF i.provenance#>>'{context,consentOccurredAt}'IS DISTINCT FROM to_jsonb(ce.occurred_at)#>>'{}'OR i.provenance#>>'{context,consentEvidenceHash}'IS DISTINCT FROM encode(digest(ce.evidence,'sha256'),'hex')THEN RETURN'consent_changed';END IF;
 SELECT*INTO rs FROM config_docs WHERE account_ref=i.account_ref AND kind='release_set'AND active;IF NOT FOUND OR rs.version IS DISTINCT FROM i.provenance#>>'{context,releaseSetVersion}'THEN RETURN'inconsistent_business_context';END IF;
 SELECT*INTO pol FROM config_docs WHERE account_ref=i.account_ref AND kind='sales_policy'AND active;IF NOT FOUND OR pol.version IS DISTINCT FROM i.policy_version OR rs.body->>'policyVersion'IS DISTINCT FROM pol.version THEN RETURN'policy_invalid';ELSIF NOT COALESCE((pol.body->>'campaignEnabled')::bool,false)THEN RETURN'campaign_disabled';END IF;
 SELECT*INTO know FROM config_docs WHERE account_ref=i.account_ref AND kind='product_knowledge'AND active;IF NOT FOUND OR know.version IS DISTINCT FROM i.knowledge_version OR rs.body->>'knowledgeVersion'IS DISTINCT FROM know.version THEN RETURN'knowledge_invalid';END IF;
 SELECT body INTO ct FROM config_docs WHERE account_ref=i.account_ref AND kind='consent_templates'AND active;IF ct IS NULL THEN RETURN'missing_consent_config';ELSIF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(ct->'templates')x WHERE x->>'key'='followup-en'AND COALESCE((x->>'approved')::bool,false)AND x->>'providerTemplateId'='followup-en'AND x->>'category'='marketing'AND x->>'language'='en')THEN RETURN'template_invalid';END IF;
 IF NOT EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(i.account_ref,i.id))THEN RETURN'provider_call_missing';END IF;RETURN'authorized';END$$;

CREATE OR REPLACE FUNCTION create_followup_after_sent()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE why text;src intents;v conversations;ce consent_events;sent_at timestamptz;due timestamptz;gen int;corr uuid;release_version text;content text:='followup-en';action text;campaign_id text;campaign_data jsonb;payload jsonb;fid uuid;oldf record;BEGIN
 IF NEW.kind<>'reply'OR NEW.state<>'sent'OR OLD.state='sent'THEN RETURN NEW;END IF;
 SELECT*INTO v FROM conversations WHERE(account_ref,id)=(NEW.account_ref,NEW.conversation_id)FOR SHARE;SELECT*INTO src FROM intents WHERE(account_ref,id)=(NEW.account_ref,NEW.id);why:=followup_schedule_authorization_reason(src,clock_timestamp());IF why<>'authorized'THEN INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(NEW.account_ref,'followup_not_scheduled',why,'system',jsonb_build_object('sourceIntentId',NEW.id));RETURN NEW;END IF;
 SELECT*INTO ce FROM consent_events WHERE(account_ref,contact_id)=(NEW.account_ref,NEW.contact_id)ORDER BY occurred_at DESC LIMIT 1;SELECT correlation_id INTO corr FROM provider_calls WHERE(account_ref,intent_id)=(NEW.account_ref,NEW.id);SELECT min(at)INTO sent_at FROM intent_transitions WHERE(account_ref,intent_id)=(NEW.account_ref,NEW.id)AND to_state='sent';IF sent_at IS NULL THEN INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(NEW.account_ref,'followup_not_scheduled','sent_evidence_missing','system',jsonb_build_object('sourceIntentId',NEW.id));RETURN NEW;END IF;due:=sent_at+interval'12 hours';release_version:=NEW.provenance#>>'{context,releaseSetVersion}';campaign_id:=NEW.account_ref||':'||NEW.conversation_id::text||':'||release_version;campaign_data:=jsonb_build_object('conversationEnabled',v.campaign,'policyEnabled',true);SELECT COALESCE(max(generation),0)+1 INTO gen FROM followups WHERE account_ref=NEW.account_ref AND conversation_id=NEW.conversation_id;
 FOR oldf IN SELECT id FROM followups WHERE account_ref=NEW.account_ref AND conversation_id=NEW.conversation_id AND source_intent_id IS DISTINCT FROM NEW.id AND state IN('due','claimed','retry','intent_created')ORDER BY id FOR UPDATE LOOP PERFORM transition_followup_parent_first(NEW.account_ref,oldf.id,'superseded','newer_sent_reply',jsonb_build_object('sourceIntentId',NEW.id));END LOOP;
 action:='followup:'||NEW.id::text;payload:=followup_request_payload(NEW.account_ref,NEW.id,NEW.contact_id,NEW.conversation_id,due,NEW.expected_version,release_version,NEW.policy_version,NEW.knowledge_version,ce.occurred_at,encode(digest(ce.evidence,'sha256'),'hex'),content,corr,gen,campaign_id,campaign_data,action,v.version,content);
 INSERT INTO followups(account_ref,contact_id,conversation_id,due_at,expected_version,template_key,state,source_intent_id,action_key,request_hash,generation,source_conversation_version,scheduled_from_sent_at,release_set_version,policy_version,knowledge_version,consent_occurred_at,consent_evidence_hash,content_ref,correlation_id,campaign_identity,campaign_snapshot)VALUES(NEW.account_ref,NEW.contact_id,NEW.conversation_id,due,NEW.expected_version,content,'due',NEW.id,action,encode(digest(payload::text,'sha256'),'hex'),gen,v.version,sent_at,release_version,NEW.policy_version,NEW.knowledge_version,ce.occurred_at,encode(digest(ce.evidence,'sha256'),'hex'),content,corr,campaign_id,campaign_data)ON CONFLICT(account_ref,source_intent_id)WHERE source_intent_id IS NOT NULL DO NOTHING RETURNING id INTO fid;
 IF fid IS NOT NULL THEN INSERT INTO followup_transitions(account_ref,followup_id,event_key,from_state,to_state,reason,details)VALUES(NEW.account_ref,fid,'scheduled','none','due','scheduled',jsonb_build_object('sourceIntentId',NEW.id,'dueAt',due,'correlationId',corr));END IF;RETURN NEW;END$$;
DROP TRIGGER IF EXISTS create_followup_after_sent ON intents;
CREATE TRIGGER create_followup_after_sent AFTER UPDATE OF state ON intents FOR EACH ROW EXECUTE FUNCTION create_followup_after_sent();

CREATE OR REPLACE FUNCTION followup_due_authorization_reason(f followups,at_time timestamptz DEFAULT clock_timestamp())RETURNS text LANGUAGE plpgsql STABLE AS $$DECLARE v conversations;stop bool;stop_control jsonb;ce consent_events;rs config_docs;pol config_docs;know config_docs;retry jsonb;ct jsonb;template_hours int;last_inbound timestamptz;hr int;freq int;BEGIN
 IF NOT followup_evidence_valid(f)THEN RETURN'legacy_unverifiable';END IF;IF NOT EXISTS(SELECT 1 FROM intents source_i JOIN provider_calls source_pc ON(source_pc.account_ref,source_pc.intent_id)=(source_i.account_ref,source_i.id)WHERE(source_i.account_ref,source_i.id)=(f.account_ref,f.source_intent_id)AND source_i.contact_id=f.contact_id AND source_i.conversation_id=f.conversation_id AND source_i.kind='reply'AND source_i.state='sent'AND source_i.expected_version=f.expected_version AND source_i.policy_version=f.policy_version AND source_i.knowledge_version=f.knowledge_version AND source_pc.correlation_id=f.correlation_id)THEN RETURN'followup_evidence_invalid';END IF;IF NOT EXISTS(SELECT 1 FROM accounts WHERE id=f.account_ref AND enabled)THEN RETURN'account_disabled';END IF;IF NOT EXISTS(SELECT 1 FROM contact_identifiers ci WHERE(ci.account_ref,ci.contact_id)=(f.account_ref,f.contact_id)AND ci.channel='whatsapp'AND ci.provider='meta'AND ci.active AND ci.retired_at IS NULL AND ci.external_ref NOT LIKE'deleted-%')THEN RETURN'contact_identifier_missing';END IF;
 SELECT value INTO stop_control FROM controls WHERE account_ref=f.account_ref AND key='stop';IF NOT FOUND THEN RETURN'missing_control';ELSIF jsonb_typeof(stop_control->'enabled')IS DISTINCT FROM'boolean'THEN RETURN'invalid_control';END IF;stop:=(stop_control->>'enabled')::bool;IF stop THEN RETURN'global_stop';END IF;
 SELECT*INTO v FROM conversations WHERE(account_ref,id)=(f.account_ref,f.conversation_id);IF NOT FOUND THEN RETURN'conversation_missing';ELSIF v.lifecycle<>'active'THEN RETURN v.lifecycle;ELSIF v.owner<>'ai'THEN RETURN'human_owned';ELSIF NOT v.campaign THEN RETURN'campaign_disabled';ELSIF v.version<>f.source_conversation_version OR v.version<>f.expected_version THEN RETURN'stale_version';ELSIF f.campaign_identity IS DISTINCT FROM f.account_ref||':'||f.conversation_id::text||':'||f.release_set_version OR f.campaign_snapshot IS DISTINCT FROM jsonb_build_object('conversationEnabled',true,'policyEnabled',true)THEN RETURN'campaign_changed';END IF;
 SELECT*INTO ce FROM consent_events WHERE(account_ref,contact_id)=(f.account_ref,f.contact_id)ORDER BY occurred_at DESC LIMIT 1;IF NOT FOUND OR ce.status<>'granted'THEN RETURN'consent_missing';ELSIF ce.occurred_at<>f.consent_occurred_at OR encode(digest(ce.evidence,'sha256'),'hex')<>f.consent_evidence_hash THEN RETURN'consent_changed';END IF;
 SELECT*INTO rs FROM config_docs WHERE account_ref=f.account_ref AND kind='release_set'AND active;IF NOT FOUND OR rs.version<>f.release_set_version THEN RETURN'inconsistent_business_context';END IF;SELECT*INTO pol FROM config_docs WHERE account_ref=f.account_ref AND kind='sales_policy'AND active;IF NOT FOUND OR pol.version<>f.policy_version OR rs.body->>'policyVersion'<>pol.version THEN RETURN'policy_invalid';ELSIF NOT COALESCE((pol.body->>'campaignEnabled')::bool,false)THEN RETURN'campaign_disabled';END IF;SELECT*INTO know FROM config_docs WHERE account_ref=f.account_ref AND kind='product_knowledge'AND active;IF NOT FOUND OR know.version<>f.knowledge_version OR rs.body->>'knowledgeVersion'<>know.version THEN RETURN'knowledge_invalid';END IF;
 SELECT body INTO retry FROM config_docs WHERE account_ref=f.account_ref AND kind='retry'AND active;IF retry IS NULL THEN RETURN'missing_retry';ELSIF f.state IN('due','claimed','retry')AND f.attempts>=COALESCE((retry->>'maxAttempts')::int,0)THEN RETURN'retry_exhausted';END IF;
 SELECT body INTO ct FROM config_docs WHERE account_ref=f.account_ref AND kind='consent_templates'AND active;IF ct IS NULL THEN RETURN'missing_consent_config';END IF;SELECT(x->>'windowHours')::int INTO template_hours FROM jsonb_array_elements(ct->'templates')x WHERE x->>'key'=f.content_ref AND COALESCE((x->>'approved')::bool,false)AND x->>'providerTemplateId'='followup-en'AND x->>'category'='marketing'AND x->>'language'='en';IF template_hours IS NULL THEN RETURN'template_invalid';END IF;SELECT max(received_at)INTO last_inbound FROM inbound_messages WHERE account_ref=f.account_ref AND conversation_id=f.conversation_id;IF last_inbound IS NULL OR last_inbound<at_time-make_interval(hours=>template_hours)THEN RETURN'template_window_closed';END IF;
 hr:=extract(hour from at_time AT TIME ZONE'UTC');IF(pol.body#>>'{quietHoursUtc,start}')::int<>(pol.body#>>'{quietHoursUtc,end}')::int AND(((pol.body#>>'{quietHoursUtc,start}')::int<(pol.body#>>'{quietHoursUtc,end}')::int AND hr>=(pol.body#>>'{quietHoursUtc,start}')::int AND hr<(pol.body#>>'{quietHoursUtc,end}')::int)OR((pol.body#>>'{quietHoursUtc,start}')::int>(pol.body#>>'{quietHoursUtc,end}')::int AND(hr>=(pol.body#>>'{quietHoursUtc,start}')::int OR hr<(pol.body#>>'{quietHoursUtc,end}')::int)))THEN RETURN'quiet_hours';END IF;
 SELECT count(*)INTO freq FROM provider_calls pc JOIN intents i ON(i.account_ref,i.id)=(pc.account_ref,pc.intent_id)WHERE pc.account_ref=f.account_ref AND i.contact_id=f.contact_id AND pc.started_at>at_time-interval'24h';IF freq>=(pol.body->>'frequencyCap24h')::int THEN RETURN'frequency_cap';END IF;RETURN'authorized';END$$;

CREATE OR REPLACE FUNCTION followup_child_evidence_valid(i intents,f followups)RETURNS boolean LANGUAGE sql IMMUTABLE AS $$SELECT i.account_ref IS NOT DISTINCT FROM f.account_ref AND i.contact_id IS NOT DISTINCT FROM f.contact_id AND i.conversation_id IS NOT DISTINCT FROM f.conversation_id AND i.source_id IS NOT DISTINCT FROM f.id AND i.kind='followup'AND i.expected_version IS NOT DISTINCT FROM f.expected_version AND i.policy_version IS NOT DISTINCT FROM f.policy_version AND i.knowledge_version IS NOT DISTINCT FROM f.knowledge_version AND i.body='Synthetic follow-up.'AND i.template_key IS NOT DISTINCT FROM f.template_key AND i.provenance IS NOT DISTINCT FROM jsonb_build_object('sourceIds',jsonb_build_array('source-1'),'offerId','offer-1','claims',jsonb_build_array('service-count'),'confidence',1.0,'context',jsonb_build_object('releaseSetVersion',f.release_set_version,'consentOccurredAt',f.consent_occurred_at,'consentEvidenceHash',f.consent_evidence_hash,'followupId',f.id,'followupCorrelationId',f.correlation_id,'campaignIdentity',f.campaign_identity,'campaignSnapshot',f.campaign_snapshot,'actionKey',f.action_key,'sourceConversationVersion',f.source_conversation_version,'templateKey',f.template_key,'requestHash',f.request_hash))$$;

CREATE OR REPLACE FUNCTION followup_final_authorization_reason(acct text,work uuid,trusted_at timestamptz DEFAULT clock_timestamp())RETURNS text LANGUAGE plpgsql STABLE AS $$DECLARE i intents;f followups;why text;retry jsonb;BEGIN SELECT*INTO i FROM intents WHERE(account_ref,id)=(acct,work);IF NOT FOUND OR i.kind<>'followup'THEN RETURN'followup_intent_missing';END IF;SELECT*INTO f FROM followups WHERE(account_ref,intent_id)=(acct,work);IF NOT FOUND THEN RETURN'followup_parent_missing';ELSIF f.state NOT IN('intent_created','call_started','reconciliation_required')THEN RETURN'followup_not_active';END IF;why:=followup_due_authorization_reason(f,trusted_at);IF why<>'authorized'THEN RETURN why;END IF;IF NOT followup_child_evidence_valid(i,f)THEN RETURN'followup_evidence_invalid';END IF;SELECT body INTO retry FROM config_docs WHERE account_ref=acct AND kind='retry'AND active;IF retry IS NULL THEN RETURN'missing_retry';ELSIF i.attempts>COALESCE((retry->>'maxAttempts')::int,0)THEN RETURN'retry_exhausted';END IF;RETURN authorization_reason(acct,i,trusted_at);END$$;

CREATE OR REPLACE FUNCTION try_claim_followup_candidate(acct text,followup uuid)RETURNS TABLE(candidate_id uuid,authority_keys bigint[],busy_kind text)LANGUAGE plpgsql AS $$DECLARE f followups;k bigint;problem text;BEGIN
 SELECT*INTO f FROM followups WHERE(account_ref,id)=(acct,followup);IF NOT FOUND THEN RETURN;END IF;problem:=NULL;
 BEGIN
  IF NOT pg_try_advisory_xact_lock(followup_conversation_key(acct,f.conversation_id))THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='authority_busy';END IF;
  authority_keys:=followup_authority_keys(acct,f.contact_id);FOREACH k IN ARRAY authority_keys LOOP IF NOT pg_try_advisory_xact_lock(k)THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='authority_busy';END IF;END LOOP;
  PERFORM 1 FROM followups WHERE(account_ref,id)=(acct,followup)FOR UPDATE NOWAIT;
 EXCEPTION WHEN SQLSTATE'P0001'THEN problem:='authority_busy';WHEN lock_not_available THEN problem:='row_busy';END;
 IF problem IS NOT NULL THEN BEGIN INSERT INTO followup_busy_events(account_ref,followup_id,busy_kind,details)VALUES(acct,followup,problem,jsonb_build_object('observedAt',clock_timestamp()))ON CONFLICT DO NOTHING;EXCEPTION WHEN lock_not_available THEN NULL;END;candidate_id:=NULL;authority_keys:=ARRAY[]::bigint[];busy_kind:=problem;RETURN NEXT;RETURN;END IF;
 candidate_id:=followup;busy_kind:=NULL;RETURN NEXT;
END$$;

CREATE OR REPLACE FUNCTION schedule_followups(t text,n timestamptz DEFAULT now())RETURNS TABLE(account_ref text,work_id uuid)LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$#variable_conflict use_column
DECLARE a record;candidate record;probe record;f followups;retry jsonb;i intents;trusted_at timestamptz;why text;processed int:=0;cursor_row scheduler_cursors;cursor_due timestamptz;cursor_acct text;cursor_id uuid;start_due timestamptz;start_acct text;start_id uuid;high_due timestamptz;high_acct text;high_id uuid;cursor_stamp timestamptz;phase int:=0;scanned bool:=false;cursor_dirty bool:=false;old_state text;deadline timestamptz:=clock_timestamp()+interval'4 seconds';
BEGIN SELECT*INTO a FROM actor_for(t,'scheduler');IF NOT FOUND THEN RETURN;END IF;PERFORM set_config('statement_timeout','12s',true);PERFORM set_config('lock_timeout','500ms',true);INSERT INTO scheduler_cursors(name)VALUES('followup-due')ON CONFLICT(name)DO NOTHING;SELECT*INTO cursor_row FROM scheduler_cursors WHERE name='followup-due';cursor_due:=cursor_row.last_sort_at;cursor_acct:=cursor_row.last_account_ref;cursor_id:=cursor_row.last_work_id;start_due:=cursor_row.cycle_start_sort_at;start_acct:=cursor_row.cycle_start_account_ref;start_id:=cursor_row.cycle_start_work_id;high_due:=cursor_row.cycle_high_sort_at;high_acct:=cursor_row.cycle_high_account_ref;high_id:=cursor_row.cycle_high_work_id;phase:=cursor_row.cycle_phase;cursor_stamp:=cursor_row.updated_at;trusted_at:=clock_timestamp();IF high_due='-infinity'THEN start_due:=cursor_due;start_acct:=cursor_acct;start_id:=cursor_id;phase:=0;SELECT x.due_at,x.account_ref,x.id INTO high_due,high_acct,high_id FROM followups x WHERE(x.state='due'OR(x.state='claimed'AND x.claim_until<=trusted_at)OR(x.state='retry'AND x.next_attempt<=trusted_at))AND x.due_at<=trusted_at ORDER BY x.due_at DESC,x.account_ref DESC,x.id DESC LIMIT 1;IF NOT FOUND THEN RETURN;END IF;cursor_dirty:=true;END IF;
 LOOP EXIT WHEN processed>=50 OR clock_timestamp()>=deadline;trusted_at:=clock_timestamp();IF phase=0 THEN SELECT x.account_ref,x.id,x.due_at INTO candidate FROM followups x WHERE(x.state='due'OR(x.state='claimed'AND x.claim_until<=trusted_at)OR(x.state='retry'AND x.next_attempt<=trusted_at))AND x.due_at<=trusted_at AND(x.due_at,x.account_ref,x.id)>(cursor_due,cursor_acct,cursor_id)AND(x.due_at,x.account_ref,x.id)<=(high_due,high_acct,high_id)ORDER BY x.due_at,x.account_ref,x.id LIMIT 1;IF NOT FOUND THEN phase:=1;cursor_due:='-infinity';cursor_acct:='';cursor_id:='00000000-0000-0000-0000-000000000000';cursor_dirty:=true;CONTINUE;END IF;ELSE SELECT x.account_ref,x.id,x.due_at INTO candidate FROM followups x WHERE(x.state='due'OR(x.state='claimed'AND x.claim_until<=trusted_at)OR(x.state='retry'AND x.next_attempt<=trusted_at))AND x.due_at<=trusted_at AND(x.due_at,x.account_ref,x.id)>(cursor_due,cursor_acct,cursor_id)AND(x.due_at,x.account_ref,x.id)<=(start_due,start_acct,start_id)ORDER BY x.due_at,x.account_ref,x.id LIMIT 1;IF NOT FOUND THEN high_due:='-infinity';high_acct:='';high_id:='00000000-0000-0000-0000-000000000000';start_due:='-infinity';start_acct:='';start_id:='00000000-0000-0000-0000-000000000000';phase:=0;cursor_dirty:=true;EXIT;END IF;END IF;cursor_due:=candidate.due_at;cursor_acct:=candidate.account_ref;cursor_id:=candidate.id;scanned:=true;
  SELECT*INTO probe FROM try_claim_followup_candidate(candidate.account_ref,candidate.id);IF probe.candidate_id IS NULL THEN CONTINUE;END IF;
  SELECT*INTO f FROM followups WHERE(account_ref,id)=(candidate.account_ref,candidate.id);trusted_at:=clock_timestamp();IF f.state NOT IN('due','claimed','retry')OR f.due_at>trusted_at OR(f.state='claimed'AND f.claim_until>trusted_at)OR(f.state='retry'AND f.next_attempt>trusted_at)THEN CONTINUE;END IF;
  why:=followup_due_authorization_reason(f,trusted_at);IF why<>'authorized'THEN PERFORM transition_followup_parent_first(f.account_ref,f.id,CASE WHEN why='legacy_unverifiable'THEN'legacy_unverifiable'WHEN why='retry_exhausted'THEN'exhausted'ELSE'denied'END,why,jsonb_build_object('phase','due','trustedAt',trusted_at));CONTINUE;END IF;
  SELECT body INTO retry FROM config_docs WHERE account_ref=f.account_ref AND kind='retry'AND active;old_state:=f.state;UPDATE followups SET state='claimed',reason=NULL,claim=gen_random_uuid(),claim_until=trusted_at+make_interval(secs=>(retry->>'followupClaimSeconds')::int),attempts=attempts+1,next_attempt=NULL WHERE(account_ref,id)=(f.account_ref,f.id)RETURNING*INTO f;INSERT INTO followup_transitions(account_ref,followup_id,event_key,from_state,to_state,reason,details)VALUES(f.account_ref,f.id,'claim-'||f.attempts,old_state,'claimed','claimed',jsonb_build_object('attempt',f.attempts,'trustedAt',trusted_at))ON CONFLICT DO NOTHING;
   INSERT INTO intents(account_ref,contact_id,conversation_id,source_id,kind,expected_version,policy_version,knowledge_version,body,template_key,provenance)VALUES(f.account_ref,f.contact_id,f.conversation_id,f.id,'followup',f.expected_version,f.policy_version,f.knowledge_version,'Synthetic follow-up.',f.template_key,jsonb_build_object('sourceIds',jsonb_build_array('source-1'),'offerId','offer-1','claims',jsonb_build_array('service-count'),'confidence',1.0,'context',jsonb_build_object('releaseSetVersion',f.release_set_version,'consentOccurredAt',f.consent_occurred_at,'consentEvidenceHash',f.consent_evidence_hash,'followupId',f.id,'followupCorrelationId',f.correlation_id,'campaignIdentity',f.campaign_identity,'campaignSnapshot',f.campaign_snapshot,'actionKey',f.action_key,'sourceConversationVersion',f.source_conversation_version,'templateKey',f.template_key,'requestHash',f.request_hash)))ON CONFLICT(account_ref,conversation_id,source_id,kind)DO UPDATE SET body=intents.body RETURNING*INTO i;IF NOT followup_child_evidence_valid(i,f)THEN PERFORM transition_followup_parent_first(f.account_ref,f.id,'denied','followup_evidence_invalid',jsonb_build_object('phase','materialization','intentId',i.id));CONTINUE;END IF;
  UPDATE followups SET state='intent_created',intent_id=i.id,reason=NULL,claim=NULL,claim_until=NULL WHERE(account_ref,id)=(f.account_ref,f.id);INSERT INTO followup_transitions(account_ref,followup_id,event_key,from_state,to_state,reason,details)VALUES(f.account_ref,f.id,'intent-created','claimed','intent_created','authorized',jsonb_build_object('intentId',i.id,'trustedAt',trusted_at,'correlationId',f.correlation_id))ON CONFLICT DO NOTHING;processed:=processed+1;account_ref:=f.account_ref;work_id:=i.id;RETURN NEXT;
 END LOOP;
 IF scanned OR cursor_dirty THEN BEGIN UPDATE scheduler_cursors SET last_sort_at=cursor_due,last_account_ref=cursor_acct,last_work_id=cursor_id,last_workflow_id='',cycle_start_sort_at=start_due,cycle_start_account_ref=start_acct,cycle_start_work_id=start_id,cycle_start_workflow_id='',cycle_high_sort_at=high_due,cycle_high_account_ref=high_acct,cycle_high_work_id=high_id,cycle_high_workflow_id='',cycle_phase=phase,updated_at=clock_timestamp()WHERE name='followup-due'AND updated_at=cursor_stamp;EXCEPTION WHEN lock_not_available THEN NULL;END;END IF;
END$$;

DROP FUNCTION IF EXISTS schedule_work(text,timestamptz);
CREATE FUNCTION schedule_work(t text,n timestamptz DEFAULT now())RETURNS TABLE(account_ref text,work_id uuid,workflow_id text)LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$
DECLARE a record;x record;work_intent intents;f followups;trusted_at timestamptz:=clock_timestamp();deadline timestamptz:=clock_timestamp()+interval'8 seconds';reconciliation_deadline timestamptz:=clock_timestamp()+interval'6 seconds';reconciled int:=0;cursor_row scheduler_cursors;reconcile_at timestamptz;reconcile_account text;reconcile_id uuid;reconcile_start_at timestamptz;reconcile_start_account text;reconcile_start_id uuid;reconcile_high_at timestamptz;reconcile_high_account text;reconcile_high_id uuid;reconcile_stamp timestamptz;reconcile_phase int:=0;reconcile_scanned bool:=false;reconcile_dirty bool:=false;busy_kind text;lock_stage text;cursor_account text;cursor_work uuid;cursor_workflow text;start_account text;start_work uuid;start_workflow text;high_account text;high_work uuid;high_workflow text;projection_stamp timestamptz;projection_phase int:=0;projection_dirty bool:=false;projected int:=0;
BEGIN
 SELECT*INTO a FROM actor_for(t,'scheduler');IF NOT FOUND THEN RAISE EXCEPTION'unauthorized' USING ERRCODE='28000';END IF;PERFORM set_config('statement_timeout','15s',true);PERFORM count(*)FROM schedule_followups(t,trusted_at);PERFORM set_config('statement_timeout','15s',true);
 INSERT INTO scheduler_cursors(name)VALUES('followup-reconciliation')ON CONFLICT(name)DO NOTHING;SELECT*INTO cursor_row FROM scheduler_cursors WHERE name='followup-reconciliation';reconcile_at:=cursor_row.last_sort_at;reconcile_account:=cursor_row.last_account_ref;reconcile_id:=cursor_row.last_work_id;reconcile_start_at:=cursor_row.cycle_start_sort_at;reconcile_start_account:=cursor_row.cycle_start_account_ref;reconcile_start_id:=cursor_row.cycle_start_work_id;reconcile_high_at:=cursor_row.cycle_high_sort_at;reconcile_high_account:=cursor_row.cycle_high_account_ref;reconcile_high_id:=cursor_row.cycle_high_work_id;reconcile_phase:=cursor_row.cycle_phase;reconcile_stamp:=cursor_row.updated_at;trusted_at:=clock_timestamp();IF reconcile_high_at='-infinity'THEN reconcile_start_at:=reconcile_at;reconcile_start_account:=reconcile_account;reconcile_start_id:=reconcile_id;reconcile_phase:=0;SELECT candidate.lease_until,candidate.account_ref,candidate.id INTO reconcile_high_at,reconcile_high_account,reconcile_high_id FROM intents candidate WHERE candidate.state IN('provider_call_started','leased')AND candidate.lease_until<=trusted_at AND EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(candidate.account_ref,candidate.id))ORDER BY candidate.lease_until DESC,candidate.account_ref DESC,candidate.id DESC LIMIT 1;reconcile_dirty:=FOUND;END IF;
 LOOP
  EXIT WHEN reconcile_high_at IS NULL OR reconcile_high_at='-infinity'OR reconciled>=50 OR clock_timestamp()>=reconciliation_deadline;trusted_at:=clock_timestamp();IF reconcile_phase=0 THEN SELECT candidate.account_ref,candidate.id,candidate.conversation_id,candidate.contact_id,candidate.lease_until INTO x FROM intents candidate WHERE candidate.state IN('provider_call_started','leased')AND candidate.lease_until<=trusted_at AND(candidate.lease_until,candidate.account_ref,candidate.id)>(reconcile_at,reconcile_account,reconcile_id)AND(candidate.lease_until,candidate.account_ref,candidate.id)<=(reconcile_high_at,reconcile_high_account,reconcile_high_id)AND EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(candidate.account_ref,candidate.id))ORDER BY candidate.lease_until,candidate.account_ref,candidate.id LIMIT 1;IF NOT FOUND THEN reconcile_phase:=1;reconcile_at:='-infinity';reconcile_account:='';reconcile_id:='00000000-0000-0000-0000-000000000000';reconcile_dirty:=true;CONTINUE;END IF;ELSE SELECT candidate.account_ref,candidate.id,candidate.conversation_id,candidate.contact_id,candidate.lease_until INTO x FROM intents candidate WHERE candidate.state IN('provider_call_started','leased')AND candidate.lease_until<=trusted_at AND(candidate.lease_until,candidate.account_ref,candidate.id)>(reconcile_at,reconcile_account,reconcile_id)AND(candidate.lease_until,candidate.account_ref,candidate.id)<=(reconcile_start_at,reconcile_start_account,reconcile_start_id)AND EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(candidate.account_ref,candidate.id))ORDER BY candidate.lease_until,candidate.account_ref,candidate.id LIMIT 1;IF NOT FOUND THEN reconcile_high_at:='-infinity';reconcile_high_account:='';reconcile_high_id:='00000000-0000-0000-0000-000000000000';reconcile_start_at:='-infinity';reconcile_start_account:='';reconcile_start_id:='00000000-0000-0000-0000-000000000000';reconcile_phase:=0;reconcile_dirty:=true;EXIT;END IF;END IF;reconcile_at:=x.lease_until;reconcile_account:=x.account_ref;reconcile_id:=x.id;reconcile_scanned:=true;busy_kind:=NULL;lock_stage:='authority';
  BEGIN PERFORM set_config('lock_timeout','500ms',true);PERFORM followup_lock_conversation(x.account_ref,x.conversation_id);PERFORM followup_lock_authorities(x.account_ref,x.contact_id);lock_stage:='row';SELECT fu.*INTO f FROM followups fu WHERE(fu.account_ref,fu.intent_id)=(x.account_ref,x.id)FOR UPDATE NOWAIT;SELECT candidate.*INTO work_intent FROM intents candidate WHERE(candidate.account_ref,candidate.id)=(x.account_ref,x.id)FOR UPDATE NOWAIT;trusted_at:=clock_timestamp();IF work_intent.state IN('provider_call_started','leased')AND work_intent.lease_until<=trusted_at AND EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(work_intent.account_ref,work_intent.id))THEN IF f.id IS NOT NULL THEN PERFORM transition_followup_parent_first(f.account_ref,f.id,'reconciliation_required','provider_call_outcome_unknown',jsonb_build_object('correlationId',f.correlation_id));END IF;UPDATE intents target SET state='reconciliation_required',reason='provider_call_outcome_unknown',lease=NULL,lease_until=NULL WHERE(target.account_ref,target.id)=(work_intent.account_ref,work_intent.id);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(work_intent.account_ref,work_intent.id,work_intent.state,'reconciliation_required','provider_call_outcome_unknown');INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason)VALUES(work_intent.account_ref,work_intent.id,'reconciliation-required','reconciliation_required','provider_call_outcome_unknown')ON CONFLICT DO NOTHING;reconciled:=reconciled+1;END IF;EXCEPTION WHEN lock_not_available THEN busy_kind:=CASE WHEN lock_stage='authority'THEN'authority_busy'ELSE'row_busy'END;END;IF busy_kind IS NOT NULL THEN BEGIN INSERT INTO reconciliation_busy_events(account_ref,intent_id,busy_kind,details)VALUES(x.account_ref,x.id,busy_kind,jsonb_build_object('observedAt',clock_timestamp()))ON CONFLICT DO NOTHING;EXCEPTION WHEN lock_not_available THEN NULL;END;END IF;
 END LOOP;
 IF reconcile_scanned OR reconcile_dirty THEN BEGIN UPDATE scheduler_cursors SET last_sort_at=reconcile_at,last_account_ref=reconcile_account,last_work_id=reconcile_id,last_workflow_id='',cycle_start_sort_at=reconcile_start_at,cycle_start_account_ref=reconcile_start_account,cycle_start_work_id=reconcile_start_id,cycle_start_workflow_id='',cycle_high_sort_at=COALESCE(reconcile_high_at,'-infinity'),cycle_high_account_ref=COALESCE(reconcile_high_account,''),cycle_high_work_id=COALESCE(reconcile_high_id,'00000000-0000-0000-0000-000000000000'),cycle_high_workflow_id='',cycle_phase=reconcile_phase,updated_at=clock_timestamp()WHERE name='followup-reconciliation'AND updated_at=reconcile_stamp;EXCEPTION WHEN lock_not_available THEN NULL;END;END IF;
 INSERT INTO scheduler_cursors(name)VALUES('all-account-work')ON CONFLICT(name)DO NOTHING;SELECT*INTO cursor_row FROM scheduler_cursors WHERE name='all-account-work';cursor_account:=cursor_row.last_account_ref;cursor_work:=cursor_row.last_work_id;cursor_workflow:=cursor_row.last_workflow_id;start_account:=cursor_row.cycle_start_account_ref;start_work:=cursor_row.cycle_start_work_id;start_workflow:=cursor_row.cycle_start_workflow_id;high_account:=cursor_row.cycle_high_account_ref;high_work:=cursor_row.cycle_high_work_id;high_workflow:=cursor_row.cycle_high_workflow_id;projection_phase:=cursor_row.cycle_phase;projection_stamp:=cursor_row.updated_at;trusted_at:=clock_timestamp();IF high_account=''THEN start_account:=cursor_account;start_work:=cursor_work;start_workflow:=cursor_workflow;projection_phase:=0;WITH eligible AS(SELECT i.account_ref,i.id work_id,'salesflow-wf-03'::text workflow_id FROM intents i JOIN accounts ac ON ac.id=i.account_ref AND ac.enabled WHERE(i.state='pending'OR(i.state='leased'AND i.lease_until<=trusted_at AND NOT EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(i.account_ref,i.id))))AND(i.next_attempt IS NULL OR i.next_attempt<=trusted_at)AND(i.kind<>'followup'OR EXISTS(SELECT 1 FROM followups parent WHERE(parent.account_ref,parent.intent_id)=(i.account_ref,i.id)AND parent.state='intent_created'))UNION ALL SELECT tr.account_ref,tr.conversation_id,'salesflow-wf-02'FROM turns tr JOIN accounts ta ON ta.id=tr.account_ref AND ta.enabled WHERE(tr.state='pending'OR(tr.state='claimed'AND tr.claim_until<=trusted_at))GROUP BY tr.account_ref,tr.conversation_id UNION ALL SELECT h.account_ref,h.id,'salesflow-wf-06'FROM handoffs h JOIN accounts ac ON ac.id=h.account_ref AND ac.enabled WHERE(h.state='pending'OR(h.state='claimed'AND h.claim_until<=trusted_at))AND(h.next_attempt IS NULL OR h.next_attempt<=trusted_at))SELECT q.account_ref,q.work_id,q.workflow_id INTO high_account,high_work,high_workflow FROM eligible q ORDER BY q.account_ref DESC,q.work_id DESC,q.workflow_id DESC LIMIT 1;projection_dirty:=FOUND;END IF;
 LOOP
  EXIT WHEN high_account IS NULL OR projected>=50 OR clock_timestamp()>=deadline;
  IF projection_phase=0 THEN
   WITH eligible AS(SELECT i.account_ref,i.id work_id,'salesflow-wf-03'::text workflow_id FROM intents i JOIN accounts ac ON ac.id=i.account_ref AND ac.enabled WHERE(i.state='pending'OR(i.state='leased'AND i.lease_until<=trusted_at AND NOT EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(i.account_ref,i.id))))AND(i.next_attempt IS NULL OR i.next_attempt<=trusted_at)AND(i.kind<>'followup'OR EXISTS(SELECT 1 FROM followups parent WHERE(parent.account_ref,parent.intent_id)=(i.account_ref,i.id)AND parent.state='intent_created'))UNION ALL SELECT tr.account_ref,tr.conversation_id,'salesflow-wf-02'FROM turns tr JOIN accounts ta ON ta.id=tr.account_ref AND ta.enabled WHERE(tr.state='pending'OR(tr.state='claimed'AND tr.claim_until<=trusted_at))GROUP BY tr.account_ref,tr.conversation_id UNION ALL SELECT h.account_ref,h.id,'salesflow-wf-06'FROM handoffs h JOIN accounts ac ON ac.id=h.account_ref AND ac.enabled WHERE(h.state='pending'OR(h.state='claimed'AND h.claim_until<=trusted_at))AND(h.next_attempt IS NULL OR h.next_attempt<=trusted_at))SELECT q.account_ref,q.work_id,q.workflow_id INTO x FROM eligible q WHERE(q.account_ref,q.work_id,q.workflow_id)>(cursor_account,cursor_work,cursor_workflow)AND(q.account_ref,q.work_id,q.workflow_id)<=(high_account,high_work,high_workflow)ORDER BY q.account_ref,q.work_id,q.workflow_id LIMIT 1;
   IF NOT FOUND THEN projection_phase:=1;cursor_account:='';cursor_work:='00000000-0000-0000-0000-000000000000';cursor_workflow:='';projection_dirty:=true;CONTINUE;END IF;
  ELSE
   WITH eligible AS(SELECT i.account_ref,i.id work_id,'salesflow-wf-03'::text workflow_id FROM intents i JOIN accounts ac ON ac.id=i.account_ref AND ac.enabled WHERE(i.state='pending'OR(i.state='leased'AND i.lease_until<=trusted_at AND NOT EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(i.account_ref,i.id))))AND(i.next_attempt IS NULL OR i.next_attempt<=trusted_at)AND(i.kind<>'followup'OR EXISTS(SELECT 1 FROM followups parent WHERE(parent.account_ref,parent.intent_id)=(i.account_ref,i.id)AND parent.state='intent_created'))UNION ALL SELECT tr.account_ref,tr.conversation_id,'salesflow-wf-02'FROM turns tr JOIN accounts ta ON ta.id=tr.account_ref AND ta.enabled WHERE(tr.state='pending'OR(tr.state='claimed'AND tr.claim_until<=trusted_at))GROUP BY tr.account_ref,tr.conversation_id UNION ALL SELECT h.account_ref,h.id,'salesflow-wf-06'FROM handoffs h JOIN accounts ac ON ac.id=h.account_ref AND ac.enabled WHERE(h.state='pending'OR(h.state='claimed'AND h.claim_until<=trusted_at))AND(h.next_attempt IS NULL OR h.next_attempt<=trusted_at))SELECT q.account_ref,q.work_id,q.workflow_id INTO x FROM eligible q WHERE(q.account_ref,q.work_id,q.workflow_id)>(cursor_account,cursor_work,cursor_workflow)AND(q.account_ref,q.work_id,q.workflow_id)<=(start_account,start_work,start_workflow)ORDER BY q.account_ref,q.work_id,q.workflow_id LIMIT 1;
   IF NOT FOUND THEN high_account:='';high_work:='00000000-0000-0000-0000-000000000000';high_workflow:='';start_account:='';start_work:='00000000-0000-0000-0000-000000000000';start_workflow:='';projection_phase:=0;projection_dirty:=true;EXIT;END IF;
  END IF;
  cursor_account:=x.account_ref;cursor_work:=x.work_id;cursor_workflow:=x.workflow_id;projected:=projected+1;account_ref:=x.account_ref;work_id:=x.work_id;workflow_id:=x.workflow_id;RETURN NEXT;
 END LOOP;
 IF projected>0 OR projection_dirty THEN BEGIN UPDATE scheduler_cursors SET last_sort_at='-infinity',last_account_ref=cursor_account,last_work_id=cursor_work,last_workflow_id=cursor_workflow,cycle_start_account_ref=start_account,cycle_start_work_id=start_work,cycle_start_workflow_id=start_workflow,cycle_high_account_ref=COALESCE(high_account,''),cycle_high_work_id=COALESCE(high_work,'00000000-0000-0000-0000-000000000000'),cycle_high_workflow_id=COALESCE(high_workflow,''),cycle_phase=projection_phase,updated_at=clock_timestamp()WHERE name='all-account-work'AND updated_at=projection_stamp;EXCEPTION WHEN lock_not_available THEN NULL;END;END IF;
END$$;

CREATE OR REPLACE FUNCTION followup_metrics(acct text)RETURNS jsonb LANGUAGE sql STABLE AS $$SELECT jsonb_build_object('followupBacklog',count(*)FILTER(WHERE state IN('due','claimed','retry','intent_created','call_started','reconciliation_required')),'oldestFollowupDueAgeSeconds',COALESCE(GREATEST(0,extract(epoch FROM clock_timestamp()-min(due_at)FILTER(WHERE state IN('due','claimed','retry','intent_created','call_started','reconciliation_required')AND due_at<=clock_timestamp()))),0),'followupRetry',count(*)FILTER(WHERE state='retry'),'followupExhausted',count(*)FILTER(WHERE state='exhausted'))FROM followups f WHERE f.account_ref=acct$$;

DROP FUNCTION IF EXISTS claim_dispatch(text,text,uuid,timestamptz);
CREATE OR REPLACE FUNCTION terminalize_orphan_followup(acct text,work uuid,why text DEFAULT'followup_parent_missing')RETURNS text LANGUAGE plpgsql AS $$DECLARE i intents;old text;has_call bool;BEGIN SELECT*INTO i FROM intents WHERE(account_ref,id)=(acct,work)FOR UPDATE;IF NOT FOUND THEN RETURN'not_found';END IF;SELECT EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(acct,work))INTO has_call;IF i.state IN('sent','failed')THEN RETURN i.state;ELSIF has_call THEN IF i.state<>'reconciliation_required'THEN old:=i.state;INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason,at)VALUES(acct,work,old,'reconciliation_required',why,clock_timestamp());UPDATE intents SET state='reconciliation_required',reason=why,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work);END IF;INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason,details)VALUES(acct,work,'orphan-'||why,'reconciliation_required',why,jsonb_build_object('providerCallExists',true))ON CONFLICT DO NOTHING;RETURN'reconciliation_required';ELSIF i.state IN('pending','leased','provider_call_started','reconciliation_required')THEN old:=i.state;UPDATE intents SET state='suppressed',reason=why,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason,at)VALUES(acct,work,old,'suppressed',why,clock_timestamp());END IF;RETURN'denied';END$$;
CREATE FUNCTION claim_dispatch(t text,acct text,work uuid,n timestamptz DEFAULT now())RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;i intents;f followups;r text;cfg jsonb;old text;conv_id uuid;contact_ref_id uuid;trusted_at timestamptz:=clock_timestamp();lock_deadline timestamptz;BEGIN
 SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR a.role NOT IN('runtime','scheduler')OR(a.role='runtime'AND acct IS NOT NULL AND a.account_ref<>acct)THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;IF acct IS NULL THEN acct:=a.account_ref;END IF;IF acct IS NULL THEN RETURN'{"ok":false,"terminal":"denied","reason":"missing_account"}';END IF;
 SELECT x.conversation_id,x.contact_id INTO conv_id,contact_ref_id FROM intents x WHERE(x.account_ref,x.id)=(acct,work);IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;PERFORM set_config('lock_timeout','1s',true);lock_deadline:=clock_timestamp()+interval'1s';BEGIN PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(acct,conv_id);PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(acct,contact_ref_id);SELECT*INTO f FROM followups WHERE(account_ref,intent_id)=(acct,work)FOR UPDATE;SELECT*INTO i FROM intents WHERE(account_ref,id)=(acct,work)FOR UPDATE;EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"terminal":"denied","reason":"busy"}';END;
 trusted_at:=clock_timestamp();IF i.kind='followup'AND f.id IS NULL THEN r:=terminalize_orphan_followup(acct,work);RETURN jsonb_build_object('ok',false,'terminal',r,'reason','followup_parent_missing');END IF;
 IF i.state='sent'THEN RETURN jsonb_build_object('ok',false,'terminal','sent','reason','already_sent','account_ref',acct,'work_id',i.id,'provider_id',i.provider_id);ELSIF i.state='failed'THEN RETURN jsonb_build_object('ok',false,'terminal','failed','reason','failed','account_ref',acct,'work_id',i.id,'provider_id',i.provider_id);ELSIF i.state='reconciliation_required'THEN RETURN jsonb_build_object('ok',false,'terminal','reconciliation_required','reason','reconciliation_required','account_ref',acct,'work_id',i.id,'provider_id',i.provider_id);ELSIF i.state='provider_call_started'AND i.lease_until>trusted_at THEN RETURN jsonb_build_object('ok',false,'terminal','already_started','reason','call_in_flight','account_ref',acct,'work_id',i.id,'provider_id',i.provider_id);ELSIF(i.state='provider_call_started'AND i.lease_until<=trusted_at)OR(i.state='leased'AND i.lease_until<=trusted_at AND EXISTS(SELECT 1 FROM provider_calls pc WHERE(pc.account_ref,pc.intent_id)=(acct,i.id)))THEN old:=i.state;IF i.kind='followup'THEN PERFORM transition_followup_parent_first(acct,f.id,'reconciliation_required','provider_call_outcome_unknown','{}');END IF;UPDATE intents SET state='reconciliation_required',reason='provider_call_outcome_unknown',lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,i.id);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,i.id,old,'reconciliation_required','provider_call_outcome_unknown');INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason)VALUES(acct,i.id,'reconciliation-required','reconciliation_required','provider_call_outcome_unknown')ON CONFLICT DO NOTHING;RETURN jsonb_build_object('ok',false,'terminal','reconciliation_required','reason','reconciliation_required','account_ref',acct,'work_id',i.id,'provider_id',i.provider_id);ELSIF i.state='leased'AND i.lease_until>trusted_at THEN RETURN'{"ok":false,"terminal":"denied","reason":"already_leased"}';ELSIF i.state NOT IN('pending','leased')THEN RETURN jsonb_build_object('ok',false,'terminal','denied','reason','not_pending','state',i.state);END IF;
 SELECT body INTO cfg FROM config_docs WHERE account_ref=acct AND kind='retry'AND active;IF cfg IS NULL THEN r:='missing_retry';ELSIF i.attempts>=(cfg->>'maxAttempts')::int THEN r:='retry_exhausted';ELSIF i.next_attempt>trusted_at THEN RETURN'{"ok":false,"terminal":"denied","reason":"backoff"}';ELSIF i.kind='followup'THEN r:=followup_final_authorization_reason(acct,work,trusted_at);ELSE r:=authorization_reason(acct,i,trusted_at);END IF;
 IF r<>'authorized'THEN IF i.kind='followup'THEN PERFORM transition_followup_parent_first(acct,f.id,CASE WHEN r='retry_exhausted'THEN'exhausted'ELSE'denied'END,r,jsonb_build_object('phase','claim'));END IF;old:=i.state;UPDATE intents SET state=CASE WHEN r='retry_exhausted'AND i.kind<>'followup'THEN'reconciliation_required'ELSE'suppressed'END,reason=r,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,i.id);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,i.id,old,CASE WHEN r='retry_exhausted'AND i.kind<>'followup'THEN'reconciliation_required'ELSE'suppressed'END,r);INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'authorization_denied',r,a.actor,jsonb_build_object('intent_id',i.id,'phase','claim'));RETURN jsonb_build_object('ok',false,'terminal',CASE WHEN r='retry_exhausted'AND i.kind<>'followup'THEN'reconciliation_required'ELSE'denied'END,'reason',r);END IF;
 old:=i.state;UPDATE intents SET state='leased',reason=NULL,lease=gen_random_uuid(),lease_until=trusted_at+make_interval(secs=>(cfg->>'leaseSeconds')::int),attempts=attempts+1,next_attempt=NULL WHERE(account_ref,id)=(acct,i.id)RETURNING*INTO i;INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,i.id,old,'leased','authorized');RETURN jsonb_build_object('ok',true,'terminal','claimed','account_ref',acct,'work_id',i.id,'lease',i.lease);
END$$;

DROP FUNCTION IF EXISTS begin_provider_call(text,text,uuid,uuid);
CREATE FUNCTION begin_provider_call(t text,acct text,work uuid,l uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;i intents;f followups;pc provider_calls;r text;pid text;release_id text;conv_id uuid;contact_ref_id uuid;corr uuid;trusted_at timestamptz:=clock_timestamp();lock_deadline timestamptz;BEGIN
 SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR(a.role='runtime'AND a.account_ref<>acct)OR a.role NOT IN('runtime','scheduler')THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;SELECT x.conversation_id,x.contact_id INTO conv_id,contact_ref_id FROM intents x WHERE(x.account_ref,x.id)=(acct,work);IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;PERFORM set_config('lock_timeout','1s',true);lock_deadline:=clock_timestamp()+interval'1s';BEGIN PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(acct,conv_id);PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(acct,contact_ref_id);SELECT*INTO f FROM followups WHERE(account_ref,intent_id)=(acct,work)FOR UPDATE;SELECT*INTO i FROM intents WHERE(account_ref,id)=(acct,work)FOR UPDATE;EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"terminal":"denied","reason":"busy"}';END;trusted_at:=clock_timestamp();IF i.kind='followup'AND f.id IS NULL THEN r:=terminalize_orphan_followup(acct,work);RETURN jsonb_build_object('ok',false,'terminal',r,'reason','followup_parent_missing');END IF;SELECT*INTO pc FROM provider_calls WHERE(account_ref,intent_id)=(acct,work);IF FOUND THEN RETURN jsonb_build_object('ok',true,'terminal','already_started','provider_id',pc.provider_id,'correlation_id',pc.correlation_id);END IF;IF i.state<>'leased'OR i.lease IS DISTINCT FROM l OR i.lease_until<=trusted_at THEN RETURN'{"ok":false,"terminal":"denied","reason":"lease_mismatch"}';END IF;r:=CASE WHEN i.kind='followup'THEN followup_final_authorization_reason(acct,work,trusted_at)ELSE authorization_reason(acct,i,trusted_at)END;
 IF r<>'authorized'THEN IF i.kind='followup'THEN PERFORM transition_followup_parent_first(acct,f.id,CASE WHEN r='retry_exhausted'THEN'exhausted'ELSE'denied'END,r,jsonb_build_object('phase','provider_call_start'));END IF;UPDATE intents SET state='suppressed',reason=r,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,work,'leased','suppressed',r);INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'authorization_denied',r,a.actor,jsonb_build_object('intent_id',work,'phase','provider_call_start'));RETURN jsonb_build_object('ok',false,'terminal','denied','reason',r);END IF;
 pid:='synthetic-'||work::text;release_id:=COALESCE(i.provenance#>>'{context,releaseSetVersion}','unbound');corr:=COALESCE(f.correlation_id,gen_random_uuid());IF i.kind='followup'THEN PERFORM transition_followup_parent_first(acct,f.id,'call_started','provider_call_started',jsonb_build_object('correlationId',corr));END IF;INSERT INTO provider_calls(account_ref,intent_id,attempt_no,lease,provider_id,correlation_id,release_set_version,callback_alias,started_at)VALUES(acct,work,i.attempts,l,pid,corr,release_id,encode(digest(acct||':'||pid,'sha256'),'hex'),clock_timestamp())RETURNING*INTO pc;UPDATE intents SET state='provider_call_started',provider_id=pid,reason=NULL WHERE(account_ref,id)=(acct,work);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,work,'leased','provider_call_started','provider_call_started');INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason,details)VALUES(acct,work,'started','started','authorized',jsonb_build_object('attempt',i.attempts,'correlation_id',pc.correlation_id,'release_set_version',release_id));RETURN jsonb_build_object('ok',true,'terminal','started','account_ref',acct,'work_id',work,'lease',l,'provider_id',pid,'correlation_id',pc.correlation_id);
END$$;

DROP FUNCTION IF EXISTS finish_dispatch(text,text,uuid,uuid,text);
CREATE FUNCTION finish_dispatch(t text,acct text,work uuid,l uuid,outcome text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;i intents;f followups;pc provider_calls;cfg jsonb;old text;event_id text;event_status text;event_time timestamptz;conv_id uuid;contact_ref_id uuid;lock_deadline timestamptz;transition_state text;transition_reason text;BEGIN
 SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR(a.role='runtime'AND a.account_ref<>acct)OR a.role NOT IN('runtime','scheduler')THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;IF l IS NULL THEN RETURN'{"ok":false,"terminal":"denied","reason":"call_mismatch"}';END IF;IF outcome IS NULL OR outcome NOT IN('success','retryable','ambiguous','failed')THEN RETURN'{"ok":false,"terminal":"denied","reason":"invalid_outcome"}';END IF;SELECT conversation_id,contact_id INTO conv_id,contact_ref_id FROM intents WHERE(account_ref,id)=(acct,work);IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;PERFORM set_config('lock_timeout','1s',true);lock_deadline:=clock_timestamp()+interval'1s';BEGIN PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(acct,conv_id);PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(acct,contact_ref_id);SELECT*INTO f FROM followups WHERE(account_ref,intent_id)=(acct,work)FOR UPDATE;SELECT*INTO i FROM intents WHERE(account_ref,id)=(acct,work)FOR UPDATE;SELECT*INTO pc FROM provider_calls WHERE(account_ref,intent_id)=(acct,work);EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"terminal":"denied","reason":"busy"}';END;event_time:=clock_timestamp();IF i.kind='followup'AND f.id IS NULL THEN old:=terminalize_orphan_followup(acct,work);RETURN jsonb_build_object('ok',false,'terminal',old,'reason','followup_parent_missing');END IF;
 IF outcome='retryable'THEN IF FOUND OR i.state<>'leased'OR i.lease IS DISTINCT FROM l OR i.lease_until IS NULL OR i.lease_until<=event_time THEN RETURN'{"ok":false,"terminal":"denied","reason":"call_already_started"}';END IF;SELECT body INTO cfg FROM config_docs WHERE account_ref=acct AND kind='retry'AND active;old:=i.state;IF cfg IS NOT NULL AND i.attempts<(cfg->>'maxAttempts')::int THEN IF i.kind='followup'THEN UPDATE followups SET next_attempt=event_time+make_interval(secs=>(cfg->>'backoffSeconds')::int)WHERE(account_ref,id)=(acct,f.id);PERFORM transition_followup_parent_first(acct,f.id,'retry','pre_call_retryable',jsonb_build_object('nextAttempt',event_time+make_interval(secs=>(cfg->>'backoffSeconds')::int)));END IF;UPDATE intents SET state='pending',reason='pre_call_retryable',next_attempt=event_time+make_interval(secs=>(cfg->>'backoffSeconds')::int),lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work)RETURNING*INTO i;INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,work,old,'pending','pre_call_retryable');RETURN jsonb_build_object('ok',true,'terminal','pending','next_attempt',i.next_attempt);END IF;IF i.kind='followup'THEN PERFORM transition_followup_parent_first(acct,f.id,'exhausted','retry_exhausted','{}');UPDATE intents SET state='suppressed',reason='retry_exhausted',lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,work,old,'suppressed','retry_exhausted');RETURN'{"ok":true,"terminal":"suppressed","reason":"retry_exhausted"}'::jsonb;END IF;UPDATE intents SET state='reconciliation_required',reason='retry_exhausted',lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,work,old,'reconciliation_required','retry_exhausted');RETURN'{"ok":true,"terminal":"reconciliation_required","reason":"retry_exhausted"}'::jsonb;END IF;
 IF NOT FOUND OR pc.lease IS DISTINCT FROM l THEN RETURN'{"ok":false,"terminal":"denied","reason":"call_mismatch"}';END IF;IF i.state='sent'THEN RETURN jsonb_build_object('ok',true,'terminal','sent','provider_id',pc.provider_id);ELSIF i.state='failed'THEN RETURN jsonb_build_object('ok',true,'terminal','failed','provider_id',pc.provider_id);ELSIF i.state NOT IN('provider_call_started','reconciliation_required')THEN RETURN jsonb_build_object('ok',false,'terminal','denied','reason','invalid_state','state',i.state);END IF;IF i.state='reconciliation_required'AND outcome='ambiguous'THEN RETURN jsonb_build_object('ok',true,'terminal','reconciliation_required','provider_id',pc.provider_id);END IF;old:=i.state;
 transition_state:=CASE outcome WHEN'success'THEN'sent'WHEN'failed'THEN'failed'ELSE'reconciliation_required'END;transition_reason:=CASE outcome WHEN'success'THEN'provider_accepted'WHEN'failed'THEN'provider_call_failed'ELSE'ambiguous'END;IF outcome='success'THEN IF i.kind='followup'AND f.id IS NOT NULL THEN PERFORM transition_followup_parent_first(acct,f.id,'sent','provider_accepted',jsonb_build_object('correlationId',f.correlation_id));END IF;event_time:=clock_timestamp();INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason,at)VALUES(acct,work,old,transition_state,transition_reason,event_time);UPDATE intents SET state='sent',reason=NULL,provider_id=pc.provider_id,provider_status='accepted',provider_time=event_time,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work)RETURNING*INTO i;event_id:='dispatch-accepted-'||work::text;event_status:='accepted';INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason)VALUES(acct,work,'outcome-success','accepted','provider_accepted')ON CONFLICT DO NOTHING;ELSIF outcome='failed'THEN IF i.kind='followup'AND f.id IS NOT NULL THEN PERFORM transition_followup_parent_first(acct,f.id,'failed','provider_call_failed',jsonb_build_object('correlationId',f.correlation_id));END IF;event_time:=clock_timestamp();INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason,at)VALUES(acct,work,old,transition_state,transition_reason,event_time);UPDATE intents SET state='failed',reason='provider_call_failed',provider_id=pc.provider_id,provider_status='failed',provider_time=event_time,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work)RETURNING*INTO i;event_id:='dispatch-failed-'||work::text;event_status:='failed';INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason)VALUES(acct,work,'outcome-failed','failed','provider_call_failed')ON CONFLICT DO NOTHING;ELSE IF i.kind='followup'AND f.id IS NOT NULL THEN PERFORM transition_followup_parent_first(acct,f.id,'reconciliation_required','ambiguous',jsonb_build_object('correlationId',f.correlation_id));END IF;event_time:=clock_timestamp();INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason,at)VALUES(acct,work,old,transition_state,transition_reason,event_time);UPDATE intents SET state='reconciliation_required',reason='ambiguous',provider_id=pc.provider_id,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work)RETURNING*INTO i;INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason)VALUES(acct,work,'outcome-ambiguous','ambiguous','ambiguous')ON CONFLICT DO NOTHING;END IF;
 IF event_id IS NOT NULL THEN INSERT INTO provider_events(account_ref,event_id,intent_id,provider_id,status,provider_time,payload_hash)VALUES(acct,event_id,work,pc.provider_id,event_status,event_time,encode(digest(jsonb_build_object('event_id',event_id,'provider_id',pc.provider_id,'status',event_status,'provider_time',event_time)::text,'sha256'),'hex'))ON CONFLICT ON CONSTRAINT provider_events_pkey DO NOTHING;END IF;RETURN jsonb_build_object('ok',true,'terminal',i.state,'provider_id',pc.provider_id);
END$$;

DROP TRIGGER IF EXISTS provider_events_immutable ON provider_events;
DROP TRIGGER IF EXISTS provider_immutable ON provider_events;
DROP FUNCTION IF EXISTS provider_immutable_guard();
CREATE FUNCTION provider_immutable_guard()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF TG_OP='UPDATE'AND current_setting('salesflow.deletion_mode',true)='on'AND NEW.account_ref=OLD.account_ref AND NEW.event_id=OLD.event_id AND NEW.intent_id=OLD.intent_id AND NEW.status=OLD.status AND NEW.provider_time=OLD.provider_time AND NEW.payload_hash=OLD.payload_hash AND NEW.provider_id='deleted-'||OLD.intent_id::text THEN RETURN NEW;END IF;RAISE EXCEPTION'append-only';END$$;
CREATE TRIGGER provider_immutable BEFORE UPDATE OR DELETE ON provider_events FOR EACH ROW EXECUTE FUNCTION provider_immutable_guard();

DROP FUNCTION IF EXISTS callback(text,jsonb);
CREATE FUNCTION callback(t text,p jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;i intents;f followups;pc provider_calls;e provider_events;pt timestamptz;h text;alias text;stored_provider text;rank_old int;rank_new int;deleted_lifecycle bool;parent_target text;sent_transition_at timestamptz;lock_deadline timestamptz;BEGIN
 SELECT*INTO a FROM actor_for(t,'runtime');IF NOT FOUND OR p->>'account_ref'IS DISTINCT FROM a.account_ref THEN RETURN'{"ok":false,"reason":"wrong_account"}';END IF;IF COALESCE(p->>'event_id','')=''OR COALESCE(p->>'provider_id','')=''OR COALESCE(p->>'provider_time','')=''OR COALESCE(p->>'status','')NOT IN('accepted','sent','delivered','read','failed')THEN RETURN'{"ok":false,"reason":"invalid"}';END IF;BEGIN pt:=(p->>'provider_time')::timestamptz;EXCEPTION WHEN OTHERS THEN RETURN'{"ok":false,"reason":"invalid"}';END;IF pt IS NULL THEN RETURN'{"ok":false,"reason":"invalid"}';ELSIF pt>clock_timestamp()+interval'5 min'THEN RETURN'{"ok":false,"reason":"future"}';END IF;
 alias:=encode(digest(a.account_ref||':'||(p->>'provider_id'),'sha256'),'hex');SELECT call.*INTO pc FROM provider_calls call WHERE call.account_ref=a.account_ref AND call.callback_alias=alias;IF NOT FOUND THEN RETURN'{"ok":false,"reason":"provider_mismatch"}';END IF;SELECT*INTO i FROM intents WHERE(account_ref,id)=(pc.account_ref,pc.intent_id);IF NOT FOUND THEN RETURN'{"ok":false,"reason":"provider_mismatch"}';END IF;PERFORM set_config('lock_timeout','1s',true);lock_deadline:=clock_timestamp()+interval'1s';BEGIN PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(a.account_ref,i.conversation_id);PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(a.account_ref,i.contact_id);PERFORM followup_set_lock_deadline(lock_deadline);PERFORM pg_advisory_xact_lock(hashtextextended(a.account_ref||':callback:'||(p->>'event_id'),0));SELECT*INTO f FROM followups WHERE(account_ref,intent_id)=(a.account_ref,i.id)FOR UPDATE;SELECT*INTO i FROM intents WHERE(account_ref,id)=(a.account_ref,i.id)FOR UPDATE;EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"reason":"busy"}';END;SELECT lifecycle='deleted'INTO deleted_lifecycle FROM conversations WHERE(account_ref,id)=(a.account_ref,i.conversation_id);h:=encode(digest(p::text,'sha256'),'hex');SELECT*INTO e FROM provider_events WHERE(account_ref,event_id)=(a.account_ref,p->>'event_id');IF FOUND THEN RETURN CASE WHEN e.payload_hash=h THEN jsonb_build_object('ok',true,'created',false,'status',i.provider_status)ELSE'{"ok":false,"reason":"idempotency_conflict"}'::jsonb END;END IF;
 stored_provider:=CASE WHEN deleted_lifecycle THEN'deleted-'||i.id::text ELSE pc.provider_id END;INSERT INTO provider_events(account_ref,event_id,intent_id,provider_id,status,provider_time,payload_hash)VALUES(a.account_ref,p->>'event_id',i.id,stored_provider,p->>'status',pt,h);IF i.kind='followup'AND f.id IS NULL AND i.state IN('sent','failed')THEN RETURN jsonb_build_object('ok',true,'created',true,'terminal',i.state,'status',i.provider_status);END IF;rank_old:=array_position(ARRAY['accepted','sent','delivered','read'],i.provider_status);rank_new:=array_position(ARRAY['accepted','sent','delivered','read'],p->>'status');IF i.state<>'failed'AND((p->>'status'='failed'AND COALESCE(rank_old,0)<3 AND(i.provider_time IS NULL OR pt>=i.provider_time))OR(p->>'status'<>'failed'AND(i.provider_time IS NULL OR(pt>=i.provider_time AND rank_new>=COALESCE(rank_old,0)))))THEN parent_target:=CASE WHEN p->>'status'='failed'THEN'failed'WHEN p->>'status'IN('delivered','read')THEN'delivered'ELSE'sent'END;IF f.id IS NOT NULL THEN PERFORM transition_followup_parent_first(a.account_ref,f.id,parent_target,'provider_callback_reconciled',jsonb_build_object('eventIdHash',encode(digest(p->>'event_id','sha256'),'hex'),'status',p->>'status','correlationId',f.correlation_id));END IF;IF i.state IN('leased','reconciliation_required','provider_call_started')THEN sent_transition_at:=clock_timestamp();INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason,at)VALUES(a.account_ref,i.id,i.state,CASE WHEN p->>'status'='failed'THEN'failed'ELSE'sent'END,'provider_callback_reconciled',sent_transition_at);INSERT INTO provider_call_events(account_ref,intent_id,event_key,event_type,reason,details)VALUES(a.account_ref,i.id,'reconciled-'||encode(digest(p->>'event_id','sha256'),'hex'),'reconciled','provider_callback_reconciled',jsonb_build_object('event_id_hash',encode(digest(p->>'event_id','sha256'),'hex'),'status',p->>'status','correlation_id',pc.correlation_id))ON CONFLICT DO NOTHING;END IF;UPDATE intents SET state=CASE WHEN p->>'status'='failed'THEN'failed'ELSE'sent'END,reason=CASE WHEN p->>'status'='failed'THEN'provider_failed'ELSE NULL END,provider_status=p->>'status',provider_time=pt,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(a.account_ref,i.id)RETURNING*INTO i;END IF;RETURN jsonb_build_object('ok',true,'created',true,'status',i.provider_status);
END$$;

CREATE OR REPLACE FUNCTION cancel_followups_after_inbound()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE cfg jsonb;norm text;why text:='customer_replied';BEGIN IF current_setting('salesflow.staging_ingest',true)='on'THEN RETURN NEW;END IF;SELECT body INTO cfg FROM config_docs WHERE account_ref=NEW.account_ref AND kind='consent_templates'AND active;norm:=lower(btrim(regexp_replace(NEW.processing_body,'[[:space:]]+',' ','g')));IF cfg IS NOT NULL AND cfg->'optOutSignals'?norm THEN why:='opted_out';ELSIF cfg IS NOT NULL AND cfg->'humanSignals'?norm THEN why:='human_owned';END IF;PERFORM cancel_followups_for_conversation(NEW.account_ref,NEW.conversation_id,why,NULL);RETURN NEW;END$$;
DROP TRIGGER IF EXISTS cancel_followups_after_inbound ON inbound_messages;
CREATE TRIGGER cancel_followups_after_inbound AFTER INSERT ON inbound_messages FOR EACH ROW EXECUTE FUNCTION cancel_followups_after_inbound();

DROP FUNCTION IF EXISTS set_consent(text,text,uuid,text,text);
CREATE FUNCTION set_consent(t text,acct text,c uuid,s text,e text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;prior timestamptz;at_time timestamptz;conv uuid;lock_deadline timestamptz;BEGIN SELECT*INTO a FROM actor_for(t,'runtime');IF NOT FOUND OR a.account_ref<>acct THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;IF s NOT IN('granted','revoked')OR COALESCE(trim(e),'')=''OR NOT EXISTS(SELECT 1 FROM contacts WHERE(account_ref,id)=(acct,c))THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;PERFORM set_config('lock_timeout','5s',true);lock_deadline:=clock_timestamp()+interval'5s';BEGIN FOR conv IN SELECT id FROM conversations WHERE(account_ref,contact_id)=(acct,c)ORDER BY id LOOP PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(acct,conv);END LOOP;PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(acct,c);EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"reason":"busy"}';END;at_time:=clock_timestamp();SELECT max(occurred_at)INTO prior FROM consent_events WHERE(account_ref,contact_id)=(acct,c);at_time:=GREATEST(at_time,COALESCE(prior+interval'1 microsecond',at_time));INSERT INTO consent_events VALUES(acct,c,s,e,at_time);IF s='revoked'THEN FOR conv IN SELECT id FROM conversations WHERE(account_ref,contact_id)=(acct,c)ORDER BY id LOOP PERFORM cancel_followups_for_conversation(acct,conv,'consent_revoked',NULL);END LOOP;END IF;RETURN jsonb_build_object('ok',true,'occurred_at',at_time);END$$;

DROP FUNCTION IF EXISTS set_control(text,text,text,jsonb);
CREATE FUNCTION set_control(t text,acct text,k text,v jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;conv uuid;contact_ref_id uuid;lock_deadline timestamptz;BEGIN SELECT*INTO a FROM actor_for(t,'operator');IF NOT FOUND OR a.account_ref IS DISTINCT FROM acct OR k IS DISTINCT FROM'stop'THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;IF jsonb_typeof(v)IS DISTINCT FROM'object'OR NOT COALESCE(v?'enabled',false)OR jsonb_typeof(v->'enabled')IS DISTINCT FROM'boolean'THEN RETURN'{"ok":false,"reason":"invalid_control"}';END IF;PERFORM set_config('lock_timeout','1s',true);lock_deadline:=clock_timestamp()+interval'1s';BEGIN FOR conv IN SELECT id FROM conversations WHERE account_ref=acct ORDER BY id LOOP PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(acct,conv);END LOOP;FOR contact_ref_id IN SELECT id FROM contacts WHERE account_ref=acct ORDER BY id LOOP PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(acct,contact_ref_id);END LOOP;EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"reason":"busy"}';END;INSERT INTO controls VALUES(acct,k,v)ON CONFLICT(account_ref,key)DO UPDATE SET value=EXCLUDED.value;IF(v->>'enabled')::bool THEN FOR conv IN SELECT id FROM conversations WHERE account_ref=acct ORDER BY id LOOP PERFORM cancel_followups_for_conversation(acct,conv,'global_stop',NULL);END LOOP;END IF;INSERT INTO audit_events(account_ref,event,reason,actor)VALUES(acct,'control_changed',k,a.actor);RETURN'{"ok":true}';END$$;

CREATE OR REPLACE FUNCTION set_account_enabled(t text,acct text,enabled_value boolean)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;conv uuid;contact_ref_id uuid;lock_deadline timestamptz;BEGIN SELECT*INTO a FROM actor_for_account_management(t,acct);IF NOT FOUND THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;IF enabled_value IS NULL THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;PERFORM set_config('lock_timeout','1s',true);lock_deadline:=clock_timestamp()+interval'1s';BEGIN FOR conv IN SELECT id FROM conversations WHERE account_ref=acct ORDER BY id LOOP PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(acct,conv);END LOOP;FOR contact_ref_id IN SELECT id FROM contacts WHERE account_ref=acct ORDER BY id LOOP PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(acct,contact_ref_id);END LOOP;EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"reason":"busy"}';END;UPDATE accounts SET enabled=enabled_value WHERE id=acct;IF NOT FOUND THEN RETURN'{"ok":false,"reason":"not_found"}';END IF;IF NOT enabled_value THEN FOR conv IN SELECT id FROM conversations WHERE account_ref=acct ORDER BY id LOOP PERFORM cancel_followups_for_conversation(acct,conv,'account_disabled',NULL);END LOOP;END IF;INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'account_enabled_changed',CASE WHEN enabled_value THEN'enabled'ELSE'disabled'END,a.actor,jsonb_build_object('enabled',enabled_value));RETURN jsonb_build_object('ok',true,'enabled',enabled_value);END$$;

CREATE OR REPLACE FUNCTION set_conversation_state(t text,acct text,conv uuid,lifecycle_value text DEFAULT NULL,owner_value text DEFAULT NULL,campaign_value boolean DEFAULT NULL)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;v conversations;contact uuid;why text;lock_deadline timestamptz;BEGIN SELECT*INTO a FROM actor_for(t,'operator');IF NOT FOUND OR a.account_ref IS DISTINCT FROM acct THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;IF lifecycle_value IS NULL AND owner_value IS NULL AND campaign_value IS NULL OR lifecycle_value='deleted'OR lifecycle_value IS NOT NULL AND lifecycle_value NOT IN('active','opted_out')OR owner_value IS NOT NULL AND owner_value NOT IN('ai','human')THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;SELECT contact_id INTO contact FROM conversations WHERE(account_ref,id)=(acct,conv);IF NOT FOUND THEN RETURN'{"ok":false,"reason":"not_found"}';END IF;PERFORM set_config('lock_timeout','1s',true);lock_deadline:=clock_timestamp()+interval'1s';BEGIN PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(acct,conv);PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(acct,contact);SELECT*INTO v FROM conversations WHERE(account_ref,id)=(acct,conv)FOR UPDATE;IF NOT FOUND THEN RETURN'{"ok":false,"reason":"not_found"}';END IF;IF lifecycle_value='active'AND v.lifecycle IN('opted_out','deleted')THEN RETURN'{"ok":false,"reason":"lifecycle_terminal"}';END IF;EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"reason":"busy"}';END;UPDATE conversations SET lifecycle=COALESCE(lifecycle_value,lifecycle),owner=COALESCE(owner_value,owner),campaign=COALESCE(campaign_value,campaign)WHERE(account_ref,id)=(acct,conv)RETURNING*INTO v;why:=CASE WHEN v.lifecycle<>'active'THEN v.lifecycle WHEN v.owner<>'ai'THEN'human_owned'WHEN NOT v.campaign THEN'campaign_disabled'END;IF v.owner<>'ai'THEN PERFORM suppress_automation_for_human(acct,conv,COALESCE(why,'human_owned'));ELSIF why IS NOT NULL THEN PERFORM cancel_followups_for_conversation(acct,conv,why,NULL);END IF;INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'conversation_state_changed',COALESCE(why,'active'),a.actor,jsonb_build_object('conversationId',conv,'lifecycle',v.lifecycle,'owner',v.owner,'campaign',v.campaign));RETURN jsonb_build_object('ok',true,'lifecycle',v.lifecycle,'owner',v.owner,'campaign',v.campaign);END$$;

DROP FUNCTION IF EXISTS activate_config(text,text,text,text,text);
CREATE FUNCTION activate_config(t text,acct text,k text,v text,expected text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;current_version text;target jsonb;conv uuid;contact_ref_id uuid;lock_deadline timestamptz;BEGIN SELECT*INTO a FROM actor_for(t,'operator');IF NOT FOUND OR a.account_ref IS DISTINCT FROM acct THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;IF COALESCE(btrim(k),'')=''OR COALESCE(btrim(v),'')=''THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;PERFORM set_config('lock_timeout','1s',true);lock_deadline:=clock_timestamp()+interval'1s';
 BEGIN FOR conv IN SELECT DISTINCT conversation_id FROM followups WHERE account_ref=acct AND state IN('due','claimed','retry','intent_created','call_started','reconciliation_required')ORDER BY conversation_id LOOP PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(acct,conv);END LOOP;FOR contact_ref_id IN SELECT DISTINCT contact_id FROM followups WHERE account_ref=acct AND state IN('due','claimed','retry','intent_created','call_started','reconciliation_required')ORDER BY contact_id LOOP PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(acct,contact_ref_id);END LOOP;EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"reason":"busy"}';END;
 BEGIN PERFORM followup_set_lock_deadline(lock_deadline);PERFORM pg_advisory_xact_lock(hashtextextended(acct||':'||k,0));EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"reason":"busy"}';END;SELECT body INTO target FROM config_docs WHERE(account_ref,kind,version)=(acct,k,v);IF NOT FOUND THEN RETURN'{"ok":false,"reason":"not_found"}';END IF;IF validate_config(k,target)IS DISTINCT FROM true THEN RETURN'{"ok":false,"reason":"incompatible_config"}';END IF;IF EXISTS(SELECT 1 FROM config_docs WHERE(account_ref,kind,version,active)=(acct,k,v,true))THEN RETURN jsonb_build_object('ok',true,'activated',false,'version',v);END IF;SELECT version INTO current_version FROM config_docs WHERE account_ref=acct AND kind=k AND active;IF current_version IS DISTINCT FROM expected THEN RETURN jsonb_build_object('ok',false,'reason','stale_active_version','activeVersion',current_version);END IF;PERFORM set_config('salesflow.config_activation','on',true);UPDATE config_docs SET active=false WHERE account_ref=acct AND kind=k AND active;UPDATE config_docs SET active=true WHERE(account_ref,kind,version)=(acct,k,v);PERFORM set_config('salesflow.config_activation','off',true);IF k='sales_policy'AND NOT COALESCE((target->>'campaignEnabled')::bool,false)THEN FOR conv IN SELECT DISTINCT conversation_id FROM followups WHERE account_ref=acct AND state IN('due','claimed','retry','intent_created')ORDER BY conversation_id LOOP PERFORM cancel_followups_for_conversation(acct,conv,'campaign_disabled',NULL);END LOOP;END IF;INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'config_activated',k,a.actor,jsonb_build_object('kind',k,'targetVersion',v,'previousVersion',current_version));RETURN jsonb_build_object('ok',true,'activated',true,'version',v,'previousVersion',current_version);
END$$;

-- Cross-table ownership constraints are added NOT VALID so a brownfield upgrade
-- preserves legacy evidence while every new or changed tuple is enforced.
CREATE UNIQUE INDEX IF NOT EXISTS conversations_account_id_contact_unique ON conversations(account_ref,id,contact_id);
CREATE UNIQUE INDEX IF NOT EXISTS inbound_messages_account_id_conversation_unique ON inbound_messages(account_ref,id,conversation_id);
CREATE UNIQUE INDEX IF NOT EXISTS intents_account_id_contact_conversation_unique ON intents(account_ref,id,contact_id,conversation_id);
DO $$BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='consent_events_evidence_bytes_check'AND conrelid='consent_events'::regclass)THEN ALTER TABLE consent_events ADD CONSTRAINT consent_events_evidence_bytes_check CHECK(octet_length(evidence)<=8192)NOT VALID;END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='config_docs_body_bytes_check'AND conrelid='config_docs'::regclass)THEN ALTER TABLE config_docs ADD CONSTRAINT config_docs_body_bytes_check CHECK(octet_length(body::text)<=262144)NOT VALID;END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='intents_conversation_contact_fk'AND conrelid='intents'::regclass)THEN ALTER TABLE intents ADD CONSTRAINT intents_conversation_contact_fk FOREIGN KEY(account_ref,conversation_id,contact_id)REFERENCES conversations(account_ref,id,contact_id)NOT VALID;END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='followups_conversation_contact_fk'AND conrelid='followups'::regclass)THEN ALTER TABLE followups ADD CONSTRAINT followups_conversation_contact_fk FOREIGN KEY(account_ref,conversation_id,contact_id)REFERENCES conversations(account_ref,id,contact_id)NOT VALID;END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='handoffs_conversation_contact_fk'AND conrelid='handoffs'::regclass)THEN ALTER TABLE handoffs ADD CONSTRAINT handoffs_conversation_contact_fk FOREIGN KEY(account_ref,conversation_id,contact_id)REFERENCES conversations(account_ref,id,contact_id)NOT VALID;END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='handoffs_source_conversation_fk'AND conrelid='handoffs'::regclass)THEN ALTER TABLE handoffs ADD CONSTRAINT handoffs_source_conversation_fk FOREIGN KEY(account_ref,source_id,conversation_id)REFERENCES inbound_messages(account_ref,id,conversation_id)NOT VALID;END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='followups_source_intent_context_fk'AND conrelid='followups'::regclass)THEN ALTER TABLE followups ADD CONSTRAINT followups_source_intent_context_fk FOREIGN KEY(account_ref,source_intent_id,contact_id,conversation_id)REFERENCES intents(account_ref,id,contact_id,conversation_id)NOT VALID;END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='followups_intent_context_fk'AND conrelid='followups'::regclass)THEN ALTER TABLE followups ADD CONSTRAINT followups_intent_context_fk FOREIGN KEY(account_ref,intent_id,contact_id,conversation_id)REFERENCES intents(account_ref,id,contact_id,conversation_id)NOT VALID;END IF;
END$$;

CREATE OR REPLACE FUNCTION intent_source_context_guard()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF NEW.kind='followup'THEN
  IF NOT EXISTS(SELECT 1 FROM followups f WHERE(f.account_ref,f.id,f.contact_id,f.conversation_id)=(NEW.account_ref,NEW.source_id,NEW.contact_id,NEW.conversation_id))THEN RAISE EXCEPTION'intent source context mismatch' USING ERRCODE='23503';END IF;
 ELSIF NOT EXISTS(SELECT 1 FROM inbound_messages m WHERE(m.account_ref,m.id,m.conversation_id)=(NEW.account_ref,NEW.source_id,NEW.conversation_id))THEN
  RAISE EXCEPTION'intent source context mismatch' USING ERRCODE='23503';
 END IF;
 RETURN NEW;
END$$;
DROP TRIGGER IF EXISTS intent_source_context ON intents;
CREATE TRIGGER intent_source_context BEFORE INSERT OR UPDATE OF account_ref,contact_id,conversation_id,source_id,kind ON intents FOR EACH ROW EXECUTE FUNCTION intent_source_context_guard();

CREATE OR REPLACE FUNCTION followup_authority_keys(acct text,contact uuid)RETURNS bigint[] LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$SELECT array_agg(k ORDER BY k)FROM(SELECT DISTINCT unnest(ARRAY[hashtextextended(acct||':control:stop',0),hashtextextended(acct||':consent:'||contact::text,0),hashtextextended(acct||':consent_templates',0),hashtextextended(acct||':handoff',0),hashtextextended(acct||':product_knowledge',0),hashtextextended(acct||':release_set',0),hashtextextended(acct||':retry',0),hashtextextended(acct||':sales_policy',0)])k)s$$;

CREATE OR REPLACE FUNCTION claim_handoff(t text,acct text,work uuid,n timestamptz DEFAULT now())RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$
DECLARE a record;h handoffs;cfg jsonb;v conversations;trusted_now timestamptz;lock_deadline timestamptz;
BEGIN
 SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR a.role NOT IN('runtime','scheduler')OR(a.role='runtime'AND(a.account_ref IS NULL OR(acct IS NOT NULL AND a.account_ref IS DISTINCT FROM acct)))OR(a.role='scheduler'AND acct IS NOT NULL AND a.account_ref IS NOT NULL AND a.account_ref IS DISTINCT FROM acct)THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;
 IF acct IS NULL THEN acct:=a.account_ref;END IF;SELECT*INTO h FROM handoffs WHERE(account_ref,id)=(acct,work);IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;
 PERFORM set_config('lock_timeout','1s',true);lock_deadline:=clock_timestamp()+interval'1s';BEGIN PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(acct,h.conversation_id);PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(acct,h.contact_id);SELECT*INTO h FROM handoffs WHERE(account_ref,id)=(acct,work)FOR UPDATE;EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"terminal":"denied","reason":"busy"}';END;
 trusted_now:=clock_timestamp();SELECT*INTO v FROM conversations WHERE(account_ref,id)=(acct,h.conversation_id);SELECT body INTO cfg FROM config_docs WHERE account_ref=acct AND kind='handoff'AND active;
 IF NOT EXISTS(SELECT 1 FROM accounts WHERE id=acct AND enabled)THEN RETURN'{"ok":false,"terminal":"denied","reason":"account_disabled"}';ELSIF v.lifecycle IN('opted_out','deleted')THEN UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL,next_attempt=NULL WHERE(account_ref,id)=(acct,work);RETURN jsonb_build_object('ok',false,'terminal','denied','reason',v.lifecycle);ELSIF cfg IS NULL THEN RETURN'{"ok":false,"terminal":"denied","reason":"missing_config"}';ELSIF h.state IN('acknowledged','suppressed')THEN RETURN jsonb_build_object('ok',false,'terminal','denied','reason','terminal_state','state',h.state);ELSIF h.state='claimed'AND h.claim_until>trusted_now THEN RETURN'{"ok":false,"terminal":"denied","reason":"already_claimed"}';ELSIF h.state='claimed'AND EXISTS(SELECT 1 FROM handoff_notification_attempts x WHERE(x.account_ref,x.handoff_id,x.attempt_no,x.claim)=(acct,work,h.attempts,h.claim))THEN RETURN'{"ok":false,"terminal":"denied","reason":"reconciliation_required"}';ELSIF h.state NOT IN('pending','claimed')THEN RETURN'{"ok":false,"terminal":"denied","reason":"invalid_state"}';ELSIF h.attempts>=(cfg->>'maxAttempts')::int THEN UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL,next_attempt=NULL WHERE(account_ref,id)=(acct,work);INSERT INTO handoff_notification_events(account_ref,handoff_id,attempt_no,outcome,result,next_attempt)VALUES(acct,work,h.attempts+1,NULL,'retry_exhausted',NULL)ON CONFLICT DO NOTHING;RETURN'{"ok":false,"terminal":"denied","reason":"retry_exhausted"}';ELSIF h.next_attempt>trusted_now THEN RETURN'{"ok":false,"terminal":"denied","reason":"backoff"}';END IF;
 UPDATE handoffs SET state='claimed',claim=gen_random_uuid(),claim_until=trusted_now+make_interval(secs=>(cfg->>'claimSeconds')::int),attempts=attempts+1 WHERE(account_ref,id)=(acct,work)RETURNING*INTO h;RETURN jsonb_build_object('ok',true,'terminal','claimed','account_ref',acct,'work_id',h.id,'claim',h.claim,'queue',h.queue,'deadline',h.deadline,'summary',handoff_summary_json(acct,work));
END$$;

CREATE OR REPLACE FUNCTION recheck_handoff(t text,acct text,work uuid,c uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$
DECLARE a record;h handoffs;life text;trusted_now timestamptz;lock_deadline timestamptz;
BEGIN SELECT x.role,x.account_ref,x.actor INTO a FROM auth_tokens x WHERE x.hash=encode(digest(t,'sha256'),'hex')AND x.revoked_at IS NULL AND x.expires_at>now()AND x.role IN('runtime','scheduler');IF NOT FOUND OR(a.role='runtime'AND(a.account_ref IS NULL OR a.account_ref IS DISTINCT FROM acct))OR(a.role='scheduler'AND a.account_ref IS NOT NULL AND a.account_ref IS DISTINCT FROM acct)THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;SELECT*INTO h FROM handoffs WHERE(account_ref,id)=(acct,work);IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;
 PERFORM set_config('lock_timeout','1s',true);lock_deadline:=clock_timestamp()+interval'1s';BEGIN PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(acct,h.conversation_id);PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(acct,h.contact_id);SELECT*INTO h FROM handoffs WHERE(account_ref,id)=(acct,work)FOR UPDATE;EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"terminal":"denied","reason":"busy"}';END;trusted_now:=clock_timestamp();IF h.state<>'claimed'OR h.claim IS DISTINCT FROM c OR h.claim_until<=trusted_now THEN RETURN'{"ok":false,"terminal":"denied","reason":"claim_mismatch"}';END IF;SELECT lifecycle INTO life FROM conversations WHERE(account_ref,id)=(acct,h.conversation_id);IF NOT EXISTS(SELECT 1 FROM accounts WHERE id=acct AND enabled)OR life IN('opted_out','deleted')OR NOT EXISTS(SELECT 1 FROM config_docs WHERE account_ref=acct AND kind='handoff'AND active)THEN UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL,next_attempt=NULL WHERE(account_ref,id)=(acct,work);RETURN jsonb_build_object('ok',false,'terminal','denied','reason',CASE WHEN life IN('opted_out','deleted')THEN life WHEN NOT EXISTS(SELECT 1 FROM accounts WHERE id=acct AND enabled)THEN'account_disabled'ELSE'missing_config'END);END IF;INSERT INTO handoff_notification_attempts(account_ref,handoff_id,attempt_no,claim)VALUES(acct,work,h.attempts,c)ON CONFLICT DO NOTHING;IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"adapter_already_started"}';END IF;RETURN jsonb_build_object('ok',true,'terminal','authorized','account_ref',acct,'work_id',work,'claim',c,'summary',handoff_summary_json(acct,work));END$$;

CREATE OR REPLACE FUNCTION finish_handoff(t text,acct text,work uuid,c uuid,outcome text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$
DECLARE a record;h handoffs;cfg jsonb;life text;trusted_now timestamptz;lock_deadline timestamptz;notification_result text;authority_reason text;started handoff_notification_attempts;prior handoff_notification_events;event_attempt int;
BEGIN SELECT x.role,x.account_ref,x.actor INTO a FROM auth_tokens x WHERE x.hash=encode(digest(t,'sha256'),'hex')AND x.revoked_at IS NULL AND x.expires_at>now()AND x.role IN('runtime','scheduler');IF NOT FOUND OR(a.role='runtime'AND(a.account_ref IS NULL OR a.account_ref IS DISTINCT FROM acct))OR(a.role='scheduler'AND a.account_ref IS NOT NULL AND a.account_ref IS DISTINCT FROM acct)THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;IF outcome IS NULL OR outcome NOT IN('success','retryable','failed')THEN RETURN'{"ok":false,"terminal":"denied","reason":"invalid_outcome"}';END IF;SELECT*INTO h FROM handoffs WHERE(account_ref,id)=(acct,work);IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;
 PERFORM set_config('lock_timeout','1s',true);lock_deadline:=clock_timestamp()+interval'1s';BEGIN PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(acct,h.conversation_id);PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(acct,h.contact_id);SELECT*INTO h FROM handoffs WHERE(account_ref,id)=(acct,work)FOR UPDATE;EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"terminal":"denied","reason":"busy"}';END;trusted_now:=clock_timestamp();SELECT*INTO started FROM handoff_notification_attempts x WHERE(x.account_ref,x.handoff_id,x.claim)=(acct,work,c);IF FOUND THEN IF started.started_at IS NULL THEN RETURN'{"ok":false,"terminal":"denied","reason":"reconciliation_required"}';END IF;event_attempt:=started.attempt_no;SELECT*INTO prior FROM handoff_notification_events e WHERE(e.account_ref,e.handoff_id,e.attempt_no)=(acct,work,event_attempt);IF FOUND THEN IF prior.outcome IS NOT DISTINCT FROM finish_handoff.outcome THEN RETURN jsonb_build_object('ok',true,'terminal',h.state,'next_attempt',h.next_attempt,'notificationResult',prior.result,'replayed',true);END IF;RETURN'{"ok":false,"terminal":"denied","reason":"outcome_conflict"}';END IF;IF NOT((h.state='claimed'AND h.claim IS NOT DISTINCT FROM c)OR h.state='suppressed')THEN RETURN'{"ok":false,"terminal":"denied","reason":"claim_mismatch"}';END IF;ELSE event_attempt:=h.attempts;IF h.state<>'claimed'OR h.claim IS DISTINCT FROM c OR h.claim_until<=trusted_now THEN RETURN'{"ok":false,"terminal":"denied","reason":"claim_mismatch"}';END IF;END IF;SELECT lifecycle INTO life FROM conversations WHERE(account_ref,id)=(acct,h.conversation_id);SELECT body INTO cfg FROM config_docs WHERE account_ref=acct AND kind='handoff'AND active;authority_reason:=CASE WHEN life IN('opted_out','deleted')THEN life WHEN NOT EXISTS(SELECT 1 FROM accounts WHERE id=acct AND enabled)THEN'account_disabled'WHEN cfg IS NULL THEN'missing_config'END;IF h.state='suppressed'OR authority_reason IS NOT NULL THEN notification_result:='authority_changed';UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL,next_attempt=NULL WHERE(account_ref,id)=(acct,work);ELSIF outcome='success'THEN notification_result:='delivered';UPDATE handoffs SET state='acknowledged',claim=NULL,claim_until=NULL,next_attempt=NULL WHERE(account_ref,id)=(acct,work);ELSIF outcome='retryable'AND h.attempts<(cfg->>'maxAttempts')::int THEN notification_result:='retry_scheduled';UPDATE handoffs SET state='pending',next_attempt=trusted_now+make_interval(secs=>(cfg->>'backoffSeconds')::int),claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);ELSE notification_result:=CASE WHEN outcome='retryable'THEN'retry_exhausted'ELSE'final_failure'END;UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL,next_attempt=NULL WHERE(account_ref,id)=(acct,work);END IF;SELECT*INTO h FROM handoffs WHERE(account_ref,id)=(acct,work);INSERT INTO handoff_notification_events(account_ref,handoff_id,attempt_no,outcome,result,next_attempt)VALUES(acct,work,event_attempt,finish_handoff.outcome,notification_result,h.next_attempt);RETURN jsonb_build_object('ok',true,'terminal',h.state,'next_attempt',h.next_attempt,'notificationResult',notification_result,'reason',authority_reason);END$$;

DROP FUNCTION IF EXISTS enforce_retention(text,text,timestamptz);
CREATE OR REPLACE FUNCTION enforce_retention(t text,acct text,n timestamptz DEFAULT now())RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;ret jsonb;message_count int;audit_count int;trusted_now timestamptz;BEGIN SELECT*INTO a FROM actor_for(t,'operator');IF NOT FOUND OR a.account_ref IS DISTINCT FROM acct THEN RETURN'{"ok":false,"reason":"wrong_account"}';END IF;trusted_now:=clock_timestamp();IF n IS NULL OR n>trusted_now THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;SELECT body INTO ret FROM config_docs WHERE account_ref=acct AND kind='retention'AND active;IF ret IS NULL THEN RETURN'{"ok":false,"reason":"missing_retention"}';END IF;PERFORM set_config('salesflow.retention_mode','on',true),set_config('salesflow.minimization_account',acct,true);UPDATE handoff_summaries s SET known_lead_details=(SELECT COALESCE(jsonb_agg(jsonb_set(x,'{excerpt}','"[deleted]"')),'[]')FROM jsonb_array_elements(s.known_lead_details)x)WHERE s.account_ref=acct AND s.source_id IN(SELECT id FROM inbound_messages WHERE account_ref=acct AND received_at<n-make_interval(days=>(ret->>'messageDays')::int))AND EXISTS(SELECT 1 FROM jsonb_array_elements(s.known_lead_details)x WHERE x->>'excerpt'<>'[deleted]');UPDATE inbound_messages SET body='[deleted]',processing_body='[deleted]',body_hash=encode(digest('[deleted]','sha256'),'hex'),contact_ref='[deleted]'WHERE account_ref=acct AND received_at<n-make_interval(days=>(ret->>'messageDays')::int)AND(body<>'[deleted]'OR processing_body<>'[deleted]'OR contact_ref<>'[deleted]');GET DIAGNOSTICS message_count=ROW_COUNT;DELETE FROM audit_events WHERE account_ref=acct AND at<n-make_interval(days=>(ret->>'auditDays')::int);GET DIAGNOSTICS audit_count=ROW_COUNT;PERFORM set_config('salesflow.retention_mode','off',true),set_config('salesflow.minimization_account','',true);INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'retention_enforced',ret->>'version',a.actor,jsonb_build_object('messagePurged',message_count,'auditPurged',audit_count,'messageDays',(ret->>'messageDays')::int,'auditDays',(ret->>'auditDays')::int));RETURN jsonb_build_object('ok',true,'terminal','retention_enforced','account_ref',acct,'retentionVersion',ret->>'version','messageDays',(ret->>'messageDays')::int,'auditDays',(ret->>'auditDays')::int,'messagePurged',message_count,'auditPurged',audit_count);END$$;

DROP FUNCTION IF EXISTS set_consent(text,text,uuid,text,text);
CREATE OR REPLACE FUNCTION set_consent(t text,acct text,c uuid,s text,e text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;prior timestamptz;at_time timestamptz;conv uuid;lock_deadline timestamptz;BEGIN SELECT*INTO a FROM actor_for(t,'runtime');IF NOT FOUND OR a.account_ref IS DISTINCT FROM acct THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;IF s IS NULL OR s NOT IN('granted','revoked')OR COALESCE(btrim(e),'')=''OR octet_length(e)>8192 OR NOT EXISTS(SELECT 1 FROM contacts WHERE(account_ref,id)=(acct,c))THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;PERFORM set_config('lock_timeout','5s',true);lock_deadline:=clock_timestamp()+interval'5s';BEGIN FOR conv IN SELECT id FROM conversations WHERE(account_ref,contact_id)=(acct,c)ORDER BY id LOOP PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_conversation(acct,conv);END LOOP;PERFORM followup_set_lock_deadline(lock_deadline);PERFORM followup_lock_authorities(acct,c);PERFORM 1 FROM contacts WHERE(account_ref,id)=(acct,c)FOR UPDATE;EXCEPTION WHEN lock_not_available THEN RETURN'{"ok":false,"reason":"busy"}';END;IF NOT FOUND THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;IF EXISTS(SELECT 1 FROM conversations WHERE(account_ref,contact_id,lifecycle)=(acct,c,'deleted'))OR EXISTS(SELECT 1 FROM deletion_requests WHERE(account_ref,contact_id,state)=(acct,c,'completed'))THEN RETURN'{"ok":false,"reason":"deleted"}';END IF;at_time:=clock_timestamp();SELECT max(occurred_at)INTO prior FROM consent_events WHERE(account_ref,contact_id)=(acct,c);at_time:=GREATEST(at_time,COALESCE(prior+interval'1 microsecond',at_time));INSERT INTO consent_events(account_ref,contact_id,status,evidence,occurred_at)VALUES(acct,c,s,e,at_time);IF s='revoked'THEN FOR conv IN SELECT id FROM conversations WHERE(account_ref,contact_id)=(acct,c)ORDER BY id LOOP PERFORM cancel_followups_for_conversation(acct,conv,'consent_revoked',NULL);END LOOP;END IF;RETURN jsonb_build_object('ok',true,'occurred_at',at_time);END$$;

REVOKE ALL ON SCHEMA salesflow FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA salesflow FROM PUBLIC,salesflow_runtime;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA salesflow FROM PUBLIC,salesflow_runtime;
GRANT USAGE ON SCHEMA salesflow TO salesflow_runtime;
GRANT EXECUTE ON FUNCTION ingest(text,jsonb),ingest_meta(text,jsonb),record_ingress_rejection(text,text,text),complete_turn(text,text,uuid),set_consent(text,text,uuid,text,text),replace_contact_identifier(text,text,uuid,text,text,text,text),set_account_enabled(text,text,boolean),set_control(text,text,text,jsonb),set_conversation_state(text,text,uuid,text,text,boolean),claim_dispatch(text,text,uuid,timestamptz),begin_provider_call(text,text,uuid,uuid),finish_dispatch(text,text,uuid,uuid,text),callback(text,jsonb),schedule_followups(text,timestamptz),schedule_work(text,timestamptz),claim_handoff(text,text,uuid,timestamptz),recheck_handoff(text,text,uuid,uuid),finish_handoff(text,text,uuid,uuid,text),read_conversation_history(text,text,uuid),read_conversation_history_request(text,text),operations(text,text,jsonb),enforce_retention(text,text,timestamptz) TO salesflow_runtime;
ALTER DEFAULT PRIVILEGES FOR ROLE salesflow_owner IN SCHEMA salesflow REVOKE ALL ON TABLES FROM PUBLIC;
RESET ROLE;
COMMIT;
